from manim import *
from forge.beats import ForgeScene, beat
from fractions import Fraction

class WordleEntropyOptimization(ForgeScene):

    @beat("Initialize the restricted word pool", seconds=3, narration="For a given proposed second guess, something like 'kitty', what's the distribution across all patterns in that restricted case?")
    def setup_scene(self):
        self.words = ["APPLE", "BEACH", "CHART", "DREAM", "EARTH", "FLAME"]
        self.word_list = VGroup(*[Text(w, font_size=32) for w in self.words]).arrange(DOWN, buff=0.2).to_edge(LEFT, buff=1)
        self.title = Text("Restricted Pool (All-Gray)", font_size=36).to_edge(UP)
        self.play(FadeIn(self.title), LaggedStart(*[Write(w) for w in self.word_list], lag_ratio=0.1))

    @beat("Visualize the pattern distribution", seconds=3, narration="We look at the distribution of outcomes for a guess like 'kitty', restricted only to the words that would produce all grays for 'soar'.")
    def show_distribution(self):
        self.dist_bars = VGroup(*[
            Rectangle(height=0.3, width=i * 0.5 + 0.5, color=BLUE_B, fill_opacity=0.6)
            for i in range(1, 5)
        ]).arrange(DOWN, buff=0.1).next_to(self.word_list, RIGHT, buff=2)
        self.dist_labels = VGroup(*[MathTex(f"p_{i}") for i in range(1, 5)]).next_to(self.dist_bars, LEFT)
        self.play(Create(self.dist_bars), Write(self.dist_labels))

    @beat("Define the entropy formula", seconds=3, narration="And then we measure the flatness of that distribution using this expected information formula.")
    def show_formula(self):
        self.formula = MathTex(r"H = -\sum p_i \log_2(p_i)", font_size=48).to_edge(RIGHT, buff=1)
        self.highlight = SurroundingRectangle(self.dist_bars, color=YELLOW)
        self.play(Write(self.formula), Create(self.highlight))

    @beat("Scale to all possible guesses", seconds=3, narration="We do that for all 13,000 possible words that we could use as a second guess.")
    def scale_process(self):
        n_words = 13000
        self.counter = Integer(0).to_edge(DOWN)
        self.label = Text("Words Evaluated:", font_size=24).next_to(self.counter, LEFT)
        self.play(FadeOut(self.highlight), FadeOut(self.word_list), FadeOut(self.dist_bars), FadeOut(self.dist_labels))
        self.play(Write(self.label), ChangeDecimalToValue(self.counter, n_words, run_time=2, rate_func=linear))

    @beat("Identify the optimal guess", seconds=3, narration="Doing this we can find the optimal second guess in that scenario...")
    def show_optimal(self):
        self.optimal_text = Text("Optimal Guess: 'SALET'", color=GREEN, font_size=40).move_to(ORIGIN)
        self.play(FadeIn(self.optimal_text, scale=1.5))

    @beat("Display expected information", seconds=3, narration="...and the amount of information we were expected to get from it.")
    def show_information(self, info_val=4.2):
        self.info_text = Text(f"Expected Information: {info_val} bits", font_size=32).next_to(self.optimal_text, DOWN)
        self.play(Write(self.info_text))
        self.play(Indicate(self.info_text))
