from manim import *
from forge.beats import ForgeScene, beat
import numpy as np

class CyclicPointRotation(ForgeScene):
    def get_points(self, n=8):
        return [np.array([2 * np.cos(2 * np.pi * i / n), 2 * np.sin(2 * np.pi * i / n), 0]) for i in range(n)]

    @beat("Initialize the points on a circle", seconds=3, narration="Again, the logic is that it's parallel to its starting position.")
    def init_points(self):
        self.n = 8
        self.points = self.get_points(self.n)
        self.dots = VGroup(*[Dot(p, color=BLUE) for p in self.points])
        self.circle = Circle(radius=2, color=WHITE, stroke_opacity=0.3)
        self.play(Create(self.circle), LaggedStart(*[GrowFromCenter(d) for d in self.dots]))

    @beat("Show the rotation vector", seconds=3, narration="And if it was passing through any other point, the number of points on a given side would have to be different.")
    def show_vector(self):
        self.arrow = Arrow(start=ORIGIN, end=self.points[1], color=YELLOW)
        self.label = MathTex(r"\vec{v}").next_to(self.arrow.get_center(), UP)
        self.play(GrowArrow(self.arrow), Write(self.label))

    @beat("Animate the cycle", seconds=4, narration="So once more, we have a cycle which hits all of the points, and which ends in the same position where it started.")
    def rotate_points(self):
        self.group = VGroup(*self.dots)
        self.play(Rotate(self.group, angle=2 * np.pi, about_point=ORIGIN, run_time=3, rate_func=linear))

    @beat("Highlight the 360 degree completion", seconds=3, narration="This time it takes 360 degrees, but that doesn't matter.")
    def show_angle(self):
        self.angle_arc = Arc(radius=0.5, angle=2 * np.pi, color=RED)
        self.angle_text = MathTex("360^\\circ").next_to(self.angle_arc, RIGHT)
        self.play(Create(self.angle_arc), Write(self.angle_text))

    @beat("Show infinite continuation", seconds=3, narration="As the cycle continues it'll hit all the points infinitely many times.")
    def infinite_loop(self):
        self.play(FadeOut(self.angle_arc), FadeOut(self.angle_text))
        self.play(Rotate(self.group, angle=4 * np.pi, about_point=ORIGIN, run_time=3, rate_func=linear))

    @beat("Final state representation", seconds=3, narration="It is a continuous, repeating traversal of the entire set.")
    def final_state(self):
        self.status = Text("Infinite Traversal", font_size=36, color=GREEN).to_edge(RIGHT)
        self.play(Write(self.status))
        self.play(Indicate(self.group))
