from manim import *
from forge.beats import ForgeScene, beat

class DrostePeriodicity(ForgeScene):

    @beat("This would happen for any image.", seconds=3, narration="This would happen for any image.")
    def show_base_image(self):
        self.frame_box = Rectangle(width=4.0, height=3.0, color=BLUE_C, stroke_width=3).shift(LEFT * 3.5)
        self.label = Text("Base Image", font_size=28, color=BLUE_C).next_to(self.frame_box, UP)
        self.play(Create(self.frame_box), Write(self.label), run_time=2.0)

    @beat("And then in this special case of a Droste image, it's also periodic horizontally", seconds=3, narration="And then in this special case of a Droste image, it's also periodic horizontally, because the Droste image repeats as you zoom in.")
    def show_droste_tiles(self):
        self.tiles = VGroup(*[
            Rectangle(width=4.0 * (0.5**i), height=3.0 * (0.5**i), color=TEAL, stroke_width=2)
            .shift(LEFT * 3.5 + RIGHT * (i * 0.5))
            for i in range(4)
        ])
        self.play(ReplacementTransform(self.frame_box, self.tiles), run_time=2.5)

    @beat("This doubly periodic property is what we'll ultimately take advantage of for the final result.", seconds=3, narration="This doubly periodic property is what we'll ultimately take advantage of for the final result.")
    def show_grid_property(self):
        self.grid = VGroup(*[
            Square(side_length=1.5, stroke_width=1, stroke_color=YELLOW_A, fill_opacity=0.2, fill_color=YELLOW_E)
            .shift(LEFT * 4.5 + RIGHT * (x * 1.5) + UP * (y * 1.5))
            for x in range(3) for y in range(2)
        ])
        self.grid_label = Text("Doubly Periodic", font_size=32, color=YELLOW_C).to_edge(UP)
        self.play(FadeOut(self.tiles), FadeIn(self.grid, lag_ratio=0.1), Write(self.grid_label), run_time=2.5)

    @beat("And we now have all the foundation we need.", seconds=3, narration="And we now have all the foundation we need.")
    def show_foundation_summary(self):
        self.check_list = VGroup(
            Text("✓ Zoom symmetry", font_size=26, color=GREEN_C),
            Text("✓ Horizontal periodicity", font_size=26, color=GREEN_C),
            Text("✓ Log-polar coordinates", font_size=26, color=GREEN_C)
        ).arrange(DOWN, aligned_edge=LEFT).shift(RIGHT * 2.5 + UP * 1.0)
        self.play(FadeOut(self.grid), FadeOut(self.grid_label), FadeIn(self.check_list, lag_ratio=0.2), run_time=2.5)

    @beat("I can now finally describe for you the function", seconds=3, narration="I can now finally describe for you the function that turns the Droste zoom")
    def show_function_mapping(self):
        self.math_expr = MathTex(r"f(z) = e^{2\pi i \frac{\log z}{\log r}}", font_size=40, color=ORANGE).shift(RIGHT * 3.0 + DOWN * 1.0)
        self.arrow = Arrow(LEFT * 0.5, RIGHT * 1.5, color=WHITE).shift(DOWN * 1.0)
