    @beat("into this Escher-style self-contained loop.", seconds=3, narration="into this Escher-style self-contained loop.")
    def show_final_loop(self):
        self.ring = Circle(radius=1.5, color=PINK, stroke_width=6).shift(RIGHT * 3.0)
        self.ring_label = Text("Escher Loop", font_size=28, color=PINK).next_to(self.ring, DOWN)
        self.play(ReplacementTransform(self.math_expr, self.ring), Write(self.ring_label), FadeOut(self.check_list), run_time=2.5)
