from manim import *
from forge.beats import ForgeScene, beat
from fractions import Fraction

class DiceSumGrid(ForgeScene):
    @beat("Initialize the dice grid", seconds=3, narration="Each of your two dice has six different possible outcomes, which gives us a total of 36 distinct possible pairs of outcomes.")
    def setup_grid(self):
        self.grid = VGroup()
        for i in range(1, 7):
            for j in range(1, 7):
                pair = Text(f"({i},{j})", font_size=24)
                pair.move_to(np.array([-4 + i * 1.1, -3 + j * 0.9, 0]))
                self.grid.add(pair)
        self.play(FadeIn(self.grid, lag_ratio=0.05), run_time=2.5)

    @beat("Highlight the total count", seconds=3, narration="And if we just look through them all we can count up how many pairs have a given sum.")
    def count_total(self):
        count = len(self.grid)
        label = Text(f"Total pairs: {count}", color=BLUE).to_edge(RIGHT, buff=1)
        self.play(Write(label), run_time=2)
        self.total_label = label

    @beat("Arrange into a visual matrix", seconds=3, narration="And arranging all the pairs in a grid like this...")
    def arrange_grid(self):
        new_grid = VGroup()
        for i in range(1, 7):
            for j in range(1, 7):
                idx = (i-1) * 6 + (j-1)
                new_grid.add(self.grid[idx])

        self.play(
            new_grid.animate.arrange_in_grid(rows=6, cols=6, buff=0.2).center().shift(LEFT*2),
            run_time=2.5
        )

    @beat("Highlight a diagonal", seconds=3, narration="...one pretty nice thing is that all of the pairs that have a constant sum...")
    def highlight_diagonal(self):
        # Sum of 7: (1,6), (2,5), (3,4), (4,3), (5,2), (6,1)
        diag = VGroup(*[self.grid[i*6 + (5-i)] for i in range(6)])
        self.play(diag.animate.set_color(YELLOW), run_time=2)
        self.diag = diag

    @beat("Show the constant sum label", seconds=3, narration="...are visible along one of these different diagonals.")
    def show_sum(self):
        sum_val = 7
        sum_text = Text(f"Sum = {sum_val}", color=YELLOW).next_to(self.diag, RIGHT)
        self.play(Write(sum_text), run_time=2)

    @beat("Highlight another diagonal", seconds=3, narration="For example, a sum of four would be these three pairs.")
    def highlight_another(self):
        # Sum of 4: (1,3), (2,2), (3,1)
        diag2 = VGroup(self.grid[0*6 + 2], self.grid[1*6 + 1], self.grid[2*6 + 0])
        self.play(
            FadeOut(self.diag),
            diag2.animate.set_color(RED),
            run_time=2
        )
        self.wait(1)
