import numpy as np

class LinearSystemVisualization(ForgeScene):
    @beat("Introduce the system of equations", seconds=3, narration="Alright so the setup here will be some linear system of equations, say with two unknowns x and y and two equations.")
    def show_equations(self):
        self.eqs = MathTex(
            r"\begin{cases} 2x + y = -4 \\ x - y = -2 \end{cases}",
            font_size=42
        ).to_edge(LEFT, buff=1.5)
        self.play(Write(self.eqs))

    @beat("Mention scalability", seconds=3, narration="In principle everything we're talking about will also work for systems with larger number of unknowns and the same number of equations, but for simplicity a smaller example is just nicer to hold in our heads.")
    def show_scalability(self):
        more_vars = MathTex(r"\dots + a_{nn}x_n = b_n", font_size=36, color=GRAY).next_to(self.eqs, DOWN)
        self.play(FadeIn(more_vars))
        self.wait(1)
        self.play(FadeOut(more_vars))

    @beat("Introduce matrix notation", seconds=3, narration="So as I talked about in a previous video you can think of this setup geometrically as a certain known matrix transforming an unknown vector (x, y)...")
    def matrix_setup(self):
        self.matrix_eq = MathTex(
            r"\begin{pmatrix} 2 & 1 \\ 1 & -1 \end{pmatrix}",
            r"\begin{pmatrix} x \\ y \end{pmatrix}",
            r"=",
            r"\begin{pmatrix} -4 \\ -2 \end{pmatrix}",
            font_size=42
        ).to_edge(RIGHT, buff=1)
        self.play(ReplacementTransform(self.eqs.copy(), self.matrix_eq))

    @beat("Highlight the transformation components", seconds=3, narration="...where you know what the output is going to be, in this case (-4, -2).")
    def highlight_output(self):
        output_vec = self.matrix_eq[3]
        box = SurroundingRectangle(output_vec, color=YELLOW, buff=0.1)
        self.play(Create(box))
        self.play(Indicate(output_vec))
        self.wait(1)

    @beat("Show the grid transformation", seconds=4, narration="Geometrically, this matrix maps the basis vectors and transforms the entire plane.")
    def show_grid(self):
        self.grid = NumberPlane(x_range=[-6, 2], y_range=[-4, 4], axis_config={"include_numbers": False})
        self.play(FadeIn(self.grid))

        # Matrix: [[2, 1], [1, -1]]
        matrix = [[2, 1], [1, -1]]
        self.play(self.grid.animate.apply_matrix(matrix), run_time=2)

    @beat("Show the target vector", seconds=3, narration="We are looking for the specific input vector that lands exactly on our target (-4, -2).")
    def show_target(self):
        target = Dot(color=YELLOW).move_to(self.grid.c2p(-4, -2))
        label = MathTex(r"(-4, -2)", font_size=30, color=YELLOW).next_to(target, UP)
        self.play(GrowFromCenter(target), Write(label))
        self.play(Indicate(target))
