from manim import *
from forge.beats import ForgeScene, beat

class LaplaceLinearity(ForgeScene):
    @beat("Initialize the expression", seconds=3, narration="What you can do next from here is break this outer expression into two different pieces.")
    def init_expr(self):
        self.expr = MathTex(r"\mathcal{L}\{\cos(t)\} = \mathcal{L}\left\{\frac{e^{it} + e^{-it}}{2}\right\}")
        self.play(Write(self.expr))
        self.wait(1)

    @beat("Split the expression", seconds=3, narration="One that looks like half times the transform of e^(it), and another which looks like half times the transform of e^(-it).")
    def split_expr(self):
        self.split = MathTex(
            r"\mathcal{L}\{\cos(t)\} =", 
            r"\frac{1}{2}\mathcal{L}\{e^{it}\}", 
            r"+", 
            r"\frac{1}{2}\mathcal{L}\{e^{-it}\}"
        ).scale(0.9)
        self.play(Transform(self.expr, self.split))

    @beat("Define linearity", seconds=4, narration="In the lingo, the way that you would phrase this is that the Laplace transform is linear.")
    def define_linearity(self):
        self.title = Text("Linearity", font_size=36, color=BLUE).to_edge(UP)
        self.rect = SurroundingRectangle(self.expr, color=YELLOW)
        self.play(Write(self.title), Create(self.rect))

    @beat("Show general property", seconds=4, narration="Meaning if you have a scaled sum of some stuff on the inside...")
    def show_property_in(self):
        self.general = MathTex(r"\mathcal{L}\{a \cdot f(t) + b \cdot g(t)\}")
        self.play(FadeOut(self.expr, self.rect), FadeIn(self.general))

    @beat("Show result of linearity", seconds=4, narration="...you can break everything apart to the same scaled sum of the transforms of those inner parts.")
    def show_property_out(self):
        self.result = MathTex(r"= a \cdot \mathcal{L}\{f(t)\} + b \cdot \mathcal{L}\{g(t)\}")
        self.group = VGroup(self.general, self.result).arrange(DOWN)
        self.play(Transform(self.general, self.group[0]), Write(self.result))

    @beat("Final summary", seconds=3, narration="This property of linearity is what makes the Laplace transform so incredibly powerful for solving differential equations.")
    def summary(self):
        self.box = SurroundingRectangle(self.result, color=GREEN)
        self.play(Create(self.box))
        self.wait(2)
