from manim import *
from forge.beats import ForgeScene, beat
from fractions import Fraction

class PigeonholePrinciple(ForgeScene):

    @beat("Introduce 4 pigeons and 3 holes", seconds=3, narration="Imagine we have four pigeons trying to roost in just three holes.")
    def setup_scene(self):
        # 3 containers (pigeonholes)
        self.holes = VGroup(*[
            RoundedRectangle(corner_radius=0.1, width=1.5, height=2.5, stroke_color=BLUE_C, stroke_width=3)
            for _ in range(3)
        ]).arrange(RIGHT, buff=0.8).move_to([-1.5, 0, 0])

        # 4 items (pigeons)
        self.pigeons = VGroup(*[
            Circle(radius=0.35, color=YELLOW_C, fill_opacity=0.8)
            for _ in range(4)
        ])

        # Place pigeons initially above their respective holes, with one extra
        for i, p in enumerate(self.pigeons):
            p.move_to(self.holes[i % 3].get_center() + UP * 1.8)

        self.play(
            LaggedStart(*[FadeIn(h, scale=0.8) for h in self.holes], lag_ratio=0.1),
            LaggedStart(*[FadeIn(p, scale=0.5) for p in self.pigeons], lag_ratio=0.1),
            run_time=2.5
        )

    @beat("Distribute pigeons and show collision", seconds=3, narration="If every hole takes at most one, we run out of holes. The fourth pigeon forces a collision.")
    def distribute_and_collide(self):
        # Move pigeons into holes: first 3 go to holes 0, 1, 2. The 4th shares hole 0.
        target_positions = [
            self.holes[0].get_center() + UP * 0.5,
            self.holes[1].get_center() + UP * 0.5,
            self.holes[2].get_center() + UP * 0.5,
            self.holes[0].get_center() + DOWN * 0.5 # shared hole 0
        ]

        animations = [
            self.pigeons[i].animate.move_to(target_positions[i])
            for i in range(4)
        ]

        # Computed count for label
        num_pigeons = len(self.pigeons)
        num_holes = len(self.holes)

        label = Text(
            f"{num_pigeons} pigeons > {num_holes} holes\n-> At least 1 shared!",
            font_size=28,
            color=YELLOW_C
        ).to_edge(RIGHT, buff=0.8)

        self.play(
            *animations,
            Write(label),
            run_time=2.5
        )
