from manim import *
from forge.beats import ForgeScene, beat

class LaplaceSecondDerivative(ForgeScene):
    @beat("Initialize the equation for the first derivative", seconds=3, narration="And then for the second derivative, what should that look like? This is actually a good chance to pause and try it out as an exercise.")
    def setup_formula(self):
        self.eq = MathTex(r"\mathcal{L}\{x''(t)\} = ?").scale(1.5)
        self.play(Write(self.eq))
        self.wait(1)

    @beat("Show the rule applied once", seconds=4, narration="It basically looks like applying that key rule we just talked about, but twice in a row.")
    def rule_step(self):
        rule = MathTex(r"\mathcal{L}\{x'(t)\} = sX(s) - x(0)").scale(1.2).to_edge(LEFT)
        self.play(Transform(self.eq, rule))
        self.wait(2)

    @beat("Derive the second derivative term", seconds=4, narration="Applying it once, you get that the transform of the second derivative should look like s times the transform of the first derivative, all minus x prime of zero.")
    def derive_second(self):
        step = MathTex(
            r"\mathcal{L}\{x''(t)\} = s \cdot \mathcal{L}\{x'(t)\} - x'(0)"
        ).scale(1.1)
        self.play(ReplacementTransform(self.eq, step))
        self.wait(2)

    @beat("Substitute the first derivative transform", seconds=4, narration="Substituting the first derivative's transform, we get s times the quantity sX(s) minus x(0).")
    def substitution(self):
        full = MathTex(
            r"\mathcal{L}\{x''(t)\} = s(sX(s) - x(0)) - x'(0)"
        ).scale(1.1)
        self.play(Transform(self.eq, full))
        self.wait(2)

    @beat("Expand the expression", seconds=4, narration="Distributing that s gives us s squared times X(s), minus s times x(0), minus x prime of zero.")
    def expansion(self):
        expanded = MathTex(
            r"\mathcal{L}\{x''(t)\} = s^2X(s) - sx(0) - x'(0)"
        ).scale(1.1)
        self.play(Transform(self.eq, expanded))
        self.wait(2)

    @beat("Highlight initial velocity", seconds=4, narration="That term is the same as the initial velocity, so I'll write it as v naught.")
    def final_label(self):
        final = MathTex(
            r"\mathcal{L}\{x''(t)\} = s^2X(s) - sx(0) - v_0"
        ).scale(1.1)
        v_box = SurroundingRectangle(final[-1], color=YELLOW)
        label = Text("v_0", color=YELLOW).next_to(v_box, DOWN)

        self.play(Transform(self.eq, final))
        self.play(Create(v_box), Write(label))
        self.wait(2)
