                    c = Cube(side_length=0.4, fill_opacity=0.8, fill_color=BLUE_E, stroke_width=1)
                    c.move_to(np.array([x - 1, y - 1, z - 1]) * 0.45)
                    self.cubes.add(c)
        self.play(FadeIn(self.cubes, lag_ratio=0.05), run_time=3.0)

    @beat("Fade out 3D cubes and fade in 2D squares", seconds=3, narration="What I like about this is that we have this purely two-dimensional question...")
    def show_2d_flat(self):
        flat_squares = VGroup()
        for i in range(self.n * self.n):
            sq = Square(side_length=0.4)
            sq.set_fill(TEAL_D, opacity=0.8)
            sq.set_stroke(WHITE, width=1)
            row = i // self.n
            col = i % self.n
            sq.move_to(np.array([(col - 1) * 0.45, (row - 1) * 0.45, 0]))
            flat_squares.add(sq)

        self.play(
            FadeOut(self.cubes),
            FadeIn(flat_squares),
            run_time=2.0
        )
        self.flat_squares = flat_squares

    @beat("Return to 3D perspective", seconds=3, narration="...and a very nice insight came from thinking as three-dimensional creatures...")
    def return_to_3d(self):
        self.play(
            FadeOut(self.flat_squares),
            FadeIn(self.cubes),
            run_time=2.0
        )

    @beat("Display the cubic formula", seconds=3, narration="...but the fact that the numerical answer to this question has that little cube in it...")
    def highlight_formula(self):
        total = self.n ** 3
        self.formula = MathTex(f"n^3 = {self.n}^3 = {total}", font_size=48, color=YELLOW)
        self.formula.to_corner(UL)
        self.play(Write(self.formula), run_time=2.0)

    @beat("Pulse the cube structure", seconds=3, narration="...is an indication that the three-dimensionality really is baked into the puzzle itself...")
    def pulse_structure(self):
        self.play(self.cubes.animate.set_fill(ORANGE), run_time=1.0)
        self.play(self.cubes.animate.set_fill(BLUE_E), run_time=1.0)

    @beat("Final zoom to emphasize the structure", seconds=3, narration="...it's not coming from some bias that we have as three-dimensional creatures.")
    def final_zoom(self):
        self.play(self.cubes.animate.scale(1.3), run_time=2.5)
