from manim import *
from forge.beats import ForgeScene, beat

class MatrixComposition(ForgeScene):
    def get_matrix_mob(self, data, label=None):
        m = Matrix(data, h_buff=0.8, v_buff=0.5).scale(0.7)
        group = VGroup(m)
        if label:
            l = MathTex(label).scale(0.8).next_to(m, UP)
            group.add(l)
        return group

    @beat("Introduce M2 and the input vector", seconds=3, narration="Then, when we apply M2 to that vector, you can work out the matrix-vector product.")
    def show_m2_product(self):
        m2 = [[0, -1], [1, 0]]
        v = [[0], [1]]
        res = [[-1], [0]]
        self.m2_mob = self.get_matrix_mob(m2, "M_2").shift(LEFT * 3)
        self.v_mob = self.get_matrix_mob(v, "\\vec{v}").next_to(self.m2_mob, RIGHT)
        self.eq = MathTex("=").next_to(self.v_mob, RIGHT)
        self.res = self.get_matrix_mob(res).next_to(self.eq, RIGHT)
        self.play(FadeIn(self.m2_mob), FadeIn(self.v_mob), Write(self.eq), FadeIn(self.res), run_time=2.5)

    @beat("Highlight the result as the second column", seconds=3, narration="which becomes the second column of our composition matrix.")
    def highlight_result(self):
        # Using a simple rectangle instead of SurroundingRectangle to avoid alignment issues
        box = Rectangle(color=YELLOW, width=1.5, height=2.0).move_to(self.res.get_center())
        self.play(Create(box), run_time=1.5)
        self.wait(1.5)

    @beat("Clear screen for variable matrices", seconds=2, narration="Let me talk through that same process again,")
    def clear_for_variables(self):
        self.play(FadeOut(*self.mobjects), run_time=1.5)

    @beat("Introduce variable matrices", seconds=3, narration="but this time I'll show variable entries in each matrix,")
    def show_variables(self):
        m1_vars = [["a", "b"], ["c", "d"]]
        m2_vars = [["e", "f"], ["g", "h"]]
        self.m1 = self.get_matrix_mob(m1_vars, "M_1").shift(LEFT * 2.5)
        self.m2 = self.get_matrix_mob(m2_vars, "M_2").next_to(self.m1, RIGHT, buff=1.0)
        self.play(Write(self.m1), Write(self.m2), run_time=2)

    @beat("Show the symbolic multiplication", seconds=3, narration="just to show that the same line of reasoning works for any matrices.")
    def show_symbolic_product(self):
        res = [["ae+bg", "af+bh"], ["ce+dg", "cf+dh"]]
        self.res_mob = self.get_matrix_mob(res, "M_1 M_2").shift(RIGHT * 2.5)
        self.play(Write(self.res_mob), run_time=2)

    @beat("Final look at the result", seconds=2, narration="The logic holds regardless of the specific numbers.")
    def final_view(self):
        self.play(Indicate(self.res_mob), run_time=1.5)
