    @beat("Contrast the quarter turn with modern conventions.", seconds=4,
          narration="What we would call today pi halves, or tau fourths.")
    def comparison(self):
        modern_label = MathTex(r"\frac{\pi}{2} \text{ or } \frac{\tau}{4}", font_size=36).next_to(self.circle, RIGHT, buff=1)
        brace = Brace(self.line, DOWN, color=YELLOW)
        brace_text = brace.get_text("Quarter turn")

        self.play(Create(brace), Write(brace_text))
        self.play(Write(modern_label))

    @beat("Summarize the fluidity of historical notation.", seconds=3,
          narration="It serves as a reminder that mathematical symbols were not always set in stone.")
    def conclusion(self):
        summary = Text("Notation evolves.", font_size=40).to_edge(UP)
        self.play(Write(summary))
        self.play(FadeOut(self.circle), FadeOut(self.line), FadeOut(self.label), 
                  FadeOut(self.euler_name), FadeOut(self.euler_box, run_time=0))
