from manim import *
from forge.beats import ForgeScene, beat
import numpy as np

class ConformalZoom(ForgeScene):
    def get_grid(self, color=BLUE, opacity=0.3):
        return VGroup(*[
            Line(start=[-4, y, 0], end=[4, y, 0], color=color, stroke_opacity=opacity)
            for y in np.linspace(-4, 4, 17)
        ], *[
            Line(start=[x, -4, 0], end=[x, 4, 0], color=color, stroke_opacity=opacity)
            for x in np.linspace(-4, 4, 17)
        ])

    @beat("Introduce the mapping", seconds=3, narration="Squares remain approximately square.")
    def show_mapping(self):
        self.grid = self.get_grid()
        self.square = Square(side_length=1.5, color=YELLOW).shift(LEFT*1.5 + UP*1)
        self.output_grid = self.get_grid(color=RED)
        # Apply a simple non-linear mapping: f(z) = z^2 (simplified for visualization)
        self.play(Create(self.grid), Create(self.square))
        self.wait(1)

    @beat("Highlight the distortion", seconds=3, narration="Okay, maybe this example square that I'm highlighting doesn't exactly look square in the output.")
    def show_distortion(self):
        distorted_square = self.square.copy().apply_complex_function(lambda z: z**2)
        distorted_square.set_color(ORANGE)
        self.play(Transform(self.square.copy(), distorted_square), run_time=2)
        self.wait(1)

    @beat("Explain the limit", seconds=3, narration="To be clear, this conformal property that I'm talking about is a limiting one.")
    def show_limit_text(self):
        text = Text("Limiting Property", font_size=36).to_edge(UP)
        self.play(Write(text))
        self.wait(2)

    @beat("Zoom in setup", seconds=3, narration="A particular square might not exactly become square, but the idea is that as you zoom in more and more.")
    def zoom_setup(self):
        self.zoom_rect = Rectangle(width=0.5, height=0.5, color=WHITE).move_to(self.square.get_center())
        self.play(Create(self.zoom_rect))
        self.wait(2)

    @beat("Zoom animation", seconds=4, narration="choosing square regions from the input space that are smaller and smaller.")
    def perform_zoom(self):
        self.play(
            self.grid.animate.scale(4).move_to(ORIGIN),
            self.zoom_rect.animate.scale(4),
            run_time=3
        )

    @beat("Final approximation", seconds=3, narration="the resulting output will indeed be better and better approximated by a square.")
    def final_result(self):
        final_shape = self.zoom_rect.copy().apply_complex_function(lambda z: z**2)
        final_shape.set_color(GREEN)
        self.play(Transform(self.zoom_rect.copy(), final_shape), run_time=2)
        self.wait(1)
