from manim import *
from forge.beats import ForgeScene, beat

class DiffusionSteering(ForgeScene):
    @beat("Initialize the latent space vectors", seconds=3, narration="Our WAN video generation model takes this guidance approach one step further.")
    def init_vectors(self):
        self.plane = NumberPlane(x_range=[-4, 4], y_range=[-3, 3], axis_config={"include_ticks": False})
        self.conditioned = Vector([2, 1.5], color=BLUE).shift(LEFT * 2)
        self.label_c = MathTex(r"\mathbf{v}_{cond}").next_to(self.conditioned, UP)
        self.play(Create(self.plane), GrowArrow(self.conditioned), Write(self.label_c))

    @beat("Introduce the negative prompt vector", seconds=3, narration="Instead of subtracting the output of an unconditioned model, the WAN team uses what's known as a negative prompt.")
    def negative_prompt(self):
        self.negative = Vector([-1, -2], color=RED).shift(LEFT * 2)
        self.label_n = MathTex(r"\mathbf{v}_{neg}", color=RED).next_to(self.negative, DOWN)
        self.play(GrowArrow(self.negative), Write(self.label_n))

    @beat("Show the subtraction operation", seconds=3, narration="where they specifically write out all the features they don't want, and then subtract the resulting vector.")
    def subtract(self):
        self.diff = Vector([3, 3.5], color=YELLOW).shift(LEFT * 2)
        self.label_d = MathTex(r"\mathbf{v}_{cond} - \mathbf{v}_{neg}", color=YELLOW).scale(0.8).to_edge(RIGHT)
        self.play(
            FadeOut(self.label_c, self.label_n),
            ReplacementTransform(VGroup(self.conditioned, self.negative), self.diff),
            Write(self.label_d)
        )

    @beat("Amplify the result", seconds=3, narration="and amplify the result, steering the diffusion process away from these unwanted features.")
    def amplify(self):
        self.amplified = Vector([4.5, 5.25], color=GREEN).shift(LEFT * 2)
        self.label_a = MathTex(r"\text{Amplify}(\mathbf{v}_{diff})", color=GREEN).next_to(self.label_d, DOWN)
        self.play(
            self.diff.animate.set_opacity(0.3),
            GrowArrow(self.amplified),
            Write(self.label_a)
        )

    @beat("Visualize the steering path", seconds=3, narration="steering the diffusion process away from these unwanted features.")
    def steering(self):
        self.path = CurvedArrow(start_point=LEFT * 2, end_point=self.amplified.get_end(), color=WHITE)
        self.dot = Dot(color=YELLOW).move_to(self.amplified.get_end())
        self.play(Create(self.path), FadeIn(self.dot))

    @beat("Final summary state", seconds=2, narration="This steers the diffusion process away from unwanted features.")
    def final(self):
        self.play(FadeOut(self.plane, self.path, self.dot, self.diff, self.amplified, self.label_d, self.label_a))
        self.wait(1)
