import numpy as np

class InterferometryStillness(ForgeScene):
    @beat("Introduce the interference pattern and the wavelength threshold", seconds=4,
          narration="If their position shifts by an amount comparable to the wavelength of the light, a few hundred nanometers, it can completely change that pattern.")
    def show_interference(self):
        self.axes = Axes(x_range=[-4, 4], y_range=[-1, 1], axis_config={"include_ticks": False})
        self.wave = self.axes.plot(lambda x: 0.5 * np.sin(5 * x), color=BLUE)
        self.pattern = VGroup(*[
            Line(start=[x, -2, 0], end=[x, 2, 0], color=BLUE_D, stroke_opacity=0.3)
            for x in np.linspace(-3, 3, 20)
        ])
        self.label = Text("Shift > Wavelength", font_size=32).to_edge(UP)
        self.play(Create(self.wave), Create(self.pattern), Write(self.label))

    @beat("Shift the pattern to show sensitivity", seconds=4,
          narration="So when Craig and Sally were showing us the ropes, one thing that really surprised me was how part of the process...")
    def shift_pattern(self):
        new_pattern = self.pattern.copy().shift(RIGHT * 1.5)
        self.play(ReplacementTransform(self.pattern, new_pattern), run_time=3)
        self.pattern = new_pattern

    @beat("Visualize the need for stillness", seconds=4,
          narration="...involved all of us sitting in this meditative stillness throughout the exposure, which took a couple of minutes.")
    def meditative_stillness(self):
        self.people = VGroup(*[Dot(point=[x, -3, 0], radius=0.2) for x in [-2, 0, 2]])
        self.timer = DecimalNumber(0, num_decimal_places=0).to_edge(RIGHT)
        timer_text = Text("Exposure (s):", font_size=24).next_to(self.timer, LEFT)
        self.play(FadeIn(self.people), Write(VGroup(self.timer, timer_text)))
