from manim import *

class AtomGridScene(Scene):
    def construct(self):
        grid = self.create_atom_grid(4, 4)
        self.play(Create(grid))
        self.wait(2)

    def create_atom_grid(self, rows: int, cols: int) -> Mobject:
        atom_list = []
        for i in range(rows):
            for j in range(cols):
                if (i + j) % 2 == 0:
                    atom_list.append(self.hydrogen_atom().move_to(np.array([i - rows // 2, j - cols // 2, 0])))
                else:
                    atom_list.append(self.chlorine_atom().move_to(np.array([i - rows // 2, j - cols // 2, 0])))
        return VGroup(*atom_list)

    def hydrogen_atom(self) -> Mobject:
        return Circle(radius=0.2, color=WHITE).add(Tex("H", color=BLACK).scale(0.5))

    def chlorine_atom(self) -> Mobject:
        return Circle(radius=0.3, color=GREEN).add(Tex("Cl", color=WHITE).scale(0.5))
