        self.plane = ComplexPlane(x_range=[-2.5, 1.5], y_range=[-2, 2], axis_config={"include_tip": False}).scale(0.8)
        self.cardioid = ParametricFunction(self.get_cardioid, t_range=[0, 2 * PI], color=BLUE)
        self.bubble = Circle(radius=0.25, color=BLUE).shift(LEFT * 0.5)
        self.play(Create(self.plane), Create(self.cardioid), Create(self.bubble), run_time=3)

