from manim import *
from forge.beats import ForgeScene, beat
import numpy as np

class FourierEpicycles(ForgeScene):
    def get_f_points(self, n=100):
        # Parametric approximation of an 'f' shape
        t = np.linspace(0, 2 * np.pi, n)
        x = 0.5 * np.cos(t) + 0.2 * np.sin(3 * t)
        y = 1.5 * np.sin(t) - 0.5 * np.cos(t)
        return [np.array([x[i], y[i], 0]) for i in range(n)]

    @beat("Initialize the canvas with an f-shape", seconds=3, narration="For finitely many vectors, this tracing usually won't be a perfect replica of the target shape, which in this animation is a lowercase f.")
    def setup_shape(self):
        self.path = VMobject(color=BLUE, stroke_width=4)
        self.points = self.get_f_points()
        self.path.set_points_smoothly(self.points)
        self.label = Text("Target: 'f'", font_size=24).to_edge(UP)
