from manim import *
from forge.beats import ForgeScene, beat
import numpy as np

class ProbabilityDensityFunction(ForgeScene):
    def get_pdf_curve(self):
        # A simple normal-like distribution: exp(-x^2)
        return FunctionGraph(lambda x: 2 * np.exp(-x**2), x_range=[-3, 3], color=BLUE)

    @beat("Introduce the PDF curve", seconds=3, narration="Anytime you see a PDF in the wild, the way to interpret it is that the probability of your random variable lying between two values equals the area under this curve between those values.")
    def show_pdf(self):
        self.axes = Axes(x_range=[-3, 3, 1], y_range=[0, 2.5, 1], axis_config={"include_tip": False}).scale(0.8).shift(LEFT * 2)
        self.curve = self.get_pdf_curve().move_to(self.axes.c2p(0, 0), aligned_edge=DOWN)
        self.area = self.axes.get_area(self.curve, x_range=[-1, 1], color=BLUE, opacity=0.3)
        self.label = MathTex(r"P(a < X < b) = \int_a^b f(x) dx").scale(0.8).next_to(self.axes, RIGHT, buff=1)
        self.play(Create(self.axes), Create(self.curve), Write(self.label), FadeIn(self.area))

    @beat("Focus on a specific point", seconds=3, narration="So, for example, what's the probability of getting any one very specific number, like 0.7?")
    def highlight_point(self):
        point = 0.7
        self.line = DashedLine(self.axes.c2p(point, 0), self.axes.c2p(point, 2 * np.exp(-point**2)), color=YELLOW)
        self.point_label = MathTex("0.7").next_to(self.axes.c2p(point, 0), DOWN, buff=0.1)
        self.play(Create(self.line), Write(self.point_label))

    @beat("Show the slice area", seconds=3, narration="Well, the area of an infinitely thin slice is 0, so it's 0.")
    def show_zero_area(self):
        self.zero_text = Text("Area = 0", color=RED).next_to(self.label, DOWN, buff=1)
        self.play(Write(self.zero_text))
        self.play(Indicate(self.line))

    @beat("Transition to total probability", seconds=3, narration="What's the probability of all of them put together?")
    def transition_to_total(self):
        self.play(FadeOut(self.line), FadeOut(self.point_label), FadeOut(self.zero_text))
        self.total_area = self.axes.get_area(self.curve, x_range=[-3, 3], color=GREEN, opacity=0.3)
        self.play(ReplacementTransform(self.area, self.total_area))

    @beat("Highlight the full integral", seconds=3, narration="For a valid PDF, the total area under the curve must sum to 1.")
    def show_total_one(self):
        total_val = MathTex(r"\int_{-\infty}^{\infty} f(x) dx = 1").next_to(self.label, DOWN, buff=1)
        self.play(Write(total_val))
        self.play(Indicate(self.total_area))
        self.wait(1)

    @beat("Final summary", seconds=2, narration="It represents the certainty that the random variable takes on some value.")
    def conclusion(self):
        self.play(FadeOut(self.axes), FadeOut(self.curve), FadeOut(self.total_area), FadeOut(self.label))
        final_text = Text("Total Probability = 1", font_size=48).center()
        self.play(Write(final_text))
