import numpy as np

class UniversalMandelbrot(ForgeScene):
    def get_cardioid(self, t):
        return np.array([
            (2 * np.cos(t) - np.cos(2 * t)) * 0.5,
            (2 * np.sin(t) - np.sin(2 * t)) * 0.5,
            0
        ])

    @beat("Draw the base cardioid and bubbles", seconds=4, narration="Yet again, asking a question where we tweak a parameter for one of these functions yields this iconic cardioid and bubbles shape.")
    def draw_shape(self):
        self.plane = ComplexPlane(x_range=[-2.5, 1.5], y_range=[-2, 2], axis_config={"include_tip": False}).scale(0.8)
        self.cardioid = ParametricFunction(self.get_cardioid, t_range=[0, 2 * PI], color=BLUE)
        self.bubble = Circle(radius=0.25, color=BLUE).shift(LEFT * 0.5)
        self.play(Create(self.plane), Create(self.cardioid), Create(self.bubble), run_time=3)

    @beat("Highlight the universality", seconds=3, narration="The upshot is that this shape is not as specific to the z squared plus c example as you might think.")
    def universality(self):
        self.text = Text("General Parameter Space", font_size=32).to_edge(RIGHT, buff=0.5)
        self.play(FadeIn(self.text), self.cardioid.animate.set_color(YELLOW), run_time=2)

    @beat("Show abstract symbols", seconds=3, narration="It seems to relate to something more general and universal about parameter spaces with processes like this.")
    def general_process(self):
        formula = MathTex(r"f_c(z) = z^n + c", font_size=40).next_to(self.text, DOWN)
        self.play(Write(formula), run_time=2)
        self.formula = formula

    @beat("Transition to fractal complexity", seconds=3, narration="Still, one pressing question is why we get fractals at all.")
    def transition(self):
        self.play(FadeOut(self.plane, self.cardioid, self.bubble, self.text, self.formula), run_time=2)

    @beat("Show abstract fractal representation", seconds=4, narration="When we look closer at the boundary, we see infinite recursive detail emerging.")
    def zoom_in(self):
        # Representing the fractal boundary with nested geometric patterns
        self.fractal_group = VGroup(*[
            Circle(radius=1.5 / (2**i), stroke_opacity=1.0 - (i/5)) 
            for i in range(5)
        ])
        self.play(FadeIn(self.fractal_group), run_time=3)

    @beat("Concluding thought", seconds=3, narration="This self-similarity is the hallmark of the fractal nature we observe.")
    def conclude(self):
        dot = Dot(color=RED).move_to(self.fractal_group.get_center())
        self.play(Indicate(dot), run_time=2)
        self.wait(1)
