        self.play(Create(self.bits), Write(self.label))

        flips = VGroup(*[Circle(radius=0.35, color=RED, stroke_width=4).move_to(self.bits[i][0]) for i in [0, 2]])
        self.play(FadeIn(flips))
        self.wait(1)

    @beat("State the fundamental limitation", seconds=3, narration="Keep in mind, though, there is no method for error detection or correction that could give you 100% confidence that the message you receive is the one the sender intended.")
    def claim_limitation(self):
        text = Text("No method provides 100% confidence", font_size=32, color=YELLOW).to_edge(RIGHT, buff=0.5)
        self.play(Write(text))
        self.confidence_bar = Rectangle(width=4, height=0.5, fill_opacity=0.5, color=RED).next_to(text, DOWN)
        self.play(Create(self.confidence_bar))

    @beat("Visualize noise as random chance", seconds=3, narration="After all, enough random noise could always change one valid message into another valid message just by pure chance.")
    def noise_visualization(self):
        noise = VGroup(*[Dot(point=np.array([np.random.uniform(-3, 3), np.random.uniform(-2, 2), 0.0])) for _ in range(50)])
        self.play(FadeIn(noise))
        self.play(noise.animate.set_color(GRAY))

    @beat("Show message transformation", seconds=3, narration="Enough random noise could always change one valid message into another valid message.")
    def message_morph(self):
        msg_a = Text("0000", font_size=40, color=BLUE).shift(LEFT * 3 + UP * 1)
        msg_b = Text("1111", font_size=40, color=GREEN).shift(LEFT * 3 + DOWN * 1)
        arrow = Arrow(msg_a.get_bottom(), msg_b.get_top(), color=WHITE)
        self.play(Write(msg_a), Write(msg_b), GrowArrow(arrow))

