import numpy as np

class VerifierLinearity(ForgeScene):
    # Setup dimensions for a vector space visual
    basis_vectors = [np.array([1, 0, 0]), np.array([0, 1, 0]), np.array([0, 0, 1])]
    coeffs = [0.2, 0.5, 0.3]

    @beat("Introduce vector decomposition", seconds=4, narration="To figure out what our verifier does to this new vector, what you do is look at what it would do to each basis separately, and then the output is going to be the same scaled sum of the result.")
    def show_decomposition(self):
        self.vec_tex = MathTex(r"\vec{v} = c_1\vec{e}_1 + c_2\vec{e}_2 + c_3\vec{e}_3")
        self.vec_tex.to_corner(UL)
        self.play(Write(self.vec_tex))

        self.basis_group = VGroup(*[Dot(color=BLUE).shift(i*RIGHT + DOWN) for i in range(-1, 2)])
        self.play(Create(self.basis_group))

    @beat("Show the verifier function", seconds=4, narration="In this case, most parts of that sum stay unchanged, but one of them, the one that's associated with the key input that represents a Sudoku solution, that part is going to have it sign flipped.")
    def show_function(self):
        self.f_label = MathTex(r"f(\vec{v}) = c_1\vec{e}_1 + c_2\vec{e}_2 - c_3\vec{e}_3").next_to(self.vec_tex, DOWN, buff=1)
        self.play(Write(self.f_label))

        # Highlight the sign flip
        self.rect = SurroundingRectangle(self.f_label[0][-4:], color=RED)
        self.play(Create(self.rect))

    @beat("Animate the transformation", seconds=3, narration="When you do this, it's very tempting to look at it and say that the function is acting on every possible basis vector at once in parallel, and then adding the results.")
    def show_parallel_action(self):
        arrows = VGroup(*[Arrow(start=self.basis_group[i].get_center(), end=self.basis_group[i].get_center() + UP, color=YELLOW) for i in range(3)])
        self.play(Create(arrows))

    @beat("Emphasize the summation", seconds=3, narration="Essentially, linearity allows us to treat the transformation of a complex input as a linear combination of its individual parts.")
    def show_summation(self):
        sum_tex = MathTex(r"f(\sum c_i \vec{e}_i) = \sum c_i f(\vec{e}_i)")
        sum_tex.to_edge(RIGHT)
        self.play(ReplacementTransform(self.f_label.copy(), sum_tex))
        self.sum_tex = sum_tex

    @beat("Highlight the solution vector", seconds=3, narration="The key is that the verifier isolates the specific input representing the solution, acting on it uniquely.")
    def highlight_solution(self):
        self.play(Indicate(self.sum_tex[0][-3:]))

    @beat("Final summary", seconds=3, narration="By manipulating basis vectors independently, we gain total control over the behavior of the linear function across the entire space.")
    def conclusion(self):
        self.play(FadeOut(self.basis_group), FadeOut(self.rect))
        self.play(self.vec_tex.animate.set_color(YELLOW))
        self.wait(1)
