import numpy as np

class MatrixRankVisualization(ForgeScene, ThreeDScene):

    @beat("Initialize 3D view", seconds=3, narration="For instance, in the case of 2x2 matrices, rank two is the best that it can be.")
    def setup_scene(self):
        self.set_camera_orientation(phi=75 * DEGREES, theta=-45 * DEGREES)
        self.axes = ThreeDAxes(x_range=[-2, 2], y_range=[-2, 2], z_range=[-2, 2], axis_config={"include_tip": True})
        self.basis = VGroup(
            Vector(RIGHT, color=RED),
            Vector(UP, color=GREEN)
        )
        self.play(Create(self.axes), Create(self.basis), run_time=2)

    @beat("Show 2D full rank", seconds=3, narration="It means the basis vectors continue to span the full two dimensions of space, and the determinant is not zero.")
    def show_2d_rank(self):
        self.plane = Surface(lambda u, v: np.array([u, v, 0]), u_range=[-1.5, 1.5], v_range=[-1.5, 1.5], fill_opacity=0.3, color=BLUE)
        self.play(FadeIn(self.plane), run_time=2)

    @beat("Transition to 3D", seconds=3, narration="But for 3x3 matrices, rank two means that we've collapsed, but not as much as they would have collapsed for a rank one situation.")
    def transition_to_3d(self):
        self.z_vec = Vector(OUT, color=BLUE)
        self.basis.add(self.z_vec)
        self.play(Create(self.z_vec), run_time=2)

    @beat("Show rank 2 collapse", seconds=3, narration="But for 3x3 matrices, rank two means that we've collapsed, but not as much as they would have collapsed for a rank one situation.")
    def show_rank_two(self):
        self.rank2_plane = Surface(lambda u, v: np.array([u, v, 0]), u_range=[-1.5, 1.5], v_range=[-1.5, 1.5], fill_opacity=0.5, color=YELLOW)
        self.play(FadeOut(self.plane), FadeIn(self.rank2_plane), run_time=2)

    @beat("Show rank 3", seconds=3, narration="If a 3D transformation has a non-zero determinant and its output fills all of 3D space, it has a rank of three.")
    def show_rank_three(self):
        self.cube = Cube(side_length=2, fill_opacity=0.2, color=PURPLE)
        self.play(FadeOut(self.basis), FadeOut(self.axes), FadeOut(self.rank2_plane))
