from manim import *
from forge.beats import ForgeScene, beat

class ColorGradientWorkflow(ForgeScene):

    @beat("Initialize color gradient mapping and states", seconds=4, narration="So I have a thing called color gradient that will basically go between two colors and you tell it how many steps exactly.")
    def init_gradient(self):
        self.colors = [BLUE_D, YELLOW_D]
        self.states = [f"State {i}" for i in range(5)]

        # Draw color bar representing the gradient
        self.gradient_bar = VGroup(*[
            Rectangle(width=0.8, height=0.6, fill_color=interpolate_color(BLUE_D, YELLOW_D, i/4), fill_opacity=1, stroke_width=1)
            for i in range(5)
