        self.title = Text("Color Gradient Steps", font_size=32).next_to(self.gradient_bar, UP, buff=0.5)
        self.play(FadeIn(self.title), LaggedStart(*[FadeIn(b, scale=0.5) for b in self.gradient_bar], lag_ratio=0.1), run_time=3.0)
        self.wait(1.0)

    @beat("Align number of steps with states length", seconds=4, narration="And so the number of steps should be the length of the states in this case.")
    def align_steps(self):
        # Compute length of states dynamically
        num_states = len(self.states)

        self.state_boxes = VGroup(*[
            Square(side_length=0.8, fill_color=GRAY, fill_opacity=0.3, stroke_color=WHITE)
            for _ in range(num_states)
        ]).arrange(RIGHT, buff=0.2).to_edge(DOWN, buff=1.5).to_edge(LEFT, buff=1.0)

        self.state_label = Text(f"States Length: {num_states}", font_size=28, color=YELLOW_C).next_to(self.state_boxes, UP, buff=0.3)

        self.play(
            LaggedStart(*[FadeIn(s) for s in self.state_boxes], lag_ratio=0.1),
            Write(self.state_label),
            run_time=3.0
        )
        self.wait(1.0)

    @beat("Match colors to states", seconds=4, narration="So we should just feel like, OK, no matter what, the number of colors matches the length of the states.")
    def match_colors(self):
        # Draw connecting lines or arrows from gradient to states
        arrows = VGroup(*[
            Arrow(self.gradient_bar[i].get_bottom(), self.state_boxes[i].get_top(), buff=0.1, color=YELLOW_C, stroke_width=2, tip_length=0.15)
            for i in range(len(self.states))
        ])

        match_text = Text("Colors Match States", font_size=28, color=GREEN).to_edge(RIGHT, buff=1.0).shift(UP * 1.0)

        self.play(
            LaggedStart(*[GrowArrow(a) for a in arrows], lag_ratio=0.1),
            FadeIn(match_text),
            run_time=3.0
        )
        self.wait(1.0)

    @beat("Feeling comfortable with the workflow", seconds=4, narration="And now I feel more comfortable.")
    def comfort_state(self):
        check_mark = Text("✓", color=GREEN).scale(2.5).to_edge(RIGHT, buff=2.0).shift(DOWN * 0.5)
