            FadeIn(check_mark, scale=0.5),
            Write(comfort_label),
            self.gradient_bar.animate.set_opacity(1.0),
            run_time=3.0
        )
        self.wait(1.0)

    @beat("Reflecting on workflow insight", seconds=4, narration="I wonder how much it is insightful to watch someone doing a workflow and to note when discomfort kicks in.")
