        thought_box = Rectangle(width=6.0, height=2.0, fill_color=BLACK, fill_opacity=0.8, stroke_color=BLUE_C)
        thought_text = Text("Observing\nWorkflow Discomfort", font_size=28, color=BLUE_C).move_to(thought_box.get_center())

