        self.play(self.triangle.animate.set_fill(YELLOW, 0.5), Write(vals))
        self.vals = vals

    @beat("Show the 5-12-13 triangle", seconds=3, narration="or the 5-12-13 triangle.")
    def show_51213(self):
        t2 = Polygon(ORIGIN, RIGHT * 2.5, UP * 6, color=GREEN, fill_opacity=0.5).scale(0.2).shift(RIGHT * 2)
        vals2 = MathTex("5^2 + 12^2 = 169 = 13^2").next_to(t2, DOWN)
        self.play(FadeIn(t2), Write(vals2))
        self.t2 = t2
        self.vals2 = vals2

    @beat("Highlight perfect squares", seconds=3, narration="And I think it's easy to take for granted that these even exist,")
    def highlight_squares(self):
        self.play(FadeOut(self.triangle), FadeOut(self.eq), FadeOut(self.vals), 
