from manim import *
from forge.beats import ForgeScene, beat
import numpy as np

class ComplexLaplaceTransition(ForgeScene):
    @beat("Initialize the real-valued integral visualization", seconds=3,
          narration="And then same deal as you keep integrating along a bunch of other unit intervals.")
    def init_real_intervals(self):
        self.axes = Axes(x_range=[0, 8, 1], y_range=[-1, 1.5, 1], x_length=8, y_length=4)
        self.func = lambda t: np.exp(-0.5 * t) * np.sin(2 * t)
        self.graph = self.axes.plot(self.func, color=BLUE)
        self.intervals = VGroup(*[
            Rectangle(height=self.axes.y_length, width=self.axes.x_length/8, color=YELLOW, fill_opacity=0.2)
            .move_to(self.axes.c2p(i + 0.5, 0))
            for i in range(8)
        ])
        self.play(Create(self.axes), Create(self.graph), FadeIn(self.intervals), run_time=2.5)

    @beat("Show the summation of averages", seconds=3,
          narration="So then, if you want the integral from 0 out to infinity, what you can think about is taking all of these average values on those intervals and adding them all together.")
    def show_summation(self):
        averages = [np.mean([self.func(x) for x in np.linspace(i, i+1, 10)]) for i in range(8)]
        total_sum = sum(averages)
        self.sum_label = MathTex(f"\\sum \\text{{avg}} \\approx {total_sum:.2f}").to_edge(RIGHT)
        self.play(Write(self.sum_label), run_time=2)
        self.wait(1)

    @beat("Transition to the complex plane", seconds=3,
          narration="This is something we can work with. Now let's look at the complex case.")
    def transition_complex(self):
        self.play(FadeOut(self.axes, self.graph, self.intervals, self.sum_label))
        self.complex_plane = ComplexPlane(x_range=[-3, 3], y_range=[-3, 3]).scale(0.8)
        self.play(Create(self.complex_plane), run_time=2)

    @beat("Define S and the complex function", seconds=3,
          narration="S is going to be some complex number, and then the function e^(-st) cycles and decays around the complex plane.")
    def define_s(self):
        self.dot = Dot(color=RED)
        self.label = MathTex("e^{-st}", color=RED).to_edge(UP)
        self.play(FadeIn(self.dot), Write(self.label), run_time=2)

    @beat("Animate the spiral decay", seconds=4,
          narration="...as you let time go from 0 up to infinity.")
    def animate_spiral(self):
        # Parametric function: e^(-st) = e^(-(0.5+2i)t) = e^(-0.5t) * (cos(2t) - i sin(2t))
        def func(t):
            return self.complex_plane.c2p(
                np.exp(-0.5 * t) * np.cos(2 * t),
                -np.exp(-0.5 * t) * np.sin(2 * t)
            )

        path = TracedPath(self.dot.get_center, stroke_width=3, stroke_color=RED)
        self.add(path)
        self.play(UpdateFromAlphaFunc(self.dot, lambda m, a: m.move_to(func(a * 6))), run_time=4, rate_func=linear)
        self.wait(1)
