        self.play(Create(self.axes), Create(self.unit_circle), run_time=2.0)

    @beat("Show a complex number and its polar transformation components.", seconds=3, narration="And in general, every one of these multiplicative actions is some combination of a stretch or a squish...")
    def show_transformation_vector(self):
        r_val = np.sqrt(5)
        angle_val = np.pi / 6

        pos = self.axes.c2p(r_val * np.cos(angle_val), r_val * np.sin(angle_val))

        self.vector = Arrow(self.axes.get_origin(), pos, color=GREEN_C, buff=0)
        self.dot = Dot(pos, color=GREEN_C)

        self.angle_arc = Arc(radius=0.5, start_angle=0, angle=angle_val, color=YELLOW)
        self.angle_arc.move_to(self.axes.get_origin(), coor_mask=np.array([1, 1, 0]))

        self.play(GrowArrow(self.vector), FadeIn(self.dot), Create(self.angle_arc), run_time=2.0)

    @beat("Highlight the scaling component on the positive real axis.", seconds=3, narration="...an action associated with some point on the positive real number line...")
    def highlight_real_axis(self):
        r_val = np.sqrt(5)
        real_pt = self.axes.c2p(r_val, 0)

        self.real_line = Line(self.axes.get_origin(), real_pt, color=RED_C, stroke_width=6)
        r_label = MathTex(r"\sqrt{5}", color=RED_C, font_size=30).next_to(real_pt, DOWN, buff=0.1)

        self.play(Create(self.real_line), Write(r_label), run_time=2.0)

    @beat("Highlight the rotation component on the unit circle.", seconds=3, narration="...followed by a pure rotation, where pure rotations are associated with points on this circle, the one with radius 1.")
