from manim import *

class ChemicalAnimation(Scene):
    def construct(self):
        # Create a grid of metal and oxygen
        grid = self.metal_oxid(4, 4)
        self.play(Create(grid))
        self.wait(1)

        # Animate an electron moving along a complex path
        electron_particle = self.electron()
        self.add(electron_particle)
        complex_path = [
            UP * 2 + LEFT * 2,
            UP * 2 + RIGHT * 2,
            DOWN * 2 + RIGHT * 2,
            DOWN * 2 + LEFT * 2,
            UP * 2 + LEFT * 2,
        ]
        animations = self.move_along_complex_path(electron_particle, [0, 3], complex_path, run_time=2)
        self.play(*animations)
        self.wait(2)

        # Fade out all elements
        self.play(FadeOut(grid), FadeOut(electron_particle))

    def electron(self) -> Mobject:
        return circle_with_text(0.15, "e$^-$", YELLOW_D, 24, BLACK, 1, YELLOW_D)

    def metal_oxid(self, rows: int, cols: int, scale=1.5) -> Mobject:
        list = []
        for i in range(rows):
            for j in range(cols):
                if (j + i) % 2 == 0:
                    list.append(self.oxygen().move_to(np.array([i, j, 0]) / scale))
                else:
                    list.append(self.metal().move_to(np.array([i, j, 0]) / scale))
        return VGroup(*list)

    def oxygen(self) -> Mobject:
        o_atom = circle_with_text(0.285, "O$^2$", GREY_B, 25, WHITE, 1)
        o_atom.set_z_index(1)
        return o_atom

    def metal(self) -> Mobject:
        co_atom = circle_with_text(0.285, "Co", BLUE_D, 25, WHITE, 1)
        co_atom.set_z_index(1)
        return co_atom

    def move_along_complex_path(self, obj: Mobject, stop_indices, points, run_time: float, rate_func=linear):
        animations = []
        paths = []
        for i in range(len(points) - 1):
            if i not in stop_indices:
                paths.append(Line(points[i], points[i + 1], color=WHITE).set_opacity(0.5))

        for i in range(len(paths)):
            animations.append(MoveAlongPath(obj, paths[i], run_time=run_time / len(paths), rate_func=rate_func))
            if i in stop_indices:
                animations.append(AnimationGroup(Wait(run_time / len(paths))))

        return animations

def circle_with_text(
    r: float, txt: str, color=WHITE, font_size: int = 10, font_color=WHITE, stroke_width: int = 2, fill_color=WHITE
) -> Mobject:
    c = Circle(radius=r, color=color).set_opacity(1).set_fill(fill_color)
    t = Tex(txt, stroke_width=stroke_width, font_size=font_size, color=font_color)
    return VGroup(c, t)
