class GradientDescentSummation(ForgeScene):

    @beat("Because the cost function involves averaging a certain cost per example over all the tens of thousands of training examples,", seconds=4, narration="Because the cost function involves averaging a certain cost per example over all the tens of thousands of training examples,")
