    @beat("the way we adjust the weights and biases for a single gradient descent step", seconds=4, narration="the way we adjust the weights and biases for a single gradient descent step")
    def show_weights_and_step(self):
        # Show weights, biases and a summation arrow pointing to a gradient step
        self.sum_symbol = MathTex(r"\frac{1}{N} \sum_{i=1}^{N} \text{Cost}_i", font_size=36).move_to([1.5, 1.5, 0])

        # Draw arrows from examples to the summation
        self.arrows = VGroup(*[
            Arrow(ex.get_center(), self.sum_symbol.get_left(), buff=0.1, stroke_width=1, color=GRAY)
            for ex in self.examples[::5] # sample a few for visual clarity
        ])

        self.play(FadeIn(self.arrows, lag_ratio=0.1), Write(self.sum_symbol), run_time=3.0)

    @beat("also depends on every single example.", seconds=3, narration="also depends on every single example.")
    def highlight_all_dependence(self):
        # Highlight all examples pulsing to show full dependency
        self.play(
            self.examples.animate.set_fill(YELLOW, opacity=0.8),
            run_time=1.5
        )
        self.play(
            self.examples.animate.set_fill(BLUE_E, opacity=0.6),
            run_time=1.5
        )

    @beat("Or rather, in principle it should,", seconds=3, narration="Or rather, in principle it should,")
