class ConnectednessAndDisease(ForgeScene):

    @beat("Introduce the nodes representing a global population", seconds=4, 
          narration="Living in a world with widespread travel and vibrant urban centers does make fighting the spread of a disease an uphill battle, that's absolutely true.")
    def show_nodes(self):
        self.nodes = VGroup(*[Dot(point=np.array([np.random.uniform(-5, 2), np.random.uniform(-3, 3), 0])) for _ in range(40)])
        self.connections = VGroup(*[
            Line(self.nodes[i].get_center(), self.nodes[j].get_center(), stroke_opacity=0.2) 
            for i in range(40) for j in range(i+1, 40) 
            if np.linalg.norm(self.nodes[i].get_center() - self.nodes[j].get_center()) < 2
        ])
        self.play(Create(self.connections), FadeIn(self.nodes), run_time=3)

    @beat("Simulate spread of infection", seconds=4,
          narration="But that same level of connectedness means that ideas spread more quickly than ever.")
    def spread_infection(self):
        self.play(*[i.animate.set_color(RED) for i in self.nodes[0:15]], run_time=3)

    @beat("Introduce glowing nodes representing ideas/solutions", seconds=4,
          narration="Ideas that can lead to systems and technologies that nip these outbreaks in the bud.")
    def show_ideas(self):
        self.ideas = VGroup(*[Circle(radius=0.15, color=YELLOW, fill_opacity=0.5).move_to(self.nodes[20+i].get_center()) for i in range(5)])
        self.play(LaggedStart(*[GrowFromCenter(i) for i in self.ideas], lag_ratio=0.3), run_time=3)

    @beat("Ideas clearing the red nodes", seconds=4,
          narration="It won't happen on its own, and it's clear that we sometimes make mistakes.")
