        return [np.array([2 * np.cos(2 * np.pi * i / n), 2 * np.sin(2 * np.pi * i / n), 0]) for i in range(n)]

    @beat("Initialize the points on a circle", seconds=3, narration="Again, the logic is that it's parallel to its starting position.")
