        self.dots = VGroup(*[Dot(p, color=BLUE) for p in self.points])
        self.circle = Circle(radius=2, color=WHITE, stroke_opacity=0.3)
        self.play(Create(self.circle), LaggedStart(*[GrowFromCenter(d) for d in self.dots]))

    @beat("Show the rotation vector", seconds=3, narration="And if it was passing through any other point, the number of points on a given side would have to be different.")
    def show_vector(self):
