import numpy as np

class DotTailAnimation(ForgeScene):
    dots = VGroup()
    trails = VGroup()

    @beat("Initialize the scene with a set of moving dots", seconds=3, narration="And indeed it looks like they do. And then we're left just with the dots, which is nice.")
    def init_dots(self):
        self.dots = VGroup(*[Dot(point=np.array([np.cos(i), np.sin(i), 0]) * 2, color=BLUE) for i in range(10)])
        self.play(FadeIn(self.dots), run_time=2)
        self.wait(1)

    @beat("Animate the dots in a circular path", seconds=3, narration="It looks very nice.")
    def move_dots(self):
        def update_dot(mob, dt):
            angle = dt * 0.5
            rot_matrix = np.array([[np.cos(angle), -np.sin(angle), 0], [np.sin(angle), np.cos(angle), 0], [0, 0, 1]])
            mob.move_to(rot_matrix @ mob.get_center())

        self.dots.add_updater(update_dot)
        self.play(Wait(3))
        self.dots.remove_updater(update_dot)

    @beat("Show the hesitation/transition state", seconds=3, narration="The other thing that we got into, and I just took way longer to say this than I properly should have.")
    def hesitation(self):
        label = Text("Wait, what was the function?", font_size=36, color=YELLOW).to_edge(UP)
        self.play(Write(label), run_time=2)
        self.play(FadeOut(label), run_time=1)

    @beat("Display an annotation about the uncut version", seconds=3, narration="Because I was trying to remember what the names of the functions were and things like that. Again, I'll post this all in a more uncut version elsewhere.")
    def uncut_note(self):
        note = Text("Full derivation in uncut version", font_size=32, color=GREY).to_edge(DOWN)
        self.play(FadeIn(note), run_time=2)
        self.play(FadeOut(note), run_time=1)

    @beat("Begin the tail effect logic", seconds=3, narration="If we wanted a nice effect where there's this sort of tail following the dots...")
    def start_tail(self):
