from manim import *
from forge.beats import ForgeScene, beat
import numpy as np

class FourierStepApproximation(ForgeScene):

    @beat("Introduce the step function as the target", seconds=4, narration="It's really hard to overstate how far-reaching this idea is, beyond anything Fourier imagined. The origin is a physics problem, yet it relates to these sums.")
    def show_target(self):
        self.axes = Axes(x_range=[-3, 3, 1], y_range=[-0.5, 1.5, 0.5], axis_config={"include_tip": False})
        self.step = self.axes.plot(lambda x: 1 if x > 0 else 0, discontinuities=[0], color=YELLOW)
        self.label = Text("Step Function", font_size=24).next_to(self.step, UP)
        self.play(Create(self.axes), Create(self.step), Write(self.label))

    @beat("Show the first harmonic", seconds=3, narration="At first glance, this has nothing to do with frequencies. But the general applicability of Fourier series is the key here.")
    def first_term(self):
        self.n = 1
        self.func = self.axes.plot(lambda x: 0.5 + (2/np.pi) * np.sin(x), color=BLUE)
        self.play(Transform(self.step, self.func), run_time=2)
        self.term_label = MathTex(r"n=1").to_edge(RIGHT)
        self.play(Write(self.term_label))

    @beat("Add more harmonics", seconds=3, narration="Now, I hear some of you saying, none of these sums of sine waves that you're showing are actually the step function.")
    def add_harmonics(self):
        self.n = 5
        # Fourier series for square wave: 1/2 + 2/pi * sum(sin((2k-1)x)/(2k-1))
        def fourier_sum(x, n):
            val = 0.5
            for k in range(1, n + 1):
                val += (2 / (np.pi * (2 * k - 1))) * np.sin((2 * k - 1) * x)
            return val

        new_func = self.axes.plot(lambda x: fourier_sum(x, self.n), color=BLUE)
        self.play(Transform(self.step, new_func))
        self.play(FadeTransform(self.term_label, MathTex(f"n={self.n}").to_edge(RIGHT)))

    @beat("Show high frequency approximation", seconds=3, narration="They're all just approximations, struggling to match the sharp vertical jump of the step.")
    def high_harmonics(self):
        self.n = 20
        def fourier_sum(x, n):
            val = 0.5
            for k in range(1, n + 1):
                val += (2 / (np.pi * (2 * k - 1))) * np.sin((2 * k - 1) * x)
            return val

        new_func = self.axes.plot(lambda x: fourier_sum(x, self.n), color=BLUE)
        self.play(Transform(self.step, new_func))
        self.play(FadeTransform(self.term_label, MathTex(f"n={self.n}").to_edge(RIGHT)))

    @beat("Highlight the Gibbs phenomenon", seconds=3, narration="You can see these oscillations near the discontinuity; the approximation never truly settles.")
    def gibbs_highlight(self):
        circle = Circle(radius=0.2, color=RED).move_to(self.axes.c2p(0, 1.1))
        arrow = Arrow(start=RIGHT, end=LEFT).next_to(circle, RIGHT)
        self.play(Create(circle), Create(arrow))
        self.wait(1)
        self.play(FadeOut(circle), FadeOut(arrow))

    @beat("Final state of the approximation", seconds=3, narration="Yet, as we add more terms, the approximation gets closer and closer to the ideal behavior.")
    def conclusion(self):
        self.n = 50
        def fourier_sum(x, n):
            val = 0.5
            for k in range(1, n + 1):
                val += (2 / (np.pi * (2 * k - 1))) * np.sin((2 * k - 1) * x)
            return val

        new_func = self.axes.plot(lambda x: fourier_sum(x, self.n), color=BLUE)
        self.play(Transform(self.step, new_func), run_time=2)
        self.play(FadeTransform(self.term_label, MathTex(f"n={self.n}").to_edge(RIGHT)))
