from manim import *
from forge.beats import ForgeScene, beat
from fractions import Fraction

class TwoEnvelopeParadox(ForgeScene):
    @beat("Introduce the two envelopes", seconds=4, narration="Imagine two envelopes. One contains twice as much money as the other, and you are asked to pick one.")
    def setup_envelopes(self):
        self.env_a = Rectangle(width=2, height=1.5, color=BLUE).shift(LEFT * 2.5)
        self.env_b = Rectangle(width=2, height=1.5, color=GREEN).shift(RIGHT * 2.5)
        self.label_a = Text("Envelope A").next_to(self.env_a, UP)
        self.label_b = Text("Envelope B").next_to(self.env_b, UP)
        self.play(Create(self.env_a), Create(self.env_b), Write(self.label_a), Write(self.label_b))

    @beat("Define the variables", seconds=5, narration="Let's say your envelope contains X dollars. Because the other contains either half or double that, it must contain either X/2 or 2X.")
    def define_variables(self):
        self.val_x = MathTex("X").move_to(self.env_a)
        self.val_other = MathTex(r"\frac{X}{2} \text{ or } 2X").move_to(self.env_b)
        self.play(Write(self.val_x), Write(self.val_other))

    @beat("Calculate expected value", seconds=6, narration="If you switch, your expected gain is 50 percent chance of doubling, and 50 percent chance of halving.")
    def calc_ev(self):
        self.ev_formula = MathTex(r"E = \frac{1}{2}(2X) + \frac{1}{2}\left(\frac{X}{2}\right)").scale(1.2).to_edge(UP)
        self.play(Write(self.ev_formula))

    @beat("Simplify the result", seconds=4, narration="Summing these up, you get X plus one-fourth X, which equals 1.25 X.")
    def simplify(self):
        self.result = MathTex(r"E = \frac{5}{4}X").scale(1.5).set_color(YELLOW).next_to(self.ev_formula, DOWN)
        self.play(TransformMatchingTex(self.ev_formula.copy(), self.result))

    @beat("Highlight the paradox", seconds=5, narration="This suggests that switching always increases your expected value by 25 percent, which seems impossible!")
    def highlight_paradox(self):
        self.box = SurroundingRectangle(self.result, color=RED)
        self.play(Create(self.box))
        self.wait(2)

    @beat("Reveal the fallacy", seconds=6, narration="The fallacy lies in assuming X is a fixed value that applies to both scenarios equally.")
    def fallacy_text(self):
        text = Text("Fallacy: X is not independent", font_size=36, color=RED).to_edge(DOWN)
        self.play(Write(text))

    @beat("Visualize the total pot", seconds=6, narration="If the smaller envelope is Y, the total money is 3Y. You are choosing between Y and 2Y with equal probability.")
    def visualize_pot(self):
        self.play(FadeOut(self.val_x, self.val_other, self.ev_formula, self.result, self.box))
        self.pot_label = MathTex(r"\text{Total Pot} = 3Y").shift(UP)
        self.option1 = Text("Envelope 1: Y").shift(LEFT * 2)
        self.option2 = Text("Envelope 2: 2Y").shift(RIGHT * 2)
        self.play(Write(self.pot_label), FadeIn(self.option1), FadeIn(self.option2))

    @beat("Correct expectation", seconds=5, narration="The expected value of your choice is simply the average of the two envelopes: 1.5Y.")
    def correct_ev(self):
        self.correct_eq = MathTex(r"E = \frac{1}{2}(Y) + \frac{1}{2}(2Y) = 1.5Y").set_color(GREEN)
        self.play(Write(self.correct_eq))

    @beat("Conclusion", seconds=4, narration="Since both envelopes have the same expected value of 1.5Y, switching doesn't change your outcome at all.")
    def conclusion(self):
        self.play(Indicate(self.correct_eq))
        self.wait(2)
