            background_line_style={"stroke_opacity": 0.3}
        ).scale(0.8).shift(LEFT * 2)
        self.outline.generate_target()
        self.outline.target.scale(0.8).shift(LEFT * 2)
        self.dots.generate_target()
        self.dots.target.scale(0.8).shift(LEFT * 2)
        self.play(
            MoveToTarget(self.outline), 
            MoveToTarget(self.dots), 
            Create(self.grid)
        )

    @beat("Rasterize the shape", seconds=4, narration="...whether it should be colored in or not.")
    def rasterize(self):
        # Create squares for pixels inside the shape
        pixels = VGroup()
        # Compute bounding box and check containment
        for x in np.arange(-3.5, 0.5, 0.2):
            for y in np.arange(-2.5, 2.5, 0.2):
                # Simple containment check relative to shifted coordinate space
                if (x + 2)**2 + (y)**2 < 2.0: 
                    pixels.add(Square(side_length=0.18, fill_opacity=0.8, color=BLUE, stroke_width=0).move_to([x, y, 0]))

        self.play(LaggedStart(*[FadeIn(p, scale=0.1) for p in pixels], lag_ratio=0.01))
        self.pixels = pixels

    @beat("Final composition", seconds=3, narration="This process of rasterization turns the mathematical curve into the physical pixels you see.")
    def final_summary(self):
        summary = Text("Rasterization", color=GREEN).to_edge(RIGHT)
        self.play(Write(summary), self.outline.animate.set_stroke(opacity=0.3))
        self.wait(2)
