from manim import *
from forge.beats import ForgeScene, beat

class IncompleteSquares(ForgeScene, ThreeDScene):
    def get_square_pattern(self, active_indices):
        grid = VGroup(*[
            Square(side_length=0.8, stroke_color=WHITE, stroke_width=2)
            for _ in range(4)
        ]).arrange(RIGHT, buff=0.2)
        for i, sq in enumerate(grid):
            if i not in active_indices:
                sq.set_fill(GREY_B, opacity=0.3)
            else:
                sq.set_fill(BLUE_D, opacity=0.8)
        return grid

    @beat("Initialize the full set of variations", seconds=3, narration="We can get rid of the two squares on the left because they aren't properly two dimensional.")
    def remove_degenerate(self):
        self.set_camera_orientation(phi=0, theta=-90*DEGREES)
        self.all_variations = VGroup(*[
            self.get_square_pattern(indices) for indices in [[0, 1], [1, 2], [2, 3], [0, 2]]
        ]).arrange(DOWN, buff=0.5).scale(0.8).to_edge(LEFT, buff=1)

        self.play(FadeIn(self.all_variations))
        self.play(FadeOut(self.all_variations[0]), FadeOut(self.all_variations[1]))
        self.remaining = VGroup(self.all_variations[2], self.all_variations[3])
        self.wait(1)

    @beat("Remove the disconnected square", seconds=3, narration="And we can get rid of the square in the middle because it isn't connected.")
    def remove_disconnected(self):
        self.play(FadeOut(self.remaining[1]))
        self.final_pair = VGroup(self.remaining[0])
        self.wait(1)

    @beat("Highlight the final two", seconds=3, narration="That leaves us with these two.")
    def show_final(self):
        self.final_pair = VGroup(
            self.get_square_pattern([0, 1, 2]), 
            self.get_square_pattern([1, 2, 3])
        ).arrange(RIGHT, buff=1).center()
        self.play(ReplacementTransform(self.remaining[0], self.final_pair))
        self.wait(1)

    @beat("Label the set", seconds=3, narration="And there we have it, the complete variations of incomplete open squares. Beautiful.")
    def label_set(self):
        title = Text("Incomplete Open Squares", font_size=36).to_edge(UP)
        self.play(Write(title))
        self.play(Indicate(self.final_pair))
        self.wait(1)

    @beat("Transition to 3D", seconds=3, narration="One of the great things about this piece is that it gives us some appreciation for the added complexity...")
