from manim import *
from forge.beats import ForgeScene, beat
import numpy as np

class LogarithmicEscherTransformation(ForgeScene):
    def get_grid(self, color=BLUE):
        return VGroup(*[
            Line(start=[-4, y, 0], end=[4, y, 0], color=color, stroke_opacity=0.3)
            for y in np.linspace(-4, 4, 9)
        ], *[
            Line(start=[x, -4, 0], end=[x, 4, 0], color=color, stroke_opacity=0.3)
            for x in np.linspace(-4, 4, 9)
        ])

    @beat("Initialize the complex plane view", seconds=3, narration="Step two, take a logarithm of this, which in this case gives us a similarly bizarre transformation of the whole scene.")
    def setup_plane(self):
        self.grid = self.get_grid()
        self.plane_label = Text("Complex Plane", font_size=24).to_edge(UP)
        self.play(Create(self.grid), Write(self.plane_label))

    @beat("Apply log transformation", seconds=3, narration="But there is a little difference this time.")
    def log_transform(self):
        def log_func(pos):
            x, y, z = pos
            r = np.sqrt(x**2 + y**2)
            theta = np.arctan2(y, x)
            return np.array([np.log(r + 0.1), theta, 0])

        self.play(self.grid.animate.apply_function(log_func), run_time=2)

    @beat("Highlight zoom factor", seconds=3, narration="Because Escher was working with a much deeper zoom, with a scale factor of 256, the repeating tiles in this new example actually span a wider part of the complex plane.")
    def zoom_factor(self):
        scale_factor = 256
        val = Text(f"Scale: {scale_factor}", color=YELLOW).to_edge(RIGHT)
        self.play(Write(val))
        self.zoom_indicator = Circle(radius=0.5, color=YELLOW).shift(LEFT * 2)
        self.play(Create(self.zoom_indicator), self.zoom_indicator.animate.scale(4))
        self.wait(1)

    @beat("Prepare for rotation", seconds=3, narration="Step three, again, is to rotate and scale this...")
    def rotate_prep(self):
        self.rot_text = Text("Rotate", color=GREEN).to_edge(RIGHT).shift(DOWN * 2)
        self.play(Write(self.rot_text))
        self.play(Rotate(self.grid, angle=PI/4, about_point=ORIGIN))

    @beat("Apply complex scaling", seconds=3, narration="...which depends on multiplying by the appropriate choice of a complex constant.")
    def scale_transform(self):
        complex_constant = 1.5
        constant_label = MathTex(r"\times z", color=RED).next_to(self.rot_text, DOWN)
        self.play(Write(constant_label))
        self.play(self.grid.animate.scale(complex_constant))

    @beat("Final state", seconds=3, narration="This completes the sequence of geometric manipulations.")
    def final(self):
        final_rect = SurroundingRectangle(self.grid, color=WHITE)
        self.play(Create(final_rect))
        self.wait(2)
