        key_pos = 27
        self.key = Star(color=YELLOW, fill_opacity=1, stroke_width=0).scale(0.2).move_to(self.grid[key_pos])
        self.play(Create(self.grid), FadeIn(self.key))

    @beat("Display the coins on the board", seconds=3,
