from math import pi
from manim import *
from forge.beats import ForgeScene, beat

class HypersphereVolume(ForgeScene):

    def volume(self, n):
        if n == 1:
            return 2.0
        elif n == 2:
            return pi
        elif n == 3:
            return (4.0 / 3.0) * pi
        elif n == 4:
            return (1.0 / 2.0) * (pi ** 2)
        elif n == 5:
            return (8.0 / 15.0) * (pi ** 2)
        elif n == 6:
            return (1.0 / 6.0) * (pi ** 3)
        elif n == 7:
            return (16.0 / 105.0) * (pi ** 3)
        elif n == 8:
            return (1.0 / 24.0) * (pi ** 4)
        elif n == 9:
            return (32.0 / 945.0) * (pi ** 4)
        return 0.0

    @beat("In one dimension the volume of a unit ball is two, and in two it's pi.", seconds=4, narration="In one dimension, the volume of a unit ball is two. In two dimensions, it's pi, the area of a unit circle.")
    def dim_1_2(self):
        title = Text("Volume of Unit Ball by Dimension", font_size=28, color=BLUE_C).to_edge(UP)
        self.play(Write(title), run_time=1)

        self.v1 = self.volume(1)
        self.v2 = self.volume(2)

        t1 = MathTex(r"n = 1:\quad V = 2", font_size=36).shift(UP * 1.5 + LEFT * 3.5)
        t2 = MathTex(rf"n = 2:\quad V = \pi \approx {self.v2:.2f}", font_size=36).shift(UP * 0.5 + LEFT * 3.5)

        circle = Circle(radius=1.2, color=BLUE, fill_opacity=0.2).shift(RIGHT * 3.5)
        label_c = MathTex(r"\text{Area} = \pi", font_size=32).move_to(circle.get_center())

        self.play(Write(t1), FadeIn(t2), Create(circle), Write(label_c), run_time=3)

    @beat("In three dimensions, it's 4/3 pi.", seconds=4, narration="In three dimensions, it's 4/3 pi. All these numbers are going up.")
    def dim_3(self):
        self.v3 = self.volume(3)
        t3 = MathTex(rf"n = 3:\quad V = \frac{{4}}{{3}}\pi \approx {self.v3:.2f}", font_size=36).shift(DOWN * 0.5 + LEFT * 3.5)

        sphere = Sphere(radius=1.0).shift(RIGHT * 3.5)
        # Approximate 3D sphere look with circles in 2D projection
        s_outline = Circle(radius=1.2, color=GREEN, fill_opacity=0.2).shift(RIGHT * 3.5)
        s_equator = Ellipse(width=2.4, height=0.8, color=GREEN).shift(RIGHT * 3.5)
        label_s = MathTex(r"\text{Volume} = \frac{4}{3}\pi", font_size=28).move_to(RIGHT * 3.5 + UP * 1.5)

        self.play(Write(t3), Create(s_outline), Create(s_equator), Write(label_s), run_time=3.5)

    @beat("Up in four dimensions, it gets bigger still, around 4.93.", seconds=4, narration="Up in four dimensions, it gets bigger still. We end up around 4.93.")
    def dim_4(self):
        self.v4 = self.volume(4)
        t4 = MathTex(rf"n = 4:\quad V = \frac{{\pi^2}}{{2}} \approx {self.v4:.2f}", font_size=36, color=YELLOW).shift(DOWN * 1.5 + LEFT * 3.5)

        # Shift old drawings left slightly to make room for a bar chart
        self.play(Write(t4), run_time=2)

        # Create a mini bar chart for dimensions 1 to 4
        volumes = [self.v1, self.v2, self.v3, self.v4]
        max_v = max(volumes)
        bars = VGroup(*[
            Rectangle(width=0.4, height=(v / max_v) * 2.5, fill_opacity=0.6, fill_color=BLUE_E)
            .set_stroke(BLUE_B, 1)
            for v in volumes
        ])
        bars.arrange(RIGHT, buff=0.3, aligned_edge=DOWN).shift(RIGHT * 3.5 + DOWN * 1.0)

        self.play(FadeIn(bars, shift=UP), run_time=2)

    @beat("Five dimensions is bigger still, but it's kind of slowing down.", seconds=4, narration="Five dimensions is bigger still, but it's kind of slowing down, which might give us pause.")
    def dim_5(self):
        self.v5 = self.volume(5)
        t5 = MathTex(rf"n = 5:\quad V \approx {self.v5:.2f}", font_size=36, color=YELLOW).shift(DOWN * 2.3 + LEFT * 3.5)

        volumes = [self.v1, self.v2, self.v3, self.v4, self.v5]
        max_v = max(volumes)
        bars = VGroup(*[
            Rectangle(width=0.3, height=(v / max_v) * 2.5, fill_opacity=0.6, fill_color=TEAL)
            .set_stroke(TEAL_B, 1)
            for v in volumes
        ])
        bars.arrange(RIGHT, buff=0.2, aligned_edge=DOWN).shift(RIGHT * 2.5 + DOWN * 0.5)

        self.play(Write(t5), Transform(self.mobjects[-1] if hasattr(self, 'mobjects') else bars, bars), run_time=3)

    @beat("Then it gets very worrying because at six dimensions it's smaller.", seconds=4, narration="Then it gets very worrying because at six dimensions it's smaller. Like that's weird.")
    def dim_6(self):
        self.v6 = self.volume(6)
        t6 = MathTex(rf"n = 6:\quad V \approx {self.v6:.2f}", font_size=36, color=RED).shift(DOWN * 3.1 + LEFT * 3.5)

        volumes = [self.v1, self.v2, self.v3, self.v4, self.v5, self.v6]
        max_v = max(volumes)
        bars = VGroup(*[
            Rectangle(width=0.25, height=(v / max_v) * 2.5, fill_opacity=0.8, fill_color=RED if i == 5 else BLUE)
            .set_stroke(RED_B if i == 5 else BLUE_B, 1)
            for i, v in enumerate(volumes)
        ])
        bars.arrange(RIGHT, buff=0.15, aligned_edge=DOWN).shift(RIGHT * 2.5 + DOWN * 0.5)

        arrow = Arrow(UP * 0.8, DOWN * 0.1, color=RED).move_to(bars[-1].get_top() + UP * 0.4)
        peak_label = Text("Peak at n=5!", font_size=20, color=RED).next_to(arrow, UP)

        self.play(Write(t6), FadeIn(bars), GrowArrow(arrow), Write(peak_label), run_time=3)

    @beat("Seven is smaller, eight is smaller, nine is smaller—they drop to zero.", seconds=4, narration="Seven is smaller, eight is smaller, nine is smaller. They keep shrinking all the way to zero.")
    def dim_7_to_9(self):
        v7 = self.volume(7)
        v8 = self.volume(8)
        v9 = self.volume(9)

        summary = MathTex(rf"n=7: {v7:.2f},\quad n=8: {v8:.2f},\quad n=9: {v9:.2f} \rightarrow 0", font_size=28, color=RED_C).to_edge(DOWN)

        volumes = [self.v1, self.v2, self.v3, self.v4, self.v5, self.v6, v7, v8, v9]
        max_v = max(volumes)
        bars = VGroup(*[
            Rectangle(width=0.2, height=max(0.05, (v / max_v) * 2.5), fill_opacity=0.8, fill_color=RED_E)
            .set_stroke(RED_A, 1)
            for v in volumes
        ])
        bars.arrange(RIGHT, buff=0.1, aligned_edge=DOWN).shift(RIGHT * 2.5 + DOWN * 0.5)

        self.play(FadeTransform(self.mobjects[-2] if hasattr(self, 'mobjects') else bars, bars), Write(summary), run_time=3)
