import numpy as np

class NeuralNetworkMatrixVector(ForgeScene):
    @beat("Introduce the activation vector", seconds=3, narration="Organize all of the activations from one layer into a column as a vector.")
    def show_activation_vector(self):
        self.vector = Matrix([[r"a_1"], [r"a_2"], [r"a_3"]], h_buff=1.5).shift(LEFT * 3)
        self.label = MathTex(r"\vec{a}").next_to(self.vector, UP)
        self.play(Create(self.vector), Write(self.label))

    @beat("Introduce the weight matrix", seconds=4, narration="Then organize all of the weights as a matrix, where each row of that matrix corresponds to the connections between one layer and a particular neuron in the next layer.")
    def show_weight_matrix(self):
        self.matrix = Matrix([
            [r"w_{1,1}", r"w_{1,2}", r"w_{1,3}"],
            [r"w_{2,1}", r"w_{2,2}", r"w_{2,3}"]
        ], h_buff=1.5).next_to(self.vector, RIGHT, buff=1.5)
        self.m_label = MathTex(r"W").next_to(self.matrix, UP)
        self.play(Create(self.matrix), Write(self.m_label))

    @beat("Show the product setup", seconds=3, narration="What that means is that taking the weighted sum of the activations in the first layer according to these weights...")
    def show_product_setup(self):
        self.equals = MathTex(r"=").next_to(self.matrix, RIGHT)
        self.result = Matrix([[r"\sum w_{1,i} a_i"], [r"\sum w_{2,i} a_i"]], h_buff=3).next_to(self.equals, RIGHT)
        self.play(Write(self.equals), Create(self.result))

    @beat("Highlight the connection", seconds=3, narration="...corresponds to one of the terms in the matrix vector product of everything we have on the left here.")
    def highlight_term(self):
        self.rect = SurroundingRectangle(self.result.get_rows()[0], color=YELLOW)
        self.play(Create(self.rect))
        self.wait(2)

    @beat("Animate the matrix-vector multiplication", seconds=3, narration="This compact notation allows us to compute the entire next layer of activations in a single operation.")
    def animate_multiplication(self):
        group = VGroup(self.vector, self.matrix, self.equals, self.result, self.label, self.m_label, self.rect)
        self.play(group.animate.scale(0.8).shift(UP * 0.5))
        formula = MathTex(r"W \cdot \vec{a} = \vec{a}'").scale(1.2).shift(DOWN * 2)
        self.play(Write(formula))

    @beat("Conclusion", seconds=2, narration="It turns a complex network of individual neurons into clean, efficient linear algebra.")
    def conclusion(self):
        self.play(Indicate(self.matrix), Indicate(self.vector))
        self.wait(1)
