        self.line = Line(start=self.axes.c2p(0, 0), end=self.axes.c2p(1, 0.5), color=RED)
        self.r_label = MathTex("r = \\sqrt{x^2 + y^2}", font_size=36, color=RED).next_to(self.line, DOWN)
        self.play(Write(self.f2_text), Create(self.line), Write(self.r_label))

    @beat("Transition to radial function", seconds=3, narration="...well it can be expressed as some single variable function of the radius r.")
    def transition_to_r(self):
        self.f_r_text = MathTex("g(r)", font_size=48, color=YELLOW).next_to(self.f2_text, DOWN)
        self.equals = MathTex("=", font_size=48).next_to(self.f2_text, DOWN).shift(LEFT*1)
        self.play(ReplacementTransform(self.f2_text.copy(), self.equals), Write(self.f_r_text))

    @beat("Highlight the radial dependency", seconds=3, narration="Since the density depends only on the distance from the center, the output remains identical for any point on the same circle.")
    def highlight_circle(self):
        new_dots = VGroup(*[Dot(point=self.axes.c2p(2*np.cos(theta), 2*np.sin(theta)), color=YELLOW) 
