        self.play(FadeIn(new_dots))
        self.play(Indicate(self.f_r_text))

    @beat("Final summary", seconds=3, narration="This radial symmetry simplifies our calculations by reducing two dimensions down to one.")
    def summary(self):
        rect = SurroundingRectangle(VGroup(self.f_r_text, self.r_label), color=WHITE)
        self.play(Create(rect))
        self.wait(2)
