from manim import *
from forge.beats import ForgeScene, beat

class Determinant3DVolume(ForgeScene, ThreeDScene):
    @beat("Initialize 3D view and unit cube", seconds=3, narration="What do you think it should mean for three dimensions? It also tells you how much a transformation scales things, but this time, it tells you how much volumes get scaled.")
    def init_scene(self):
        self.set_camera_orientation(phi=75 * DEGREES, theta=-45 * DEGREES)
        self.axes = ThreeDAxes(x_range=[-2, 2], y_range=[-2, 2], z_range=[-2, 2])
        self.cube = Cube(side_length=1, fill_opacity=0.3, fill_color=BLUE)
        self.cube.shift(0.5 * RIGHT + 0.5 * UP + 0.5 * OUT)

        self.play(Create(self.axes), Create(self.cube), run_time=2)

    @beat("Label basis vectors", seconds=3, narration="Just as in two dimensions, where this is easiest to think about by focusing on one particular square with an area 1...")
    def label_basis(self):
        ihat = Vector(RIGHT, color=RED).shift(0.5*UP + 0.5*OUT)
        jhat = Vector(UP, color=GREEN).shift(0.5*RIGHT + 0.5*OUT)
        khat = Vector(OUT, color=YELLOW).shift(0.5*RIGHT + 0.5*UP)

        self.play(Create(ihat), Create(jhat), Create(khat), run_time=2)
        self.ihat, self.jhat, self.khat = ihat, jhat, khat

    @beat("Highlight the cube", seconds=3, narration="...and watching only what happens to it, in three dimensions, it helps to focus your attention on the specific 1 by 1 by 1 cube...")
    def highlight_cube(self):
        self.play(self.cube.animate.set_fill(opacity=0.6, color=YELLOW), run_time=2)

    @beat("Show basis vectors", seconds=3, narration="...whose edges are resting on the basis vectors, i-hat, j-hat and k-hat.")
    def show_edges(self):
        labels = VGroup(
            MathTex(r"\hat{i}").next_to(self.ihat, RIGHT),
            MathTex(r"\hat{j}").next_to(self.jhat, UP),
            MathTex(r"\hat{k}").next_to(self.khat, OUT)
        )
        self.play(Write(labels), run_time=2)
        self.labels = labels

    @beat("Animate transformation", seconds=4, narration="When we transform space, this unit volume changes into a new parallelopiped, and the determinant is the volume of that resulting shape.")
    def transform_cube(self):
        matrix = [[1.5, 0.5, 0], [0, 1.2, 0.5], [0.5, 0, 1.5]]

        # Apply transformation to vertices
        new_cube = self.cube.copy()
        new_cube.apply_matrix(matrix)
        new_cube.set_fill(color=PURPLE, opacity=0.5)

        self.play(Transform(self.cube, new_cube), FadeOut(self.labels), run_time=3)

    @beat("Final volume indicator", seconds=3, narration="The change in volume of this unit cube is exactly what the determinant measures in three dimensions.")
    def show_determinant(self):
