from manim import *
from forge.beats import ForgeScene, beat

class HanoiEfficiency(ForgeScene):
    n = 3
    steps = 2**n - 1

    @beat("Initialize the Towers of Hanoi setup", seconds=3, narration="For example, how do you know that every time you're rolling over to the eights place, that disk 3 is necessarily going to be freed up to move?")
    def setup_hanoi(self):
        self.rods = VGroup(*[Line(DOWN*1.5, UP*1.5) for _ in range(3)]).arrange(RIGHT, buff=2.5)
        self.disks = VGroup(*[
            Rectangle(height=0.4, width=1.5 - i*0.3, fill_opacity=1, fill_color=BLUE_D)
            for i in range(self.n)
        ]).arrange(DOWN, buff=0.1).next_to(self.rods[0], DOWN, buff=-1.5)
        self.play(Create(self.rods), LaggedStart(*[FadeIn(d) for d in self.disks], lag_ratio=0.2))

    @beat("Highlight disk 3 in the stack", seconds=3, narration="At the same time, the solution just immediately raises these questions like, where does this come from, why does this work?")
    def highlight_disk(self):
        self.play(Indicate(self.disks[0], color=YELLOW))
        self.wait(1)

    @beat("Show the exponential step count", seconds=3, narration="...and is there a better way of doing this than having to do 2 to the n minus 1 steps?")
    def show_formula(self):
        self.formula = MathTex(r"2^n - 1 = 2^3 - 1 = 7").shift(UP*2)
        self.play(Write(self.formula))

    @beat("Visualize the recursive tree structure", seconds=3, narration="It turns out, not only does this solve Towers of Hanoi...")
    def show_tree(self):
        # Manually grid the dots since arrange_grid is not standard
        dots = VGroup(*[Dot() for _ in range(self.steps)])
        for i, dot in enumerate(dots):
            row, col = divmod(i, 4)
            dot.move_to(np.array([col * 0.5 - 0.75, -row * 0.5 - 0.5, 0]))
        self.tree = dots
        self.play(FadeIn(self.tree))

    @beat("Emphasize optimality", seconds=3, narration="...but it does it in the most efficient way possible.")
    def show_efficiency(self):
        brace = Brace(self.tree, DOWN)
        label = brace.get_text("Optimal Path").set_color(GREEN)
        self.play(Create(brace), Write(label))
        self.wait(1)

    @beat("Conclude with the final count", seconds=2, narration="It is the absolute minimum number of moves.")
    def conclusion(self):
        count_label = Text(f"{self.steps} steps total", font_size=36, color=GREEN).next_to(self.formula, DOWN)
        self.play(Transform(self.formula, count_label))
        self.play(FadeOut(self.rods, self.disks, self.tree))
