    def show_formula(self):
        self.formula = MathTex(r"|\cos(\theta)|", color=RED).to_edge(RIGHT).shift(UP)
        # Replacing Angle with a simple arc path to avoid 3D projection issues
        self.arc = Arc(radius=0.5, start_angle=PI/2, angle=-PI/4, color=RED).shift(LEFT * 1.5)
