    def label_density(self):
        density_label = MathTex(r"\text{Height} = \frac{\text{Probability}}{\text{Width}}").to_edge(RIGHT).shift(UP)
        self.play(FadeOut(self.brace_w, self.brace_h, self.w_text, self.h_text))
        self.play(Write(density_label))
        self.density_label = density_label

    @beat("Calculate area", seconds=3, narration="The other thing to keep in mind is that the total area of all these bars has to equal one...")
    def show_total_area(self):
        heights = [0.1, 0.3, 0.4, 0.2]
        width = 1.0
        total_area = sum([h * width for h in heights])
        area_text = MathTex(f"\\sum \\text{{Area}} = {total_area}").next_to(self.density_label, DOWN)
        self.play(Write(area_text))
        self.area_text = area_text

    @beat("Highlight bars for area", seconds=3, narration="...at every level of the process.")
    def highlight_all(self):
        self.play(*[b.animate.set_fill(YELLOW, opacity=0.8) for b in self.bars])
