        label = Text("Continuous Infinite Range", font_size=36).next_to(line, UP)
        self.play(Create(line), Write(label))
        self.line, self.label = line, label

    @beat("Transition to discrete dice", seconds=3, narration="It'll be a lot easier if we warm up in a setting that's more discrete and finite, like maybe rolling a pair of weighted dice.")
    def transition(self):
        box = Rectangle(width=6, height=2, color=BLUE).shift(DOWN * 1)
        text = Text("Discrete Finite Setting", font_size=36).move_to(box)
        self.play(FadeOut(self.line, self.label), Create(box), Write(text))
        self.box, self.text = box, text

    @beat("Show dice distribution", seconds=4, narration="Here, the animation you're looking at is simulating two weighted dice, and you can probably tell what's going on.")
    def show_dice(self):
        blue_dist = self.get_weighted_dist(bias_low=True)
        red_dist = self.get_weighted_dist(bias_low=False)

        blue_bars = VGroup(*[Rectangle(height=blue_dist[i]*5, width=0.4, color=BLUE, fill_opacity=0.7) 
                             for i in range(6)]).arrange(RIGHT, buff=0.2).shift(LEFT * 2.5 + DOWN * 1)
        red_bars = VGroup(*[Rectangle(height=red_dist[i]*5, width=0.4, color=RED, fill_opacity=0.7) 
                            for i in range(6)]).arrange(RIGHT, buff=0.2).shift(RIGHT * 2.5 + DOWN * 1)

        self.play(FadeOut(self.box, self.text), Create(blue_bars), Create(red_bars))
        self.blue_bars, self.red_bars = blue_bars, red_bars

    @beat("Explain blue die bias", seconds=3, narration="But just to spell it out explicitly, the blue die is following a distribution that seems to be biased towards lower values.")
    def blue_bias(self):
        label = Text("Blue: Biased Low", color=BLUE, font_size=24).next_to(self.blue_bars, UP)
        self.play(Write(label))

    @beat("Explain red die bias", seconds=3, narration="The red die has a distinct distribution.")
    def red_bias(self):
        label = Text("Red: Biased High", color=RED, font_size=24).next_to(self.red_bars, UP)
        self.play(Write(label))

    @beat("Show sampling process", seconds=4, narration="And I'm repeatedly sampling from each one and recording the sum of the two values at each iteration.")
    def sampling(self):
        sum_val = Integer(0).scale(2).shift(UP * 1)
        sum_label = Text("Current Sum:").next_to(sum_val, LEFT)
        self.play(Write(sum_label), Write(sum_val))

        # Simulate sum updates
        for _ in range(5):
            val = np.random.choice([1, 2, 3, 4, 5, 6], p=self.get_weighted_dist(True)/sum(self.get_weighted_dist(True))) + \
                  np.random.choice([1, 2, 3, 4, 5, 6], p=self.get_weighted_dist(False)/sum(self.get_weighted_dist(False)))
            self.play(sum_val.animate.set_value(int(val)), run_time=0.5)
