from manim import *
from forge.beats import ForgeScene, beat

class AlgebraicMassaging(ForgeScene):
    @beat("Introduce the Laplace transform integral form", seconds=4, narration="And at first, this actually seems wrong. It seems inconsistent with the desired conclusion.")
    def show_laplace(self):
        self.eq = MathTex(r"\mathcal{L}\{e^{at}\} = \int_0^\infty e^{at} e^{-st} dt").scale(1.2)
        self.play(Write(self.eq))

    @beat("Highlight the mismatch between s and a", seconds=4, narration="We're not multiplying by s, the input of our new transformed function. Instead, the thing we're multiplying by is this random constant a.")
    def highlight_mismatch(self):
        self.s_term = self.eq[0][9:11]
        self.a_term = self.eq[0][4:6]
        self.play(
            Indicate(self.s_term, color=RED),
            Indicate(self.a_term, color=BLUE)
        )

    @beat("Transition to algebraic manipulation", seconds=4, narration="But this is really just a matter of some gentle algebraic massaging.")
    def show_massaging_intro(self):
        self.step1 = MathTex(r"= \int_0^\infty e^{-(s-a)t} dt").shift(DOWN * 1.5)
        self.play(TransformFromCopy(self.eq, self.step1))

    @beat("Introduce the factor of 1", seconds=4, narration="Notice what happens if I add this fraction, s minus a over s minus a, which is the same as adding 1.")
    def add_fraction(self):
        self.fraction = MathTex(r"\frac{s-a}{s-a} = 1").to_edge(RIGHT)
        self.play(Write(self.fraction))

    @beat("Show the subtraction step", seconds=4, narration="So I have to subtract off 1 to account for it.")
    def subtract_one(self):
        self.full_expr = MathTex(r"1 = \left( \frac{s-a}{s-a} \right) - 0").next_to(self.fraction, DOWN)
        self.play(Write(self.full_expr))

    @beat("Final arrangement", seconds=4, narration="This algebraic manipulation allows us to reveal the structure of the transform.")
    def final_view(self):
        self.final_eq = MathTex(r"F(s) = \frac{1}{s-a} \cdot \left( \frac{s-a}{s-a} \right)").scale(1.2)
        self.play(
            FadeOut(self.eq, self.step1, self.fraction, self.full_expr),
            Write(self.final_eq)
        )
