from manim import *
from forge.beats import ForgeScene, beat
import numpy as np

class ComplexLogPeriodicity(ForgeScene):
    @beat("Introduce the log image on the left and the complex plane on the right", seconds=4, narration="In principle, it can extend out infinitely far in all directions, following the same self-similar pattern as you scale up.")
    def setup_planes(self):
        self.left_plane = NumberPlane(x_range=[-4, 4], y_range=[-4, 4], background_line_style={"stroke_opacity": 0.3}).scale(0.6).shift(LEFT * 3.5)
        self.right_plane = NumberPlane(x_range=[-4, 4], y_range=[-4, 4], background_line_style={"stroke_opacity": 0.3}).scale(0.6).shift(RIGHT * 3.5)
        self.label_left = Text("Log Domain", font_size=24).next_to(self.left_plane, UP)
        self.label_right = Text("Complex Plane", font_size=24).next_to(self.right_plane, UP)
        self.play(Create(self.left_plane), Create(self.right_plane), Write(self.label_left), Write(self.label_right))

    @beat("Show tiling extending rightward in the log plane", seconds=4, narration="and the result for the log image on the left would be to extend as far rightward as you want,")
    def extend_log(self):
        tiles = VGroup(*[Rectangle(width=0.6, height=0.6, fill_opacity=0.2, fill_color=BLUE).move_to(self.left_plane.c2p(i, 0)) for i in range(7)])
        self.play(LaggedStart(*[FadeIn(t) for t in tiles], lag_ratio=0.2))

    @beat("Highlight the repeated pattern", seconds=3, narration="again with a repeated tiling pattern.")
    def repeat_pattern(self):
        copy = VGroup(*[Rectangle(width=0.6, height=0.6, fill_opacity=0.2, fill_color=RED).move_to(self.left_plane.c2p(i, 1)) for i in range(7)])
        self.play(FadeIn(copy))

    @beat("Rotate in the complex plane", seconds=4, narration="So to conclude, the logarithm image on the left is periodic vertically,")
    def rotate_right(self):
        p1 = self.right_plane.c2p(1, 1)
        p2 = self.right_plane.c2p(1, -1)
        arrow = CurvedArrow(start_point=p1, end_point=p2, color=YELLOW)
        self.play(Create(arrow))
        self.play(Rotate(self.right_plane, angle=TAU, about_point=self.right_plane.get_center(), run_time=2))

    @beat("Connect vertical periodicity to rotation", seconds=3, narration="basically because rotation on the right is periodic.")
    def connect_periodicity(self):
        brace = Brace(self.left_plane, LEFT)
        text = brace.get_text("Vertical Periodicity").scale(0.7)
        self.play(Create(brace), Write(text))

