from manim import *
from forge.beats import ForgeScene, beat

class DefiniteIntegralAntiderivative(ForgeScene):
    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self.ax = Axes(x_range=[0, 6, 1], y_range=[0, 4, 1], x_length=8, y_length=4, axis_config={"include_tip": False})
        self.ax.shift(LEFT * 1.5)
        self.func = lambda x: 0.1 * (x - 2)**2 + 1
        self.graph = self.ax.plot(self.func, x_range=[0, 5], color=BLUE)
        self.label = MathTex("f(t)").next_to(self.graph, UP)
        self.t_val = ValueTracker(4)
        self.area = always_redraw(lambda: self.ax.get_area(self.graph, x_range=[0, self.t_val.get_value()], color=YELLOW, opacity=0.5))
        self.t_label = MathTex("T").add_updater(lambda m: m.next_to(self.ax.c2p(self.t_val.get_value(), 0), DOWN))

    @beat("Introduce the integral function", seconds=3, narration="But there is one piece of information we haven't used yet that will let us zero in on which antiderivative to use, the lower bound of the integral.")
    def setup_scene(self):
        self.play(Create(self.ax), Create(self.graph), Write(self.label))
        self.play(FadeIn(self.area), Write(self.t_label))

    @beat("Show the integral as a function of T", seconds=3, narration="This integral has to be zero when we drag that right endpoint all the way to the left endpoint, right?")
    def drag_endpoint(self):
        self.play(self.t_val.animate.set_value(0), run_time=2, rate_func=linear)

    @beat("Explain the zero distance property", seconds=3, narration="The distance travelled by the car between 0 seconds and 0 seconds is… well, zero.")
    def zero_point(self):
        zero_text = Text("Area = 0", font_size=36, color=YELLOW).to_edge(RIGHT)
        self.play(Write(zero_text))
        self.wait(1)
        self.play(FadeOut(zero_text))

    @beat("Show the endpoint moving back", seconds=3, narration="So as we found, the area as a function of capital T is an antiderivative for the stuff inside.")
    def move_back(self):
        self.play(self.t_val.animate.set_value(5), run_time=2)

    @beat("Define the antiderivative relation", seconds=3, narration="This area function, F of T, is the unique antiderivative that satisfies F of 0 equals zero.")
    def display_antiderivative(self):
        self.formula = MathTex(r"F(T) = \int_{0}^{T} f(t) \, dt", font_size=36).to_edge(RIGHT).shift(UP)
        self.condition = MathTex(r"F(0) = 0", font_size=36).next_to(self.formula, DOWN)
        self.play(Write(self.formula), Write(self.condition))

    @beat("Highlight the connection", seconds=3, narration="By fixing the lower bound, we pick exactly one antiderivative out of the infinite family.")
    def final_highlight(self):
        box = SurroundingRectangle(VGroup(self.formula, self.condition), color=RED, buff=0.2)
        self.play(Create(box))
        self.wait(2)
