from manim import *
from forge.beats import ForgeScene, beat

class ConvolutionTruncation(ForgeScene):
    def get_array(self, length, color, y_pos):
        arr = VGroup(*[Square(side_length=0.6, fill_opacity=0.6, fill_color=color) 
                       for _ in range(length)])
        arr.arrange(RIGHT, buff=0.1).move_to(y_pos)
        return arr

    @beat("Introduce the input and kernel arrays", seconds=3, narration="For something like the moving average example, you might only want to think about the terms when both of the windows fully align with each other.")
    def setup_arrays(self):
        self.input = self.get_array(5, BLUE, 1.5)
        self.kernel = self.get_array(3, RED, 0.5)
        self.label_in = Text("Input", font_size=24).next_to(self.input, LEFT)
        self.label_ker = Text("Kernel", font_size=24).next_to(self.kernel, LEFT)
        self.play(Create(self.input), Create(self.kernel), Write(self.label_in), Write(self.label_ker))

    @beat("Show full convolution output", seconds=4, narration="Now, convolutions as a pure math operation always produce an array that's bigger than the two arrays that you started with.")
    def show_full_conv(self):
        # Length of full convolution is L_in + L_ker - 1
        full_len = len(self.input) + len(self.kernel) - 1
        self.full_output = self.get_array(full_len, GREEN, -1.0)
        self.label_out = Text("Full Conv", font_size=24).next_to(self.full_output, LEFT)
        self.play(FadeIn(self.full_output), Write(self.label_out))

    @beat("Highlight the boundary effects", seconds=3, narration="Or in the image processing example, maybe you want the final output to have the same size as the original.")
    def highlight_boundaries(self):
        self.brace = Brace(self.full_output, DOWN)
        self.brace_text = self.brace.get_text("Size: " + str(len(self.full_output)))
        self.play(Create(self.brace), Write(self.brace_text))

    @beat("Show truncation target", seconds=3, narration="Just know that in certain computer science contexts, you often want to deliberately truncate that output.")
    def show_truncation(self):
        # Target size is same as input
        target_len = len(self.input)
        self.target_output = self.get_array(target_len, YELLOW, -1.0)
        self.target_output.align_to(self.full_output, LEFT)
        self.play(ReplacementTransform(self.full_output.copy(), self.target_output), 
                  FadeOut(self.full_output, self.brace, self.brace_text))

    @beat("Label the truncated result", seconds=3, narration="This effectively brings the output back to the dimensions of your original input array.")
    def final_label(self):
        self.label_final = Text("Truncated", font_size=24, color=YELLOW).next_to(self.target_output, LEFT)
        self.play(Write(self.label_final))

    @beat("Final summary", seconds=2, narration="It is a common design choice to ensure your processed data maintains consistent spatial dimensions.")
    def conclusion(self):
        self.play(Indicate(self.target_output))
        self.wait(1)
