from forge.beats import ForgeScene, beat
import numpy as np

class LaplacianIntuition(ForgeScene):
    def setup(self):
        self.grid_size = 5
        self.points = VGroup(*[
            Dot(np.array([x - 2, y - 1.5, 0]), color=BLUE)
            for x in range(self.grid_size) for y in range(self.grid_size)
        ])
        self.center_idx = self.grid_size // 2
        self.center_point = self.points[self.center_idx * self.grid_size + self.center_idx]

    @beat("Introduce the discrete grid", seconds=3, narration="Tuck that away as a meaningful intuition for problems well beyond the heat equation.")
    def show_grid(self):
        self.play(FadeIn(self.points), run_time=2)
        self.play(self.center_point.animate.set_color(YELLOW), run_time=1)

    @beat("Highlight neighbors", seconds=3, narration="Second derivatives give a measure of how a value compares to the average of its neighbors.")
    def highlight_neighbors(self):
        neighbors = VGroup(
            self.points[self.center_idx * self.grid_size + self.center_idx - 1],
            self.points[self.center_idx * self.grid_size + self.center_idx + 1],
            self.points[(self.center_idx - 1) * self.grid_size + self.center_idx],
            self.points[(self.center_idx + 1) * self.grid_size + self.center_idx]
        )
        self.play(neighbors.animate.set_color(RED), run_time=2)
        self.neighbors = neighbors

    @beat("Show average calculation", seconds=3, narration="Hopefully that gives some satisfying added color to the equation.")
    def show_formula(self):
        formula = MathTex(r"\nabla^2 f \approx \frac{1}{4}\sum f_{neighbors} - f_{center}")
        formula.to_edge(RIGHT, buff=1)
        self.play(Write(formula))
        self.formula = formula

    @beat("Animate flux towards average", seconds=3, narration="It's already pretty intuitive when you read it as saying that curved points tend to flatten out.")
    def visualize_flattening(self):
        avg_pos = np.mean([p.get_center() for p in self.neighbors], axis=0)
        self.play(self.center_point.animate.move_to(avg_pos), run_time=2)

    @beat("Show the PDE", seconds=3, narration="But I think there's something even more satisfying about seeing a partial differential equation like this arise.")
    def show_pde(self):
        pde = MathTex(r"\frac{\partial u}{\partial t} = \alpha \nabla^2 u")
        pde.next_to(self.formula, DOWN, buff=1)
        self.play(FadeIn(pde))
        self.pde = pde

    @beat("Conclusion", seconds=3, narration="Thinking about each point as simply tending towards the average of its neighbors.")
    def final_summary(self):
        box = SurroundingRectangle(self.pde, color=YELLOW)
        self.play(Create(box), run_time=2)
        self.wait(1)
