import numpy as np

class MatrixExponentRotation(ForgeScene):
    @beat("Initialize the rotation setup", seconds=3, narration="Hopefully the fact that these line up inspires a little confidence in the claim that matrix exponents really do solve systems like this.")
    def init_setup(self):
        self.eq = MathTex(r"e^{\begin{pmatrix} 0 & -\pi \\ \pi & 0 \end{pmatrix}} = \begin{pmatrix} -1 & 0 \\ 0 & -1 \end{pmatrix}")
        self.eq.to_edge(LEFT, buff=1)
        self.play(Write(self.eq), run_time=2.5)

    @beat("Highlight the specific matrix", seconds=3, narration="This explains the computation we saw at the start, by the way, with the matrix that had negative pi and pi off the diagonals, producing the negative identity.")
    def highlight_matrix(self):
        rect = SurroundingRectangle(self.eq, color=YELLOW)
        self.play(Create(rect), run_time=1.5)
        self.play(FadeOut(rect), run_time=1.5)

    @beat("Visualize the rotation matrix component", seconds=3, narration="This expression is exponentiating a 90 degree rotation matrix times pi...")
    def show_rotation(self):
        self.rot_text = MathTex(r"A = \pi \begin{pmatrix} 0 & -1 \\ 1 & 0 \end{pmatrix} = \pi R_{\pi/2}")
        self.rot_text.next_to(self.eq, DOWN, buff=1)
        self.play(Write(self.rot_text), run_time=2.5)

    @beat("Draw the vector transformation", seconds=4, narration="...which is another way to describe what the Romeo-Juliet setup does after pi units of time.")
    def draw_vector(self):
        plane = NumberPlane(x_range=[-2, 2], y_range=[-2, 2], axis_config={"include_numbers": False})
        plane.scale(0.6).to_edge(RIGHT, buff=1)
        vec = Vector([1, 0], color=BLUE)
        vec.shift(plane.c2p(0, 0))

        self.play(Create(plane), GrowArrow(vec), run_time=2)
        self.play(Rotate(vec, angle=np.pi, about_point=plane.c2p(0, 0)), run_time=2)

    @beat("Show the final identity", seconds=3, narration="When you rotate a vector by pi radians, you simply flip its direction, which is exactly what multiplying by negative one does.")
    def final_identity(self):
        final = MathTex(r"R_{\pi/2}^2 = -I")
        final.next_to(self.rot_text, DOWN, buff=0.5)
        self.play(Write(final), run_time=2)

    @beat("Summary of the relationship", seconds=3, narration="Everything aligns perfectly, confirming that the matrix exponential correctly captures the circular flow of the system.")
    def summary(self):
        self.play(Indicate(self.eq), run_time=2)
