from manim import *
from forge.beats import ForgeScene, beat
import numpy as np

class FourierRectSinc(ForgeScene):
    @beat("Introduce the rect function", seconds=3, narration="The connection comes down to the fact that this rect function is related to the sinc function.")
    def show_rect(self):
        self.axes = Axes(x_range=[-2, 2, 1], y_range=[-0.2, 1.2, 0.5], x_length=5, y_length=3).shift(LEFT * 3.5)
        # Rect function: 1 if |x| < 0.5 else 0
        self.rect = self.axes.plot(lambda x: 1 if -0.5 <= x <= 0.5 else 0, color=BLUE)
        self.rect_label = MathTex(r"\text{rect}(t)").next_to(self.axes, UP)
        self.play(Create(self.axes), Create(self.rect), Write(self.rect_label))

    @beat("Show the sinc function", seconds=3, narration="Specifically, the sinc function, with its characteristic oscillations, is the Fourier transform of the rectangle.")
    def show_sinc(self):
        self.axes_sinc = Axes(x_range=[-4, 4, 1], y_range=[-0.3, 1.1, 0.5], x_length=5, y_length=3).shift(RIGHT * 3.5)
        self.sinc = self.axes_sinc.plot(lambda x: np.sinc(x/np.pi), color=YELLOW)
        self.sinc_label = MathTex(r"\text{sinc}(f)").next_to(self.axes_sinc, UP)
        self.play(Create(self.axes_sinc), Create(self.sinc), Write(self.sinc_label))

    @beat("Draw a transformation arrow", seconds=2, narration="This connection is known as the Fourier transform.")
    def draw_transform(self):
        self.arrow = Arrow(start=LEFT*0.5, end=RIGHT*0.5, color=WHITE).shift(UP * 0.5)
        self.transform_label = Text("Fourier Transform", font_size=24).next_to(self.arrow, UP)
        self.play(GrowArrow(self.arrow), Write(self.transform_label))

    @beat("Visualize frequency components", seconds=3, narration="Think of this as breaking down a function into a sum, or integral, of pure frequencies.")
    def show_frequencies(self):
        # Create a few sinusoids to visualize frequency decomposition
        freqs = VGroup(*[
            self.axes_sinc.plot(lambda x: 0.15 * np.sin(k * x), color=WHITE, stroke_opacity=0.4)
            for k in range(1, 5)
        ])
        self.play(FadeIn(freqs, lag_ratio=0.2))
        self.freq_label = Text("Sum of frequencies", font_size=20, color=GRAY).next_to(self.sinc_label, DOWN)
        self.play(Write(self.freq_label))

    @beat("Highlight strength and phase", seconds=3, narration="The Fourier transform tells you the strength and phase for every constituent frequency.")
    def show_strength(self):
        # Point on the sinc curve to represent strength
        pt = self.axes_sinc.c2p(1, np.sinc(1/np.pi))
        dot = Dot(pt, color=RED)
        line = Line(self.axes_sinc.c2p(1, 0), pt, color=RED)
        text = Text("Strength", font_size=20, color=RED).next_to(dot, RIGHT)
        self.play(Create(line), Create(dot), Write(text))
        self.wait(1)

    @beat("Final summary", seconds=2, narration="It effectively maps the time domain to the frequency domain.")
    def summary(self):
        self.play(Indicate(self.rect), Indicate(self.sinc))
        self.wait(1)
