from fractions import Fraction

class MovingAverageProcess(ForgeScene):
    @beat("Introduce the window width 1/3", seconds=3, narration="So overall it's 1 minus that window width, which is 1 minus 1 third.")
    def show_window_subtraction(self):
        w = Fraction(1, 3)
        self.rect = Rectangle(width=6, height=1, color=BLUE).shift(UP * 1.5)
        self.label = MathTex(f"1 - {w.numerator}/{w.denominator} = {1 - w}").next_to(self.rect, DOWN)

        # Visualize the window
        window = Rectangle(width=6 * float(w), height=1, color=YELLOW, fill_opacity=0.5).align_to(self.rect, LEFT).shift(UP * 1.5)
        self.play(Create(self.rect), FadeIn(window), Write(self.label))

    @beat("Display the plateau function at 0", seconds=3, narration="The value we're going to be computing, the thing that will look stable for a while before it breaks, is the value of this function at the input 0.")
    def show_function_plateau(self):
        axes = Axes(x_range=[-2, 2], y_range=[0, 2], axis_config={"include_tip": False})
        # Plateau function: 1 if |x| < 1/3 else 0
        func = lambda x: 1.0 if abs(x) < 1/3 else 0.0
        graph = axes.plot(func, color=GREEN)
        dot = Dot(axes.c2p(0, 1), color=RED)
        self.play(FadeOut(self.rect, self.label), Create(axes), Create(graph))
        self.play(FadeIn(dot))

    @beat("Highlight the value 1", seconds=2, narration="Which in both of these iterations is equal to 1 because it's inside that plateau.")
    def show_value_one(self):
        val_text = MathTex("f(0) = 1").to_edge(RIGHT)
        self.play(Write(val_text))
        self.current_val = val_text

    @beat("Transition to the next iteration", seconds=3, narration="For the next iteration, we're going to take a moving average of that last function.")
    def transition_to_next(self):
        arrow = Arrow(start=LEFT, end=RIGHT).shift(DOWN * 1)
        text = Text("Moving Average", font_size=36).next_to(arrow, UP)
        self.play(FadeOut(self.current_val), FadeIn(arrow, text))

    @beat("Define the window width 1/5", seconds=3, narration="But this time with the window whose width is 1 fifth.")
    def show_new_window(self):
        w_new = Fraction(1, 5)
        new_window = Rectangle(width=6 * float(w_new), height=0.5, color=ORANGE, fill_opacity=0.5).shift(DOWN * 2)
        label = MathTex(f"w = {w_new.numerator}/{w_new.denominator}").next_to(new_window, RIGHT)
        self.play(Create(new_window), Write(label))

    @beat("Final summary state", seconds=3, narration="This process will be repeated, narrowing our window each time.")
    def final_state(self):
        final_text = Text("Iteration Complete", font_size=30, color=YELLOW).to_edge(UP)
        self.play(Write(final_text), Indicate(self.mobjects[-2])) # Indicate the window
