from fractions import Fraction

class InfiniteSumEquality(ForgeScene):
    @beat("Initialize the number line", seconds=3, narration="To understand why 0.9 repeating equals 1, let's look at the unit interval on a number line.")
    def setup_line(self):
        self.line = NumberLine(x_range=[0, 1.2, 0.1], length=10, include_numbers=True)
        self.dot_one = Dot(self.line.n2p(1), color=YELLOW)
        self.label_one = MathTex("1").next_to(self.dot_one, UP)
        self.play(Create(self.line), FadeIn(self.dot_one), Write(self.label_one))

    @beat("Represent 0.9 as a sum", seconds=5, narration="We can think of 0.9 repeating as an infinite sum: nine-tenths, plus nine-hundredths, plus nine-thousandths, and so on.")
    def show_sum(self):
        self.sum_text = MathTex("0.999\\dots = \\sum_{n=1}^{\\infty} \\frac{9}{10^n}")
        self.sum_text.to_corner(UL, buff=1)
        self.play(Write(self.sum_text))
        self.wait(2)

    @beat("Visualize the first term", seconds=4, narration="Each digit adds a fraction of the remaining distance to one. The first nine-tenths covers most of the way.")
    def first_term(self):
        self.rect = Rectangle(width=9, height=0.2, color=BLUE, fill_opacity=0.5).move_to(self.line.n2p(0.45))
        self.play(Create(self.rect))
        self.wait(2)

    @beat("Visualize the second term", seconds=4, narration="Adding nine-hundredths fills in ninety percent of the remaining gap, leaving only one percent left.")
    def second_term(self):
        new_rect = Rectangle(width=0.9, height=0.2, color=BLUE, fill_opacity=0.5).move_to(self.line.n2p(0.945))
        self.play(Transform(self.rect, VGroup(self.rect, new_rect)))
        self.wait(2)

    @beat("Show the general gap", seconds=5, narration="At any step n, the distance remaining to one is exactly one-tenth to the power of n.")
    def show_gap(self):
        self.gap_brace = Brace(Line(self.line.n2p(0.999), self.line.n2p(1)), UP)
        self.gap_text = self.gap_brace.get_text("$10^{-3}$")
        self.play(Create(self.gap_brace), Write(self.gap_text))

    @beat("Explain the limit", seconds=5, narration="As we add infinite terms, this remaining gap shrinks toward zero. In the limit, it vanishes entirely.")
    def shrink_gap(self):
        self.play(FadeOut(self.gap_brace), FadeOut(self.gap_text))
        self.gap_brace_inf = Brace(Line(self.line.n2p(0.999999), self.line.n2p(1)), UP)
        self.gap_text_inf = self.gap_brace_inf.get_text("$\\to 0$")
        self.play(Create(self.gap_brace_inf), Write(self.gap_text_inf))

    @beat("Algebraic verification", seconds=6, narration="Alternatively, consider x equals 0.9 repeating. Ten x is 9.9 repeating. Subtracting the two gives nine x equals nine, so x must be one.")
    def algebra_proof(self):
        self.eqs = VGroup(
            MathTex("x = 0.999..."),
            MathTex("10x = 9.999..."),
            MathTex("9x = 9"),
            MathTex("x = 1")
        ).arrange(DOWN).to_edge(RIGHT, buff=1)
        self.play(Write(self.eqs[0]))
        self.play(Write(self.eqs[1]))
        self.play(Write(self.eqs[2]))
        self.play(Write(self.eqs[3]))

    @beat("Conclusion", seconds=4, narration="There is no number between 0.9 repeating and 1, so they must be the same point on the number line.")
    def conclude(self):
        self.play(Indicate(self.dot_one), Indicate(self.eqs[3]))
        self.wait(2)

    @beat("Final cleanup", seconds=2, narration="It is not a number that gets close to 1; it is 1, written in a different way.")
    def cleanup(self):
        self.play(FadeOut(self.line, self.rect, self.sum_text, self.eqs, self.dot_one, self.label_one, self.gap_brace_inf, self.gap_text_inf))
