from manim import *
from forge.beats import ForgeScene, beat
import numpy as np

class HexagonTilingLogic(ForgeScene):
    def get_hex(self, center, color=BLUE_D):
        return RegularPolygon(n=6, radius=0.8, color=color, fill_opacity=0.5).move_to(center)

    def get_pent(self, center, color=RED_D):
        return RegularPolygon(n=5, radius=0.8, color=color, fill_opacity=0.5).move_to(center)

    @beat("Introduce the hexagon tile", seconds=4, narration="To tile a plane perfectly, we need shapes that fit together without leaving any gaps.")
    def intro_hex(self):
        self.hex = self.get_hex(ORIGIN)
        self.label = Text("Internal Angle: 120°", font_size=32).to_edge(UP)
        self.play(Create(self.hex), Write(self.label))

    @beat("Show three hexagons meeting", seconds=5, narration="A regular hexagon has an internal angle of 120 degrees. Three of them meeting at a point sum to exactly 360 degrees.")
    def cluster_hex(self):
        self.group_hex = VGroup(*[self.get_hex(0.8 * 1.5 * np.array([np.cos(a), np.sin(a), 0])) 
                        for a in [np.pi/2, 7*np.pi/6, 11*np.pi/6]])
        self.play(FadeIn(self.group_hex))

    @beat("Tiling the plane", seconds=5, narration="Because they fit perfectly, we can repeat this pattern infinitely to cover the entire plane.")
    def tile_plane(self):
        self.hex_grid = VGroup(*[self.get_hex(0.8 * 1.5 * np.array([np.sqrt(3)*x, y + 0.5*(x%2), 0])) 
                                for x in range(-3, 4) for y in range(-3, 3)])
        self.play(FadeOut(self.label), FadeOut(self.group_hex), ReplacementTransform(self.hex, self.hex_grid))

    @beat("Introduce the pentagon", seconds=4, narration="But what happens if we try this with a regular pentagon?")
    def intro_pent(self):
        self.play(FadeOut(self.hex_grid))
        self.pent = self.get_pent(ORIGIN)
        self.p_label = Text("Internal Angle: 108°", font_size=32).to_edge(UP)
        self.play(Create(self.pent), Write(self.p_label))

    @beat("Show three pentagons meeting", seconds=5, narration="A regular pentagon has an internal angle of 108 degrees. Three of them sum to only 324 degrees.")
    def cluster_pent(self):
        self.group_pent = VGroup(*[self.get_pent(0.8 * 1.5 * np.array([np.cos(a + np.pi/2), np.sin(a + np.pi/2), 0])) 
                        for a in [0, 2*np.pi/3, 4*np.pi/3]])
        self.play(Create(self.group_pent))
        self.gap_text = Text("Gap: 36°", color=YELLOW).next_to(self.group_pent, RIGHT)
        self.play(Write(self.gap_text))

    @beat("The failure of tiling", seconds=5, narration="That leaves a 36-degree gap. If we force them together, they won't lay flat.")
    def show_gap(self):
        self.play(Indicate(self.gap_text))
        self.wait(2)

    @beat("Testing four pentagons", seconds=5, narration="What if we try four? That gives us 432 degrees, which is way too much overlap.")
    def four_pents(self):
        self.group_four = VGroup(*[self.get_pent(1.2 * np.array([np.cos(a), np.sin(a), 0])) 
                        for a in [0, np.pi/2, np.pi, 3*np.pi/2]])
        self.overlap_label = Text("432°: Overlap!", font_size=32).to_edge(UP)
        self.play(FadeOut(self.gap_text), FadeOut(self.group_pent), ReplacementTransform(self.p_label, self.overlap_label))
        self.play(Create(self.group_four))

    @beat("Conclusion summary", seconds=4, narration="Tiling relies on the internal angle being a divisor of 360. Pentagons simply don't fit the math.")
    def conclusion(self):
        self.play(FadeOut(self.group_four), FadeOut(self.pent), FadeOut(self.overlap_label))
        conclusion = Text("Divisors of 360° are the key", font_size=36)
        self.play(Write(conclusion))
        self.wait(2)
