        self.wait(1)

    @beat("Show the knight's move", seconds=3, narration="I don't know how this works, I don't know why this works.")
    def move_visual(self):
        # Move to index 10 (which is 2 right, 1 up relative to 0)
        target = self.board[10].get_center()
        self.play(self.knight.animate.move_to(target), run_time=2)

    @beat("Highlight multiple possible moves", seconds=3, narration="Now I know, but it's just magical when you see it.")
    def possible_moves(self):
        # Calculate moves from position 10: (col=1, row=2)
        # Potential knight moves: (c+1, r+2), (c+2, r+1), (c+2, r-1), (c+1, r-2), etc.
        indices = [25, 27, 20, 26]
        dots = VGroup(*[Dot(color=RED).move_to(self.board[i]) for i in indices])
        self.play(FadeIn(dots))
        self.dots = dots
        self.wait(1)

