        self.eq2 = MathTex(f"d = {d}").next_to(self.eq1, DOWN)
        self.play(Write(self.eq1), Write(self.eq2))

    @beat("Show the resulting values 4 and 10", seconds=3, narration="In other words, the two values for this very specific example work out to be 4 and 10.")
    def step_two(self):
        m, d = 7, 3
        v1, v2 = m - d, m + d
        self.result = MathTex(f"\\text{{Values: }} {v1} \\text{{ and }} {v2}").shift(LEFT * 2 + DOWN * 1)
        self.play(ReplacementTransform(self.eq2.copy(), self.result))

    @beat("Transition to general formula", seconds=3, narration="But our goal is a quick trick, and you wouldn't want to think through this each time, so let's wrap up what we just did in a general formula.")
    def step_three(self):
        self.rect = SurroundingRectangle(VGroup(self.eq1, self.result), color=YELLOW)
        self.text = Text("Generalize", font_size=36, color=YELLOW).next_to(self.rect, RIGHT)
        self.play(Create(self.rect), Write(self.text))

    @beat("Introduce variables m and p", seconds=3, narration="For any mean m and product p, the distance squared is always going to be m squared minus p.")
    def step_four(self):
        self.formula = MathTex("d^2 = m^2 - p", font_size=60).shift(RIGHT * 3)
        self.play(FadeIn(self.formula))

    @beat("Highlight components", seconds=3, narration="This relationship links the distance from the mean to the product of the two numbers.")
    def step_five(self):
        self.play(Indicate(self.formula), run_time=1.5)
        self.wait(1.5)

    @beat("Final summary", seconds=3, narration="It's a powerful shortcut for solving these algebraic systems.")
    def step_six(self):
        final_box = SurroundingRectangle(self.formula, color=BLUE, buff=0.3)
        self.play(Create(final_box), self.formula.animate.set_color(BLUE))
        self.wait(2)
