from manim import *
from forge.beats import ForgeScene, beat
from fractions import Fraction

class GaussianPrimeDistribution(ForgeScene):
    # Gaussian integers (2+i) * (2+i) = 3 + 4i
    # (2+i) * (2-i) = 5
    # (2-i) * (2-i) = 3 - 4i

    def get_column(self, items, x_pos):
        group = VGroup(*[MathTex(t, font_size=48) for t in items])
        group.arrange(DOWN, buff=0.5).move_to([x_pos, 0, 0])
        return group

    @beat("Introduce the three distribution scenarios", seconds=3, narration="Now notice, there are three choices for how you can divvy up the primes that can affect this output.")
    def setup_scene(self):
        self.title = Text("Distributing (2+i) and (2-i)", font_size=36).to_edge(UP)
        self.play(Write(self.title))

    @beat("Scenario 1: Both in left", seconds=4, narration="Pictured right here, both copies of 2 plus i are in the left column, and that gives us the product 3 plus 4i.")
    def scenario_one(self):
        left = self.get_column(["2+i", "2+i"], -3)
        right = self.get_column(["1", "1"], 3)
        equals = MathTex("=").scale(2)
        result = MathTex("3+4i").move_to([0, 0, 0])

        self.group = VGroup(left, right, equals, result)
        self.play(FadeIn(left), FadeIn(right), Write(equals), Write(result))

    @beat("Transition to Scenario 2", seconds=3, narration="You could also have chosen to have only one copy of 2 plus i in this left column...")
    def transition_two(self):
        new_left = self.get_column(["2+i", "2-i"], -3)
        self.play(Transform(self.group[0], new_left))

    @beat("Show Result 2", seconds=3, narration="...in which case the product would be 5.")
    def scenario_two(self):
        new_result = MathTex("5").move_to([0, 0, 0])
        self.play(Transform(self.group[3], new_result))

    @beat("Transition to Scenario 3", seconds=3, narration="Or you could have both copies of 2 plus i in that right column...")
    def transition_three(self):
        new_left = self.get_column(["2-i", "2-i"], -3)
        new_right = self.get_column(["2+i", "2+i"], 3)
        self.play(Transform(self.group[0], new_left), Transform(self.group[1], new_right))

    @beat("Show Result 3", seconds=3, narration="...in which case the output of our recipe would have been 3 minus 4i.")
    def scenario_three(self):
        new_result = MathTex("3-4i").move_to([0, 0, 0])
        self.play(Transform(self.group[3], new_result))
