class TilingArgument(ForgeScene):
    k = 4
    grid_size = 2 * k - 1

    def get_grid(self):
        grid = VGroup()
        for i in range(self.grid_size):
            for j in range(self.grid_size):
                sq = Square(side_length=0.6, stroke_color=GRAY, fill_opacity=0.1)
                sq.move_to(0.6 * np.array([j - (self.grid_size-1)/2, i - (self.grid_size-1)/2, 0]))
                grid.add(sq)
        return grid

    @beat("Initialize the grid and highlight the specific x'd squares", seconds=4, narration="There's a much simpler way to argue you need at least k squared minus one tiles by making a one-to-one association.")
    def init_grid(self):
        self.grid = self.get_grid().shift(LEFT * 2)
        self.x_indices = [(i, i) for i in range(self.k)]
        self.x_marks = VGroup(*[
            VGroup(Line(DR*0.2, UL*0.2), Line(DL*0.2, UR*0.2)).move_to(self.grid[i*self.grid_size + j].get_center())
            for i, j in self.x_indices
        ])
        self.play(Create(self.grid), run_time=2)
        self.play(FadeIn(self.x_marks), run_time=2)

    @beat("Highlight the right edges of the x'd squares", seconds=3, narration="Rather than highlighting every edge, just highlight all of their right edges.")
    def highlight_right_edges(self):
        self.right_edges = VGroup(*[
            Line(self.grid[i*self.grid_size + j].get_right(), self.grid[i*self.grid_size + j].get_right() + UP*0.6, color=YELLOW, stroke_width=6)
            for i, j in self.x_indices
        ])
        self.play(Create(self.right_edges), run_time=2)

    @beat("Show tiles touching these edges", seconds=3, narration="Each of those right edges must touch a tile.")
    def show_tiles(self):
        self.tiles = VGroup(*[
            Square(side_length=0.6, fill_color=BLUE, fill_opacity=0.5, stroke_width=0).move_to(self.grid[i*self.grid_size + j + 1].get_center())
            for i, j in self.x_indices
        ])
        self.play(FadeIn(self.tiles), run_time=2)

    @beat("Label the one-to-one mapping", seconds=3, narration="Importantly, any given tile can touch at most one such edge.")
    def explain_mapping(self):
        self.arrows = VGroup(*[
            Arrow(self.right_edges[i].get_center(), self.tiles[i].get_center(), buff=0.1, color=WHITE)
