                if (x + 2)**2 + (y)**2 < 2.0: 
                    pixels.add(Square(side_length=0.18, fill_opacity=0.8, color=BLUE, stroke_width=0).move_to([x, y, 0]))

        self.play(LaggedStart(*[FadeIn(p, scale=0.1) for p in pixels], lag_ratio=0.01))
        self.pixels = pixels

    @beat("Final composition", seconds=3, narration="This process of rasterization turns the mathematical curve into the physical pixels you see.")
    def final_summary(self):
        summary = Text("Rasterization", color=GREEN).to_edge(RIGHT)
        self.play(Write(summary), self.outline.animate.set_stroke(opacity=0.3))
        self.wait(2)
