    def vertical_kernel(self):
        # Kernel: [-1, 0, 1]
        self.kernel = VGroup(*[Square(side_length=0.4, fill_opacity=0.8).set_fill(color=[RED, BLACK, BLUE][i]) 
                               for i in range(3)]).arrange(RIGHT, buff=0)
