from manim import *
from forge.beats import ForgeScene, beat
import numpy as np

class MultiTailParticleSystem(ForgeScene):
    num_dots = 10
    steps = 15

    def get_dot_position(self, i, t):
        # Parametric path for dots
        angle = i * (TAU / self.num_dots)
        x = 3.0 * np.cos(t + angle) + 0.5 * np.sin(2 * t)
        y = 2.0 * np.sin(t * 0.7 - angle) + 0.3 * np.cos(t)
        return np.array([x - 1.5, y, 0.0])

    @beat("Instead of just having one tail, we could have a group of them.", seconds=3, narration="Instead of just having one tail, we could have a group of them.")
    def show_single_tail(self):
        self.t_val = 2.0
        # Compute path for a single dot
        points = [self.get_dot_position(0, self.t_val - k * 0.1) for k in range(self.steps)]

        self.tail_group = VGroup(*[
            Line(points[k], points[k+1], stroke_width=4, stroke_opacity=1.0 - (k / self.steps))
            for k in range(len(points) - 1)
        ])
        self.dot = Dot(points[0], color=BLUE)

        self.play(FadeIn(self.dot), FadeIn(self.tail_group), run_time=2.0)
        self.wait(1.0)

    @beat("So we'll create a group of these tails, not just for the zeroth dot, but for all of the dots.", seconds=3, narration="So we'll create a group of these tails, not just for the zeroth dot, but for all of the dots.")
    def expand_to_all_dots(self):
        self.all_dots = VGroup()
        self.all_tails = VGroup()

        for i in range(self.num_dots):
            pts = [self.get_dot_position(i, self.t_val - k * 0.1) for k in range(self.steps)]
            tail = VGroup(*[
                Line(pts[k], pts[k+1], stroke_width=3, stroke_opacity=0.8 - (k / self.steps)*0.8)
                for k in range(len(pts) - 1)
            ])
            dot = Dot(pts[0])
            self.all_dots.add(dot)
            self.all_tails.add(tail)

        self.play(
            Transform(self.dot, self.all_dots),
            Transform(self.tail_group, self.all_tails),
            run_time=2.5
        )
        self.wait(0.5)

    @beat("For dots and dots.", seconds=2, narration="For dots and dots.")
    def highlight_dots(self):
        # Flash the dots to emphasize plurality and structure
        self.play(
            self.all_dots.animate.set_color(YELLOW),
            run_time=1.0
        )
        self.play(
            self.all_dots.animate.set_color(WHITE),
            run_time=1.0
        )

    @beat("And then I could maybe have it match the color of that dot so that we kind of see them all.", seconds=3, narration="And then I could maybe have it match the color of that dot so that we kind of see them all.")
    def color_match(self):
        colors = color_gradient([BLUE, GREEN, YELLOW, RED, PURPLE], self.num_dots)

        anim_dots = []
        anim_tails = []
        for i, (d, t, c) in enumerate(zip(self.all_dots, self.all_tails, colors)):
            d.set_color(c)
            for line in t:
                line.set_color(c)
            anim_dots.append(Indicate(d, scale_factor=1.2, run_time=1.5))

        self.play(AnimationGroup(*anim_dots, lag_ratio=0.05))
        self.wait(0.5)

    @beat("So now, when we do this, we should see ten different tails all following for a little bit more time.", seconds=3, narration="So now, when we do this, we should see ten different tails all following for a little bit more time.")
    def animate_motion(self):
        # Update function to animate the particle system smoothly
        def update_system(mob, dt):
            self.t_val += dt * 1.5
            colors = color_gradient([BLUE, GREEN, YELLOW, RED, PURPLE], self.num_dots)
            for i, (d, t, c) in enumerate(zip(self.all_dots, self.all_tails, colors)):
                pts = [self.get_dot_position(i, self.t_val - k * 0.12) for k in range(self.steps)]
                d.move_to(pts[0])
                for k, line in enumerate(t):
                    line.put_start_and_end_on(pts[k], pts[k+1])

        self.all_dots.add_updater(update_system)
        self.wait(3.0)
        self.all_dots.remove_updater(update_system)

    @beat("Which I think should just give a nice, oh yeah, yeah, yeah, that gives a nice smooth little effect.", seconds=3, narration="Which I think should just give a nice, oh yeah, yeah, yeah, that gives a nice smooth little effect.")
    def smooth_effect_finale(self):
        # Continue motion with a label highlighting the smooth effect
        def update_system_fast(mob, dt):
            self.t_val += dt * 2.0
            for i, (d, t) in enumerate(zip(self.all_dots, self.all_tails)):
                pts = [self.get_dot_position(i, self.t_val - k * 0.1) for k in range(self.steps)]
                d.move_to(pts[0])
                for k, line in enumerate(t):
                    line.put_start_and_end_on(pts[k], pts[k+1])

        self.all_dots.add_updater(update_system_fast)

        effect_label = Text("Smooth Flow", font_size=32, color=YELLOW).to_edge(UP).shift(RIGHT * 3)
        self.play(FadeIn(effect_label, shift=DOWN), run_time=1.0)
        self.wait(2.0)

        self.all_dots.remove_updater(update_system_fast)
        self.play(FadeOut(effect_label), run_time=0.5)
