        self.board = self.get_board().shift(LEFT * 1.5)
        self.play(Create(self.board))

    @beat("Spawn the knight", seconds=3, narration="We start our knight on the bottom-left corner square.")
    def spawn_knight(self):
        self.knight = Dot(color=YELLOW, radius=0.2).move_to(self.board[0].get_center())
        self.play(FadeIn(self.knight, scale=0.5))

    @beat("Show move logic", seconds=5, narration="The knight must follow its L-shaped movement rule, jumping two squares in one cardinal direction and one perpendicular.")
    def show_logic(self):
        target = self.board[10].get_center()
        arrow = CurvedArrow(self.knight.get_center(), target, angle=-TAU/6, color=YELLOW)
        self.play(Create(arrow))
        self.play(self.knight.animate.move_to(target))
        self.play(FadeOut(arrow))

    @beat("Explain the constraint", seconds=5, narration="The challenge is that every move consumes a square, and we cannot revisit any square during the entire tour.")
    def explain_constraint(self):
        text = Text("No repeats", font_size=36, color=RED).to_edge(RIGHT)
        self.play(Write(text))
        self.text = text

    @beat("Visualize the path", seconds=6, narration="As the knight travels, we leave a trail to mark our progress across the sixty-four squares.")
    def draw_path(self):
        path = [(0, 0), (2, 1), (4, 0), (6, 1), (7, 3), (6, 5), (7, 7), (5, 6), (7, 5), (6, 7), (4, 6), (5, 4)]
        self.lines = VGroup()
        for i in range(len(path) - 1):
            start = self.board[path[i][0] + path[i][1]*8].get_center()
            end = self.board[path[i+1][0] + path[i+1][1]*8].get_center()
            line = Line(start, end, color=YELLOW_A, stroke_width=3)
            self.lines.add(line)
        self.play(LaggedStart(*[Create(l) for l in self.lines], lag_ratio=0.5))

    @beat("Count the progress", seconds=5, narration="We keep track of the count; here we've successfully mapped out the first twelve steps of our journey.")
    def count_steps(self):
        count = Integer(len(self.lines) + 1, font_size=72).next_to(self.text, DOWN)
        label = Text("Squares visited", font_size=24).next_to(count, DOWN)
        self.play(Write(count), Write(label))
        self.count = count

    @beat("Mention the complexity", seconds=5, narration="With 64 squares total, the number of possible paths is astronomically large, making this a classic problem in graph theory.")
    def complexity(self):
        math = MathTex(r"N = 64", font_size=48).next_to(self.count, DOWN, buff=1)
        self.play(Write(math))

    @beat("Highlight the goal", seconds=5, narration="The tour is complete only when the knight lands on the final remaining square, having touched every single one.")
    def goal(self):
        final_sq = self.board[63]
        highlight = SurroundingRectangle(final_sq, color=GREEN)
        self.play(Create(highlight))

    @beat("Conclusion", seconds=3, narration="Solving this requires a systematic approach, often using backtracking algorithms to explore the vast tree of possibilities.")
    def conclusion(self):
        self.play(FadeOut(self.knight), FadeOut(self.lines), FadeOut(self.text))
        self.wait(1)
