from manim import *
from forge.beats import ForgeScene, beat
from fractions import Fraction

class BuoyancyPrinciple(ForgeScene):
    @beat("Introduce the setup", seconds=4, narration="To understand buoyancy, imagine a block resting above a tank of water. The block has a specific weight, and the water is ready to be displaced.")
    def setup_scene(self):
        self.water = Rectangle(width=6, height=3, fill_color=BLUE_D, fill_opacity=0.3, stroke_width=0).shift(DOWN * 1.5)
        water_label = Text("Water Tank", font_size=24).next_to(self.water, UP)
        self.block = Square(side_length=1.5, fill_color=YELLOW_C, fill_opacity=0.8)
        self.block.move_to(UP * 2)

        self.play(FadeIn(self.water), Write(water_label))
        self.play(FadeIn(self.block))

    @beat("Lower the block", seconds=4, narration="As we lower the block into the water, it pushes the liquid aside. This is the core of Archimedes' principle: the object occupies space previously held by water.")
    def lower_block(self):
        self.play(self.block.animate.move_to(DOWN * 0.75))
        self.water_rise = Rectangle(width=6, height=0.75, fill_color=BLUE_D, fill_opacity=0.6).move_to(DOWN * 1.125)
        self.play(Create(self.water_rise))

    @beat("Highlight displaced volume", seconds=5, narration="The volume of the submerged part of the block is exactly equal to the volume of the water that was pushed upward. This displaced volume is key.")
    def highlight_displaced(self):
        self.displaced_rect = SurroundingRectangle(self.water_rise, color=YELLOW_C, buff=0)
        self.play(Create(self.displaced_rect))
        self.label = Text("Displaced Volume", font_size=24, color=YELLOW_C).next_to(self.displaced_rect, RIGHT)
        self.play(Write(self.label))

    @beat("Introduce weight vectors", seconds=5, narration="There are two competing forces here. Gravity pulls the block down, while the buoyant force pushes upward.")
    def weight_vectors(self):
        self.g_vec = Arrow(start=ORIGIN, end=DOWN * 1.5, color=RED).move_to(self.block.get_center()).shift(UP * 0.5)
        self.b_vec = Arrow(start=ORIGIN, end=UP * 1.5, color=GREEN).move_to(self.block.get_center()).shift(DOWN * 0.5)

        g_label = MathTex("F_g").next_to(self.g_vec, RIGHT)
        b_label = MathTex("F_b").next_to(self.b_vec, RIGHT)

        self.play(GrowArrow(self.g_vec), Write(g_label))
        self.play(GrowArrow(self.b_vec), Write(b_label))

    @beat("Define the buoyant force", seconds=5, narration="Archimedes discovered that the upward buoyant force is exactly equal to the weight of the fluid that was displaced.")
    def define_force(self):
        formula = MathTex("F_b = W_{displaced}", font_size=36).to_edge(RIGHT)
        self.play(Write(formula))
        self.play(Indicate(self.displaced_rect))

    @beat("Equilibrium condition", seconds=5, narration="If the object floats, it means the weight of the object is perfectly balanced by the weight of the water it pushed out of the way.")
    def equilibrium(self):
        eq = MathTex("F_g = F_b", color=YELLOW).next_to(self.label, DOWN)
        self.play(Write(eq))

    @beat("Vary density", seconds=5, narration="If the object were denser, it would need to displace more water to stay afloat. If it's denser than water, the buoyant force can never catch up to gravity.")
    def vary_density(self):
        self.play(self.block.animate.set_fill(color=RED, opacity=1.0))
        self.play(self.block.animate.move_to(DOWN * 2.25))
        self.play(FadeOut(self.water_rise), FadeOut(self.displaced_rect))

    @beat("Final summary", seconds=4, narration="So, buoyancy isn't just about floating; it's a precise accounting of mass, volume, and the displaced fluid's weight.")
    def conclusion(self):
        summary = Text("Buoyancy = Weight of Displaced Fluid", font_size=32).to_edge(UP)
        self.play(FadeIn(summary))
        self.wait(2)

    @beat("Clean up", seconds=2, narration="This simple relationship governs everything from small boats to massive ships floating on the ocean.")
    def cleanup(self):
        self.play(FadeOut(self.block), FadeOut(self.water))
