from manim import *
from forge.beats import ForgeScene, beat
import numpy as np

class SineDerivative(ForgeScene):
    def setup(self):
        self.axes = Axes(
            x_range=[-PI, 3 * PI, PI / 2],
            y_range=[-1.5, 1.5, 1],
            axis_config={"include_tip": True}
        ).scale(0.8).shift(LEFT * 1.5)

        self.sine = self.axes.plot(np.sin, color=BLUE)
        self.cosine = self.axes.plot(np.cos, color=YELLOW)
        self.dot = Dot(color=RED)
        self.label = MathTex(r"f(\theta) = \sin(\theta)", color=BLUE).to_corner(UR)

    @beat("Display the sine wave and a tangent slope indicator", seconds=3, narration="Then the slope is negative for a little while, while the sine is decreasing.")
    def show_slope_decreasing(self):
        self.play(Create(self.axes), Create(self.sine), Write(self.label))
        self.dot.move_to(self.axes.c2p(PI / 2, 1))
        tangent = TangentLine(self.sine, alpha=0.5, length=2, color=RED)
        self.play(Create(self.dot), Create(tangent))
        self.wait(1)

    @beat("Show the slope reaching zero at the trough", seconds=3, narration="before coming back up to 0 as the sine graph levels out.")
    def show_trough(self):
        new_dot = Dot(color=RED).move_to(self.axes.c2p(3 * PI / 2, -1))
        tangent = TangentLine(self.sine, alpha=0.75, length=2, color=RED)
        self.play(Transform(self.dot, new_dot), ReplacementTransform(self.sine, self.sine), run_time=1)
        self.play(Create(tangent), run_time=1)

    @beat("Introduce the derivative graph points", seconds=3, narration="And as you continue thinking this through and drawing it out, if you're familiar with the graph of trig functions you might guess...")
    def plot_derivative_points(self):
        points = VGroup(*[Dot(self.axes.c2p(x, np.cos(x)), color=YELLOW, radius=0.05) 
                          for x in np.linspace(-PI, 3 * PI, 20)])
        self.play(LaggedStart(*[FadeIn(p) for p in points], lag_ratio=0.1))

    @beat("Draw the cosine curve through the points", seconds=3, narration="that this derivative graph should be exactly cosine of theta,")
