from manim import *
from forge.beats import ForgeScene, beat

class LimitEpsilonDelta(ForgeScene):
    def get_axes(self):
        return Axes(
            x_range=[-2, 2, 1], 
            y_range=[-1, 3, 1], 
            x_length=6, 
            y_length=4
        ).shift(LEFT * 2)

    @beat("Introduce epsilon-delta limit", seconds=4, narration="The key point here is that that's true for any epsilon, no matter how small, you'll always be able to find the corresponding delta.")
    def show_limit_exists(self):
        self.axes = self.get_axes()
        graph = self.axes.plot(lambda x: x**2, color=BLUE)
        target = Dot(self.axes.c2p(0, 0), color=YELLOW)

        eps = 0.5
        y_min, y_max = self.axes.c2p(0, -eps)[1], self.axes.c2p(0, eps)[1]
        eps_rect = Rectangle(
            width=self.axes.x_length, 
            height=y_max - y_min, 
            fill_color=BLUE, 
            fill_opacity=0.2, 
            stroke_width=0
        ).move_to(self.axes.c2p(0, 0))

        self.play(Create(self.axes), Create(graph), FadeIn(target))
        self.play(FadeIn(eps_rect))
        self.wait(1)

    @beat("Contrast with non-existent limit", seconds=3, narration="In contrast, when a limit does not exist, as in this example here...")
    def show_discontinuity(self):
        self.clear()
        self.axes = self.get_axes()
        graph_left = self.axes.plot(lambda x: 1, x_range=[-2, 0], color=BLUE)
        graph_right = self.axes.plot(lambda x: 2, x_range=[0, 2], color=BLUE)
        self.play(Create(self.axes), Create(graph_left), Create(graph_right))

    @beat("Highlight epsilon choice", seconds=3, narration="...you can find a sufficiently small epsilon, like 0.4, so that...")
    def highlight_epsilon(self):
        eps = 0.4
        y_center = self.axes.c2p(0, 1.5)[1]
        self.eps_line = Line(
            start=self.axes.c2p(-2, 1.5 - eps), 
            end=self.axes.c2p(2, 1.5 - eps)
        ).set_color(RED)
        self.eps_line_top = Line(
            start=self.axes.c2p(-2, 1.5 + eps), 
            end=self.axes.c2p(2, 1.5 + eps)
        ).set_color(RED)
        label = MathTex(r"\epsilon = 0.4", color=RED).next_to(self.eps_line_top, RIGHT)
        self.play(Create(self.eps_line), Create(self.eps_line_top), Write(label))

    @beat("Show the gap", seconds=3, narration="...no matter how small you make your range around 0...")
    def show_delta_range(self):
        delta_width = 0.4
        delta_rect = Rectangle(
            width=delta_width, 
            height=self.axes.y_length, 
            fill_color=YELLOW, 
            fill_opacity=0.3, 
            stroke_width=0
        ).move_to(self.axes.c2p(0, 0))
        self.play(FadeIn(delta_rect))

    @beat("Show output range", seconds=3, narration="...no matter how tiny delta is, the corresponding range of outputs is just always too big.")
    def show_output_mismatch(self):
        output_box = Rectangle(
            width=self.axes.x_length, 
            height=1.0, 
            fill_color=RED, 
            fill_opacity=0.3, 
            stroke_width=0
        ).move_to(self.axes.c2p(0, 1.5))
        self.play(FadeIn(output_box))

    @beat("Final conclusion", seconds=3, narration="The output interval remains trapped across the gap, failing the epsilon condition.")
    def conclude(self):
        text = Text("Gap > 2 * epsilon", font_size=30, color=RED).to_edge(RIGHT)
        self.play(Write(text))
        self.play(Indicate(text))
