from manim import *
from forge.beats import ForgeScene, beat
import math

class BinarySearchVisualization(ForgeScene):
    @beat("Initialize the sorted array", seconds=3, narration="Imagine we have a sorted array of 16 numbers. We want to find a specific target value.")
    def init_array(self):
        self.n = 16
        self.elements = VGroup(*[
            Square(side_length=0.6, fill_opacity=0.5, fill_color=BLUE)
            .set_stroke(WHITE, 1)
            for _ in range(self.n)
        ]).arrange(RIGHT, buff=0.1).shift(DOWN * 0.5)
        self.play(Create(self.elements), run_time=2)

    @beat("Highlight the middle", seconds=4, narration="To find our target, we look at the middle element. This single check lets us discard half the remaining possibilities.")
    def highlight_middle(self):
        mid_idx = self.n // 2
        self.mid_box = self.elements[mid_idx].copy().set_fill(YELLOW, 1)
        self.play(Indicate(self.mid_box, color=YELLOW), run_time=2)
        self.add(self.mid_box)

    @beat("Discard half", seconds=4, narration="Since the array is sorted, if our target is smaller, we know it cannot be in the right half, so we ignore those eight blocks.")
    def discard_half(self):
        discard_group = VGroup(*self.elements[8:])
        self.play(FadeOut(discard_group, shift=UP * 0.5), run_time=2)
        self.remaining_count = Text(f"Remaining: 8", font_size=36).to_edge(UP)
        self.play(Write(self.remaining_count))

    @beat("Repeat the process", seconds=4, narration="We repeat this halving process. Each step reduces the search space by half, reaching the target incredibly quickly.")
    def repeat_step(self):
        new_elements = self.elements[:8]
        new_mid = new_elements[4].copy().set_fill(YELLOW, 1)
        discard_group = VGroup(*new_elements[4:])

        self.play(
            FadeOut(discard_group, shift=UP * 0.5),
            ReplacementTransform(self.mid_box, new_mid),
            self.remaining_count.animate.become(Text(f"Remaining: 4", font_size=36).to_edge(UP)),
            run_time=2
        )
        self.mid_box = new_mid

    @beat("Final conclusion", seconds=5, narration="This logarithmic behavior is why binary search is so powerful; even with millions of items, you only need about twenty steps.")
    def conclusion(self):
        steps = int(math.log2(self.n))
        final_text = Text(f"Log2({self.n}) = {steps} steps", color=GREEN).next_to(self.elements, DOWN, buff=1)
        self.play(Write(final_text), run_time=2)
        self.wait(3)
