from manim import *
from forge.beats import ForgeScene, beat
from fractions import Fraction

class CubeComplements(ForgeScene):
    def get_cube_edges(self, n):
        # A cube has 12 edges. We represent a "n-part cube" as a subset of 12 edges.
        # This is a visualization of the combinatorial duality.
        return n

    @beat("Introduce the 12 edges of a cube", seconds=4, narration="It was only after LeWitt switched to this edge numbering system that we suddenly see him begin to explore cubes and their complements at the same time.")
    def show_cube(self):
        self.cube = VGroup(*[Line(ORIGIN, RIGHT*0.5, color=BLUE) for _ in range(12)])
        self.cube.arrange_in_grid(3, 4, buff=0.2).to_edge(LEFT, buff=1)
        self.play(Create(self.cube), run_time=3)

    @beat("Highlight the total count of 12", seconds=3, narration="And these combinations are useful to consider because the number of edges of a cube and its complement must always add up to 12.")
    def show_total(self):
        self.total_label = MathTex(r"12 \text{ edges total}").to_edge(RIGHT, buff=2)
        self.play(Write(self.total_label))
        self.play(self.cube.animate.set_color(WHITE))

    @beat("Demonstrate 4 and 8 complement", seconds=4, narration="For example, every four part cube has an eight part complement.")
    def show_four_eight(self):
        n = 4
        complement = 12 - n
        subset = VGroup(*self.cube[:n]).set_color(YELLOW)
        comp_set = VGroup(*self.cube[n:]).set_color(RED)

        label = MathTex(f"{n} + {complement} = 12").next_to(self.total_label, DOWN)
        self.play(FadeIn(subset), FadeIn(comp_set), Write(label))
        self.temp_label = label

    @beat("Explore parallel exploration", seconds=3, narration="Thus, LeWitt could basically explore four and eight part cubes in parallel,")
    def parallel_highlight(self):
        self.play(Indicate(self.cube[:4]), Indicate(self.cube[4:]))
        self.wait(1)

    @beat("Show 5 and 7 complement", seconds=4, narration="similarly for five and seven part cubes, and so on.")
    def show_five_seven(self):
        n = 5
        comp = 12 - n
        new_subset = VGroup(*self.cube[:n]).set_color(YELLOW)
        new_comp = VGroup(*self.cube[n:]).set_color(RED)
        new_label = MathTex(f"{n} + {comp} = 12").move_to(self.temp_label)

        self.play(
            ReplacementTransform(self.cube, VGroup(new_subset, new_comp)),
            ReplacementTransform(self.temp_label, new_label)
        )

    @beat("Final summary", seconds=3, narration="This duality allowed for a systematic exploration of all possible configurations.")
    def wrap_up(self):
        self.play(FadeOut(self.total_label), FadeOut(self.temp_label))
        self.play(self.cube.animate.set_color(BLUE).arrange_in_grid(3, 4))
        self.wait(1)
