from manim import *
from forge.beats import ForgeScene, beat
import numpy as np

class FourierRectSincDuality(ForgeScene):
    def setup(self):
        self.rect_func = lambda x: 1 if abs(x) <= 0.5 else 0
        self.sinc_func = lambda x: np.sinc(x)

    @beat("Introduce the Fourier Transform duality", seconds=4, narration="This is a fact that will pop right out of the definition, representative of how individual outputs of the Fourier transform correspond to global information.")
    def show_duality(self):
        left_label = Text("Original Function", font_size=24).shift(LEFT * 3 + UP * 2)
        right_label = Text("Fourier Transform", font_size=24).shift(RIGHT * 3 + UP * 2)

        self.axes_l = Axes(x_range=[-2, 2, 1], y_range=[-0.5, 1.5, 1], axis_config={"include_tip": False}).scale(0.5).shift(LEFT * 3)
        self.axes_r = Axes(x_range=[-4, 4, 1], y_range=[-0.5, 1.5, 1], axis_config={"include_tip": False}).scale(0.5).shift(RIGHT * 3)

        rect = self.axes_l.plot(self.rect_func, color=BLUE)
        sinc = self.axes_r.plot(self.sinc_func, color=YELLOW)

        self.play(Create(self.axes_l), Create(self.axes_r), Write(left_label), Write(right_label))
        self.play(Create(rect), Create(sinc))
        self.rect, self.sinc = rect, sinc

    @beat("Highlight the integral relationship", seconds=4, narration="In our specific case, if you believe this sinc function and the rect function are related, it explains the integral.")
    def show_integral(self):
        integral_text = MathTex(r"\int_{-\infty}^{\infty} \text{sinc}(x) \, dx = \text{rect}(0)", font_size=32).shift(DOWN * 2)
        self.play(Write(integral_text))
        self.integral_text = integral_text

    @beat("Visualize the area", seconds=3, narration="The integral is otherwise a very tricky thing to compute, but we can visualize it as the total signed area under the sinc curve.")
    def shade_area(self):
        area = self.axes_r.get_area(self.sinc, x_range=[-10, 10], color=YELLOW, opacity=0.3)
        self.play(FadeIn(area))
        self.area = area

    @beat("Connect to the rect function", seconds=3, narration="It's saying all that signed area is the same thing as evaluating the rect function at zero.")
    def focus_zero(self):
        dot = Dot(self.axes_l.c2p(0, 1), color=RED)
        self.play(Indicate(dot), Flash(self.axes_l.c2p(0, 1)))
        self.dot = dot

    @beat("Show the final value", seconds=3, narration="And evaluating the rect function at zero, which is just one, gives us our result.")
    def show_value(self):
        result = MathTex("= 1", font_size=32).next_to(self.integral_text, RIGHT)
        self.play(Write(result))
        self.result = result

    @beat("Conclusion of the duality", seconds=3, narration="This beautiful link shows how global integral information is contained within the local value at the origin.")
    def wrap_up(self):
        group = VGroup(self.axes_l, self.axes_r, self.rect, self.sinc, self.integral_text, self.area, self.dot, self.result)
        self.play(group.animate.scale(0.8).shift(UP * 0.5))
        self.wait(1)
