from manim import *
from forge.beats import ForgeScene, beat
import numpy as np

class NewtonFractalReflection(ForgeScene):
    def get_newton_fractal(self, res=100):
        # Representation of a Newton Fractal for z^3 - 1 = 0
        x = np.linspace(-2, 2, res)
        y = np.linspace(-2, 2, res)
        X, Y = np.meshgrid(x, y)
        Z = X + 1j * Y
        for _ in range(10):
            Z = Z - (Z**3 - 1) / (3 * Z**2)
        return Z

    @beat("Introduce the central question", seconds=4, narration="But of course all of this simply raises the question of why this bizarre boundary property would have to be true in the first place, where does it even come from?")
    def question_mark(self):
        self.question = Text("Why?", font_size=96).shift(LEFT * 3)
        self.play(Write(self.question), run_time=2)
        self.wait(2)

    @beat("Transition to Holomorphic Dynamics", seconds=4, narration="For that I'd like to tell you about a field of math which studies this kind of question, it's called holomorphic dynamics.")
    def field_name(self):
        field = Text("Holomorphic Dynamics", color=BLUE).next_to(self.question, DOWN, buff=1)
        self.play(FadeIn(field, shift=UP), run_time=2)
        self.wait(2)

    @beat("Acknowledge the scope", seconds=4, narration="And I think we've covered enough ground today, and there's certainly enough left to tell, so it makes sense to pull that out as a separate video.")
    def transition_text(self):
        self.play(FadeOut(self.question), FadeOut(self.mobjects[1]))
        self.note = Text("To be continued...", slant=ITALIC).move_to(ORIGIN)
        self.play(Write(self.note), run_time=2)

    @beat("Show Newton's portrait", seconds=4, narration="To close things off here, there is something sort of funny to me about the fact that we call this Newton's fractal...")
    def newton_portrait(self):
        self.play(FadeOut(self.note))
        self.title = Text("Newton's Fractal", font_size=48).to_edge(UP)
        self.newton_name = Text("Isaac Newton", font_size=36).shift(LEFT * 3)
        self.play(Write(self.title), Write(self.newton_name))

