    @beat("Final arrangement", seconds=4, narration="This algebraic manipulation allows us to reveal the structure of the transform.")
    def final_view(self):
        self.final_eq = MathTex(r"F(s) = \frac{1}{s-a} \cdot \left( \frac{s-a}{s-a} \right)").scale(1.2)
