class FifthRootsOfUnity(ForgeScene):
    @beat("Show z^5 = 1", seconds=3, narration="If you just presented someone with this equation, they would probably say the answer is clearly z equals one.")
    def eq_start(self):
        self.eq = MathTex("z^5 = 1", font_size=60)
        self.sol = MathTex("z = 1", font_size=50, color=YELLOW).next_to(self.eq, DOWN)
        self.play(Write(self.eq))
        self.play(FadeIn(self.sol, shift=UP))
        self.wait()

    @beat("Show complex plane", seconds=4, narration="But the idea is that there are four other answers in the complex plane.")
    def complex_plane(self):
        self.plane = ComplexPlane(x_range=[-2, 2, 1], y_range=[-2, 2, 1]).scale(0.8).shift(RIGHT * 2)
        self.circle = Circle(radius=1.6, color=WHITE).move_to(self.plane.get_origin())

        # Compute 5th roots
        self.roots = [np.exp(2 * np.pi * 1j * k / 5) for k in range(5)]
        self.dots = VGroup(*[
            Dot(self.plane.n2p(r), color=YELLOW if k == 0 else RED) 
            for k, r in enumerate(self.roots)
        ])

        self.play(self.eq.animate.to_edge(LEFT, buff=1), FadeOut(self.sol))
        self.play(Create(self.plane), Create(self.circle))
        self.play(LaggedStart(*[GrowFromCenter(d) for d in self.dots], lag_ratio=0.2))

    @beat("Label roots", seconds=4, narration="These numbers have a special name, they're called the fifth roots of unity, essentially because they solve the equation z to the fifth equals one.")
    def label_roots(self):
        label = Text("Fifth roots of unity", font_size=30).to_edge(UP)
        self.play(Write(label))
        self.play(self.dots.animate.set_color(GREEN))
