from manim import *
from forge.beats import ForgeScene, beat
import numpy as np

class LocusEquidistant(ForgeScene):
    @beat("Introduce two fixed points", seconds=4, narration="Let's consider two fixed points in a plane, which we'll call A and B.")
    def show_points(self):
        self.pA = Dot(LEFT * 2, color=BLUE).scale(2)
        self.pB = Dot(RIGHT * 2, color=BLUE).scale(2)
        self.labelA = MathTex("A").next_to(self.pA, UP)
        self.labelB = MathTex("B").next_to(self.pB, UP)
        self.play(FadeIn(self.pA, self.pB, self.labelA, self.labelB))

    @beat("Pick a test point", seconds=5, narration="Now, imagine a point P that moves around the plane. What does it mean for this point to be equidistant from A and B?")
    def show_test_point(self):
        self.pP = Dot(UP * 2 + RIGHT * 0.5, color=YELLOW).scale(1.5)
        self.labelP = MathTex("P", color=YELLOW).next_to(self.pP, UP)
        self.line1 = DashedLine(self.pA.get_center(), self.pP.get_center(), color=BLUE_D)
        self.line2 = DashedLine(self.pB.get_center(), self.pP.get_center(), color=BLUE_D)
        self.play(FadeIn(self.pP, self.labelP))
        self.play(Create(self.line1), Create(self.line2))

    @beat("Show distance labels", seconds=5, narration="We define the locus as the set of all points where the distance to A is exactly equal to the distance to B.")
    def show_distances(self):
        self.dist1 = MathTex("d_1", color=BLUE_D).next_to(self.line1, LEFT, buff=0.1)
        self.dist2 = MathTex("d_2", color=BLUE_D).next_to(self.line2, RIGHT, buff=0.1)
        self.play(Write(self.dist1), Write(self.dist2))
        self.eq = MathTex("d_1 = d_2").to_corner(UL)
        self.play(Write(self.eq))

    @beat("Animate the point moving", seconds=6, narration="As we move point P, the distances change, but we are specifically interested in the path where these two lengths remain perfectly balanced.")
    def animate_path(self):
        path = VMobject()
        path.set_points_smoothly([UP * 2 + RIGHT * 0.5, UP * 1 + RIGHT * 0, DOWN * 1 + RIGHT * 0, DOWN * 2 + RIGHT * 0.5])

        def update_lines(m):
            m.put_start_and_end_on(self.pA.get_center(), self.pP.get_center())

        def update_lines2(m):
            m.put_start_and_end_on(self.pB.get_center(), self.pP.get_center())

        self.line1.add_updater(update_lines)
        self.line2.add_updater(update_lines2)
        self.play(MoveAlongPath(self.pP, path), run_time=5, rate_func=linear)
        self.line1.remove_updater(update_lines)
        self.line2.remove_updater(update_lines2)

    @beat("Trace the locus", seconds=5, narration="If you trace every single valid position for P, a clear geometric shape begins to emerge.")
    def trace_locus(self):
        self.locus = Line(UP * 4, DOWN * 4, color=RED)
        self.play(Create(self.locus), run_time=3)

    @beat("Highlight the perpendicular bisector", seconds=5, narration="This line is the perpendicular bisector of the segment AB. It hits the midpoint at a 90-degree angle.")
    def show_properties(self):
        midpoint = Dot(ORIGIN, color=WHITE)
        angle = RightAngle(Line(ORIGIN, RIGHT), Line(ORIGIN, UP), length=0.3)
        self.play(FadeIn(midpoint), Create(angle))

    @beat("Explain the symmetry", seconds=5, narration="Every point on this line is equidistant because the line acts as a mirror, reflecting point A onto point B.")
    def show_symmetry(self):
        arrow = DoubleArrow(self.pA.get_center(), self.pB.get_center(), color=GRAY)
        self.play(Create(arrow))
        self.play(FadeOut(arrow))

    @beat("Summarize", seconds=4, narration="So, the locus of points equidistant from two fixed points is always the perpendicular bisector of the segment connecting them.")
    def summary(self):
        self.final_text = Text("Perpendicular Bisector", font_size=36, color=RED).to_corner(DR)
        self.play(Write(self.final_text))
        self.play(Indicate(self.locus))

    @beat("Cleanup", seconds=3, narration="It is a fundamental result that links distance, symmetry, and linear geometry.")
    def cleanup(self):
        self.play(FadeOut(*self.mobjects))
