class SubsetSumDivisibility(ForgeScene):
    def get_poly_string(self, n):
        # Represents (1+x^1)(1+x^2)...(1+x^n)
        return MathTex(r"P(x) = \prod_{k=1}^{" + str(n) + r"} (1 + x^k)")

