    def recap_start(self):
        self.q = Text("Count subsets of {1, ..., 2000}", font_size=32).next_to(self.rect, DOWN, buff=0.5)
        self.cond = Text("Sum divisible by 5", font_size=32, color=YELLOW).next_to(self.q, DOWN)
        self.play(FadeIn(self.q), FadeIn(self.cond))

    @beat("Define the set", seconds=3, narration="So we started with this question asking us, count the number of subsets of 1 up to 2000 whose sum is divisible by 5.")
