        self.play(FadeIn(img))
        self.play(self.kernel.animate.shift(LEFT*1.5), run_time=2)

    @beat("Rotate the kernel", seconds=4, narration="And similarly, if we rotated that grid around so that it varies as you move from the top to the bottom...")
