    @beat("Show the horizontal edges", seconds=4, narration="...this will be picking up on all the horizontal edges...")
    def horizontal_result(self):
        img_h = self.get_grid(5, 5, lambda r, c: 1 if r > 2 else 0)
        self.play(ReplacementTransform(self.kernel.copy(), img_h))

