from manim import *
from forge.beats import ForgeScene, beat
from fractions import Fraction

class ConvolutionWedge(ForgeScene):
    @beat("Initialize axes and variables", seconds=3, narration="Each of the two variables can only get as low as negative one half, so the sum could never get below negative one.")
    def setup_scene(self):
        self.axes = Axes(x_range=[-2, 2, 1], y_range=[-0.5, 1.5, 0.5], axis_config={"include_tip": True})
        self.axes.scale(0.8).shift(LEFT * 2)

        # Represent two uniform distributions U(-0.5, 0.5)
        self.rect1 = Rectangle(width=1.6, height=1.6, color=BLUE, fill_opacity=0.3).move_to(self.axes.c2p(-0.5, 0.5))
        self.rect2 = Rectangle(width=1.6, height=1.6, color=RED, fill_opacity=0.3).move_to(self.axes.c2p(0.5, 0.5))

        self.play(Create(self.axes), FadeIn(self.rect1), FadeIn(self.rect2))

    @beat("Slide s to the right", seconds=4, narration="As I start to slide s to the right and the graphs overlap with each other, the area increases linearly...")
    def slide_overlap(self):
        self.s_tracker = ValueTracker(-1.0)
        self.rect2.add_updater(lambda m: m.move_to(self.axes.c2p(self.s_tracker.get_value() + 0.5, 0.5)))

        self.overlap_area = always_redraw(lambda: Intersection(
            self.rect1, self.rect2, color=PURPLE, fill_opacity=0.6
        ))
        self.add(self.overlap_area)
        self.play(self.s_tracker.animate.set_value(0), run_time=3)

    @beat("Reach maximum overlap", seconds=3, narration="...until the graphs overlap entirely and it reaches a maximum.")
    def reach_max(self):
        self.play(self.s_tracker.animate.set_value(0.5), run_time=2)
        self.max_label = Text("Max", font_size=24).next_to(self.axes.c2p(0, 1.5), UP)
        self.play(Write(self.max_label))

    @beat("Slide past maximum", seconds=3, narration="And then after that point it starts to decrease linearly again,")
    def decrease_overlap(self):
        self.play(self.s_tracker.animate.set_value(1.5), run_time=3)

    @beat("Draw the wedge distribution", seconds=4, narration="which means that the distribution for the sum takes on this kind of wedge shape.")
    def draw_wedge(self):
        # The PDF of the sum of two U(-0.5, 0.5) is a triangular distribution on [-1, 1]
        wedge = Polygon(
            self.axes.c2p(-1, 0),
            self.axes.c2p(0, 1),
            self.axes.c2p(1, 0),
            color=YELLOW, stroke_width=4, fill_opacity=0.3
        )
        self.play(FadeOut(self.rect1, self.rect2, self.overlap_area, self.max_label), 
                  Create(wedge), run_time=2)
        self.wedge = wedge

    @beat("Final look", seconds=2, narration="This triangular shape is the classic result of convolving two uniform distributions.")
    def final_view(self):
        label = MathTex(r"f_S(s) = 1 - |s|").next_to(self.axes, RIGHT, buff=1)
        self.play(Write(label))
        self.wait(1)
