    def write_equation(self):
        self.eq1 = MathTex(r"A\mathbf{v} = \lambda \mathbf{v}").to_edge(RIGHT).shift(UP * 1.5)
        self.eq2 = MathTex(r"A\mathbf{v} - \lambda I\mathbf{v} = 0").next_to(self.eq1, DOWN, buff=0.5)

        self.play(Write(self.eq1), run_time=1.5)
        self.play(TransformMatchingTex(self.eq1.copy(), self.eq2), run_time=1.5)

    @beat("...what you see is that if the number lambda is an eigenvalue of a matrix A, then the matrix A minus lambda times the identity...", seconds=4, narration="...what you see is that if the number lambda is an eigenvalue of a matrix A, then the matrix A minus lambda times the identity...")
