            .move_to(self.xy(Cell(r, c)))
            for r in range(1, 5) for c in range(1, 5)
        ])
        self.play(FadeIn(self.center_squares, lag_ratio=0.03), run_time=2.5)

    @beat("If you continue like this, what you end up with is a very pleasing slightly tilted 4 by 4 pattern of square tiles,", seconds=4, narration="If you continue like this, what you end up with is a very pleasing slightly tilted 4 by 4 pattern of square tiles,")
    def show_tiles(self):
        # Highlight them as the 4x4 tile pattern
        label = Text("4 × 4 tiles", font_size=32, color=BLUE_C).to_edge(RIGHT, buff=1.0).shift(UP * 1.5)
        self.play(
            self.center_squares.animate.set_fill(BLUE_D, opacity=0.4),
            Write(label),
            run_time=3.0
        )
        self.tile_label = label

    @beat("each one with a windmill of Xs around it", seconds=4, narration="each one with a windmill of Xs around it")
    def add_windmills(self):
        # Place Xs around the tiles forming windmill patterns
        self.xs = VGroup()
        # Compute positions for 25 Xs in a 5x5 grid layout of points surrounding the 4x4 tiles
        positions = []
        for r in range(5):
            for c in range(5):
                pos = self.xy(Cell(r, c)) + np.array([0.4, -0.4, 0])
                positions.append(pos)

        self.xs = VGroup(*[
            Text("X", font_size=28, color=YELLOW_C).move_to(pos)
            for pos in positions
        ])
        self.play(LaggedStart(*[FadeIn(x, scale=0.5) for x in self.xs], lag_ratio=0.04), run_time=3.5)

    @beat("using 25 Xs in total.", seconds=3, narration="using 25 Xs in total.")
    def count_xs(self):
        count_val = len(self.xs)
        count_label = Text(f"{count_val} Xs total", font_size=32, color=YELLOW_C).to_edge(RIGHT, buff=1.0).shift(UP * 0.5)
        self.play(
            *[x.animate.set_color(YELLOW_A) for x in self.xs],
            Write(count_label),
            run_time=2.5
        )
        self.count_label = count_label

    @beat("And you'll notice these Xs really do sit in distinct rows and columns,", seconds=4, narration="And you'll notice these Xs really do sit in distinct rows and columns,")
    def show_grid_lines(self):
        # Draw horizontal and vertical grid lines passing through the Xs
        grid_lines = VGroup()
        for i in range(5):
            y_coord = self.xy(Cell(i, 0))[1] - 0.4
            h_line = Line(start=[-2.8 - 0.4, y_coord, 0], end=[0.4 - 0.4 + 4*0.8, y_coord, 0], stroke_width=1, stroke_color=GRAY)
            grid_lines.add(h_line)

            x_coord = self.xy(Cell(0, i))[0] + 0.4
            v_line = Line(start=[x_coord, -2.8 + 0.4, 0], end=[x_coord, 0.4 + 4*0.8 - 0.4, 0], stroke_width=1, stroke_color=GRAY)
            grid_lines.add(v_line)

        self.play(Create(grid_lines, lag_ratio=0.05), run_time=3.5)
        self.grid_lines = grid_lines

