import numpy as np

class PolarSpiralVisualization(ForgeScene):
    def get_point(self, n):
        # n is the step number (0, 1, 2, 3)
        # angle = n radians, radius = n units
        angle = n
        radius = n
        return np.array([radius * np.cos(angle), radius * np.sin(angle), 0])

    @beat("Initialize the coordinate system", seconds=3, narration="And to get to 3,3, you rotate one more radian, with a total angle that's now slightly less than a half turn, since 3 is slightly less than pi.")
    def init_axes(self):
        self.axes = Axes(x_range=[-4, 4], y_range=[-4, 4], axis_config={"include_tip": True})
        self.dot = Dot(color=YELLOW)
        self.label = MathTex("(3, 3)", color=YELLOW).next_to(self.dot, UP)
        self.play(Create(self.axes), run_time=1.5)
        self.play(FadeIn(self.dot), Write(self.label), run_time=1.5)

    @beat("Animate the growing radius", seconds=3, narration="And you step one unit farther away from the origin.")
    def grow_radius(self):
        # Show path from 0 to 3
        path = VMobject()
        path.set_points_smoothly([self.get_point(i) for i in np.linspace(0, 3, 20)])
        path.set_stroke(color=BLUE, width=4)
        self.play(Create(path), self.dot.animate.move_to(self.get_point(3)), run_time=2.5)

    @beat("Emphasize the plot structure", seconds=3, narration="I really want you to make sure that it's clear what's being plotted, because everything that follows depends on understanding it.")
    def highlight_plot(self):
        self.rect = SurroundingRectangle(self.axes, color=WHITE, buff=0.1)
        self.play(Create(self.rect), run_time=2.5)

    @beat("Represent the clock hand analogy", seconds=3, narration="Each step forward is like the tip of a clock hand, which rotates one radian with each tick.")
    def clock_hand(self):
        self.hand = Line(ORIGIN, self.get_point(3), color=RED)
        self.play(Create(self.hand), run_time=2)
        self.play(Rotate(self.hand, angle=0.5, about_point=ORIGIN), run_time=1)

    @beat("Show the angular step", seconds=3, narration="A little less than a sixth of a turn.")
    def angular_step(self):
        # 1 radian is approx 57 degrees, 1/6 of a turn is 60 degrees.
        arc = Arc(radius=1.5, start_angle=0, angle=1, color=GREEN)
        label = MathTex("1 \\text{ rad}", color=GREEN).next_to(arc, RIGHT)
        self.play(Create(arc), Write(label), run_time=2.5)

    @beat("Conclude growth", seconds=3, narration="And it grows by one unit at each step.")
    def growth_final(self):
        steps = VGroup(*[Dot(self.get_point(i), color=WHITE, radius=0.05) for i in range(4)])
        self.play(FadeIn(steps), run_time=2)
        self.play(FadeOut(self.rect), run_time=1)
