from manim import *
from forge.beats import ForgeScene, beat
import numpy as np

class VelocityToArea(ForgeScene):
    def get_velocity_graph(self):
        axes = Axes(x_range=[0, 6, 1], y_range=[0, 4, 1], axis_config={"include_tip": False})
        curve = axes.plot(lambda x: 0.1 * x**2 + 1, x_range=[0, 5])
        return axes, curve

    @beat("Introduce velocity over time", seconds=3, narration="In a case like that, you might range through many different points in time.")
    def setup_graph(self):
        self.axes, self.curve = self.get_velocity_graph()
        self.axes.shift(LEFT * 2)
        self.curve.shift(LEFT * 2)
        self.play(Create(self.axes), Create(self.curve))

    @beat("Highlight a small dt interval", seconds=4, narration="And at each one multiply the velocity at that time times a tiny change in time, dt.")
    def show_dt(self):
        t = 3.0
        rect_width = 0.5
        rect = self.axes.get_riemann_rectangles(self.curve, x_range=[t, t + rect_width], dx=rect_width, fill_opacity=0.6)
        label = MathTex("v(t) \\cdot dt").next_to(rect, UP)
        self.play(Create(rect), Write(label))
        self.rect, self.label = rect, label

    @beat("Show accumulation of distance", seconds=3, narration="Which would give the corresponding little bit of distance traveled during that little time.")
    def show_distance(self):
        dist_text = Text("Distance = Area", font_size=30, color=YELLOW).to_edge(RIGHT)
        self.play(FadeOut(self.label), FadeIn(dist_text))
        self.dist_text = dist_text

    @beat("Transition to integral concept", seconds=3, narration="I'll talk through the details of examples like this later in the series.")
    def transition(self):
        dots = VGroup(*[Dot(self.axes.c2p(x, 0.1 * x**2 + 1)) for x in np.linspace(0, 5, 10)])
        self.play(FadeIn(dots), run_time=2)
        self.dots = dots

    @beat("Fill area under curve", seconds=4, narration="But at a high level many of these types of problems turn out to be equivalent to finding the area under some graph.")
    def fill_area(self):
        area = self.axes.get_area(self.curve, x_range=[0, 5], color=BLUE, fill_opacity=0.3)
        self.play(FadeOut(self.dots), FadeOut(self.rect), Create(area))
        self.area = area

    @beat("Compare to circle problem", seconds=3, narration="In much the same way that our circle problem did.")
    def conclusion(self):
        circle = Circle(radius=0.8, color=RED).shift(RIGHT * 3 + UP * 1)
        circle_label = Text("Circle Area", font_size=24).next_to(circle, DOWN)
        self.play(Create(circle), Write(circle_label))
        self.wait(2)
