from manim import *
from forge.beats import ForgeScene, beat
import numpy as np

class SoftmaxTemperature(ForgeScene):
    def get_distribution(self, logits, t=1.0):
        exp_vals = np.exp(np.array(logits) / t)
        return exp_vals / np.sum(exp_vals)

    @beat("Introduce the logits and the Softmax concept", seconds=4, narration="But it's softer than just picking the max in the sense that when other values are similarly large, they also get meaningful weight in the distribution.")
    def show_softmax(self):
        logits = [2.0, 1.8, 0.5]
        probs = self.get_distribution(logits)
        self.bars = VGroup(*[Rectangle(height=p * 4, width=0.8, fill_opacity=0.8, color=BLUE) 
                             for p in probs]).arrange(RIGHT, buff=0.5).to_edge(LEFT, buff=1)
        labels = VGroup(*[DecimalNumber(p, num_decimal_places=2).next_to(b, UP) for b, p in zip(self.bars, probs)])
        self.play(Create(self.bars), Write(labels), run_time=3)
        self.labels = labels

    @beat("Show continuous variation", seconds=3, narration="And everything changes continuously as you continuously vary the inputs.")
    def vary_inputs(self):
        new_logits = [2.0, 2.2, 0.5]
        new_probs = self.get_distribution(new_logits)
        new_bars = VGroup(*[Rectangle(height=p * 4, width=0.8, fill_opacity=0.8, color=BLUE) 
                            for p in new_probs]).arrange(RIGHT, buff=0.5).to_edge(LEFT, buff=1)
        self.play(Transform(self.bars, new_bars), 
                  *[n.animate.set_value(p) for n, p in zip(self.labels, new_probs)], run_time=2)

    @beat("Introduce the Temperature parameter", seconds=3, narration="In some situations, like when ChatGPT is using this distribution to create a next word, there's room for a little bit of extra fun.")
    def intro_temp(self):
        self.formula = MathTex(r"\sigma(z)_i = \frac{e^{z_i / T}}{\sum e^{z_j / T}}").to_edge(RIGHT, buff=1)
        self.play(Write(self.formula), run_time=2)

    @beat("Highlight the T constant", seconds=3, narration="By adding a little extra spice into this function, with a constant T thrown into the denominator of those exponents.")
    def highlight_t(self):
        box = SurroundingRectangle(self.formula[0][4:6], color=YELLOW)
        self.play(Create(box), run_time=2)
        self.box = box

    @beat("Show high temperature effect (flattening)", seconds=3, narration="With a high temperature, the distribution flattens out, giving more weight to less likely options.")
    def high_temp(self):
        probs = self.get_distribution([2.0, 1.8, 0.5], t=2.0)
        new_bars = VGroup(*[Rectangle(height=p * 4, width=0.8, fill_opacity=0.8, color=YELLOW) 
                            for p in probs]).arrange(RIGHT, buff=0.5).to_edge(LEFT, buff=1)
        self.play(Transform(self.bars, new_bars),
                  *[n.animate.set_value(p) for n, p in zip(self.labels, probs)], run_time=2)

    @beat("Show low temperature effect (sharpening)", seconds=3, narration="Conversely, a low temperature makes the model more confident, sharpening the peak.")
    def low_temp(self):
        probs = self.get_distribution([2.0, 1.8, 0.5], t=0.5)
        new_bars = VGroup(*[Rectangle(height=p * 4, width=0.8, fill_opacity=0.8, color=RED) 
                            for p in probs]).arrange(RIGHT, buff=0.5).to_edge(LEFT, buff=1)
        self.play(Transform(self.bars, new_bars),
                  *[n.animate.set_value(p) for n, p in zip(self.labels, probs)], run_time=2)
