from fractions import Fraction

class BreastCancerBayes(ForgeScene):
    # Setup constants based on the prompt
    prevalence = Fraction(1, 100)
    sensitivity = Fraction(90, 100)
    specificity = Fraction(91, 100)

    @beat("Introduce the population", seconds=3, narration="Apart from the screening result, you know nothing else about this woman.")
    def intro(self):
        self.woman = Dot(color=PINK).scale(2)
        self.label = Text("Unknown Woman", font_size=36).next_to(self.woman, DOWN)
        self.play(FadeIn(self.woman), Write(self.label))

    @beat("Display the prevalence", seconds=3, narration="In that seminar, the doctors were then told that the prevalence of breast cancer for women of this age is about 1%.")
    def show_prevalence(self):
        self.stat_group = VGroup(
            Text(f"Prevalence: {self.prevalence * 100:.0f}%", font_size=32),
            Text(f"Sensitivity: {self.sensitivity * 100:.0f}%", font_size=32),
            Text(f"Specificity: {self.specificity * 100:.0f}%", font_size=32)
        ).arrange(DOWN, aligned_edge=LEFT).to_edge(RIGHT, buff=1)

        self.play(
            self.woman.animate.shift(LEFT*3),
            self.label.animate.shift(LEFT*3),
            FadeIn(self.stat_group[0])
        )

    @beat("Display test parameters", seconds=3, narration="And then to suppose that the test sensitivity is 90% and that its specificity was 91%.")
    def show_params(self):
        self.play(FadeIn(self.stat_group[1], shift=UP), FadeIn(self.stat_group[2], shift=UP))

    @beat("Highlight connection", seconds=3, narration="You might notice these are exactly the same numbers from the example that you and I just looked at.")
    def highlight_connection(self):
        box = SurroundingRectangle(self.stat_group, color=YELLOW, buff=0.2)
        self.play(Create(box))
        self.play(Indicate(box))
        self.box = box

    @beat("Source note", seconds=3, narration="This is where I got them.")
    def source(self):
        arrow = Arrow(start=self.box.get_left(), end=self.woman.get_right())
        self.play(GrowArrow(arrow))
        self.wait(1)
        self.play(FadeOut(arrow))

    @beat("Recall answer", seconds=3, narration="So, having already thought it through, you and I know the answer.")
    def conclusion(self):
        # Calculate posterior probability P(C|+) = (0.01 * 0.9) / (0.01 * 0.9 + 0.99 * 0.09)
        # = 0.009 / (0.009 + 0.0891) = 0.009 / 0.0981 = 90 / 981 ≈ 0.0917
        posterior = (self.prevalence * self.sensitivity) / (self.prevalence * self.sensitivity + (1 - self.prevalence) * (1 - self.specificity))
        ans_text = Text(f"Posterior Probability: {float(posterior):.1%}", color=GREEN).to_edge(DOWN)
        self.play(Write(ans_text))
        self.play(self.woman.animate.set_color(GREEN))
