    @beat("Initialize the canvas with a target destination and obstacles", seconds=3, narration="Okay. And then the red can kind of come under.")
    def init_scene(self):
        self.start = Dot(LEFT * 5 + DOWN * 2, color=BLUE)
        self.target = Dot(RIGHT * 5 + UP * 2, color=RED)
        self.obstacle = Rectangle(height=3, width=1, fill_opacity=0.5, color=GREY).shift(UP * 0.5)
        self.label = Text("Target", font_size=24).next_to(self.target, UP)
        self.play(Create(self.start), Create(self.target), Create(self.obstacle), Write(self.label))

    @beat("Draw a path that gets 'under' the obstacle", seconds=3, narration="Nice. And there we go.")
    def path_under(self):
        self.path = VMobject(color=RED, stroke_width=6)
        self.path.set_points_smoothly([self.start.get_center(), LEFT * 2 + DOWN * 2, RIGHT * 0.5 + DOWN * 2, self.target.get_center()])
