        self.stuck_label = Text("Stuck!", color=RED, font_size=30).next_to(dot, UP)
        self.play(Write(self.stuck_label))

    @beat("Draw the detour path around the obstacle", seconds=3, narration="So look, I'm gonna draw this to here like that.")
    def draw_detour(self):
        detour = ArcBetweenPoints(self.stuck_label.get_center(), self.target.get_center(), angle=PI/3, color=GREEN)
        self.play(Create(detour), run_time=2)
        self.wait(1)
