from manim import *
from forge.beats import ForgeScene, beat
import numpy as np

class DerivativeSensitivity(ForgeScene):
    @beat("Introduce the function f(x) = x^2", seconds=3, narration="Now I'd encourage you not to think of this derivative as slope idea as being the definition of a derivative.")
    def setup_axes(self):
        self.axes = Axes(x_range=[-2, 2, 1], y_range=[-0.5, 4, 1], axis_config={"include_tip": True})
        self.graph = self.axes.plot(lambda x: x**2, color=BLUE)
        self.label = MathTex("f(x) = x^2").to_corner(UL)
        self.play(Create(self.axes), Create(self.graph), Write(self.label))

    @beat("Show a point and a tiny nudge", seconds=4, narration="Instead think of it as being more fundamentally about how sensitive the function is to tiny little nudges around the input.")
    def show_nudge(self):
        self.x0 = 1.0
        self.dx = 0.4
        self.dot = Dot(self.axes.c2p(self.x0, self.x0**2), color=YELLOW)
        self.nudge_line = Line(
            self.axes.c2p(self.x0, self.x0**2), 
            self.axes.c2p(self.x0 + self.dx, (self.x0 + self.dx)**2),
            color=YELLOW
        )
        self.play(FadeIn(self.dot), Create(self.nudge_line))
        self.play(self.nudge_line.animate.set_length(0.5), run_time=2)

    @beat("Highlight the change in output", seconds=3, narration="You are looking at how much the output changes in response to that small input variation.")
    def highlight_delta(self):
        dy = (self.x0 + self.dx)**2 - self.x0**2
        self.bracket = Brace(Line(self.axes.c2p(0, self.x0**2), self.axes.c2p(0, (self.x0+self.dx)**2)), RIGHT)
        self.dy_text = MathTex(f"\\Delta y \\approx {dy:.2f}").next_to(self.bracket, RIGHT)
        self.play(Create(self.bracket), Write(self.dy_text))

    @beat("Contrast with slope", seconds=4, narration="And the slope is just one way to think about that sensitivity, relevant only to this particular way of viewing functions.")
    def show_slope(self):
        tangent = TangentLine(self.graph, alpha=0.5, length=2, color=RED)
        slope_text = Text("Slope view", color=RED, font_size=24).next_to(tangent, UP)
        self.play(Create(tangent), Write(slope_text))
        self.play(FadeOut(self.bracket, self.dy_text))

    @beat("Clear the screen for the call to action", seconds=3, narration="I have not just another video, but a full series on this topic if it's something you want to learn more about.")
    def transition(self):
        self.play(
            FadeOut(self.graph), FadeOut(self.axes), FadeOut(self.dot),
            FadeOut(self.nudge_line), FadeOut(self.label)
        )
        self.series_text = Text("Calculus Series", font_size=60).move_to(ORIGIN)
        self.play(Write(self.series_text))

    @beat("Final logo reveal", seconds=2, narration="Check the link in the description to dive deeper.")
    def outro(self):
        self.play(self.series_text.animate.scale(0.5).to_edge(UP))
        self.rect = SurroundingRectangle(self.series_text, color=BLUE)
        self.play(Create(self.rect))
        self.wait(1)
