from manim import *
from forge.beats import ForgeScene, beat
from fractions import Fraction

class HammingErrorCorrection(ForgeScene):
    def get_binary(self, n, bits=4):
        return format(n, f'0{bits}b')

    @beat("Introduce the parity check results as binary bits", seconds=3, narration="If you read out the answers to the four parity checks we did in the last video, all as 1s and 0s instead of yeses and nos, it literally spells out the position of the error in binary.")
    def show_binary_concept(self):
        self.title = Text("Error Position: 7", font_size=36).to_edge(UP)
        binary_val = self.get_binary(7, 4)
        self.binary_text = Text(binary_val, font="Monospace", font_size=96, color=YELLOW)
        self.play(Write(self.title), Write(self.binary_text))

    @beat("Decompose the number 7 into powers of 2", seconds=3, narration="For example, the number 7 in binary looks like 0111, essentially saying that it's 4 plus 2 plus 1.")
    def decompose_seven(self):
        eq = MathTex("7_{10} = 4 + 2 + 1 = 0111_2").scale(1.2)
        self.play(ReplacementTransform(self.binary_text, eq))
        self.current_eq = eq

    @beat("Setup a visual representation of parity groups", seconds=3, narration="And notice where the position 7 sits, it does affect the first of our parity groups, and the second, and the third, but not the last.")
    def setup_parity_groups(self):
        self.groups = VGroup(*[Text(f"Group {i+1}") for i in range(4)]).arrange(DOWN, buff=0.5).to_edge(LEFT)
        self.play(FadeOut(self.current_eq), FadeIn(self.groups))

    @beat("Highlight the groups affected by position 7", seconds=3, narration="It affects the first of our parity groups, and the second, and the third...")
    def highlight_active(self):
        self.active_indicators = VGroup(*[
            Circle(radius=0.2, color=GREEN, fill_opacity=0.5).next_to(self.groups[i], RIGHT)
            for i in range(3)
        ])
        self.play(LaggedStart(*[FadeIn(ind) for ind in self.active_indicators], lag_ratio=0.5))

    @beat("Show that the last group is not affected", seconds=3, narration="...but not the last.")
    def show_inactive(self):
        cross = Cross(self.groups[3], stroke_color=RED)
        self.play(Create(cross))

    @beat("Final summary view", seconds=3, narration="This binary pattern acts like a map, pointing exactly to the bit that flipped.")
    def summary(self):
        summary = Text("Binary Pattern = Error Index", font_size=32, color=BLUE).to_edge(DOWN)
        self.play(Write(summary))
        self.wait(2)
