from manim import *
from forge.beats import ForgeScene, beat

class ChainRuleOscillation(ForgeScene):

    @beat("Initialize the function expression", seconds=3, narration="Taking the derivative with respect to x, we still get negative sine, but the chain rule tells us to multiply that omega on the outside.")
    def init_eq(self):
        self.eq = MathTex("f(x) = \\cos(\\omega x)")
        self.d1 = MathTex("f'(x) = -\\omega \\sin(\\omega x)")
        VGroup(self.eq, self.d1).arrange(DOWN, buff=1.5).shift(LEFT * 2)
        self.play(Write(self.eq))
        self.play(TransformMatchingTex(self.eq.copy(), self.d1))

    @beat("Compute the second derivative", seconds=3, narration="And similarly the second derivative will still be negative cosine, but now with omega squared.")
    def d2_eq(self):
        self.d2 = MathTex("f''(x) = -\\omega^2 \\cos(\\omega x)")
        self.d2.next_to(self.d1, DOWN, buff=1.5).align_to(self.d1, LEFT)
        self.play(Write(self.d2))

    @beat("Highlight the omega squared term", seconds=3, narration="This means that the right hand side of our equation has now picked up this omega squared term.")
    def highlight_term(self):
        box = SurroundingRectangle(self.d2[0][2:4], color=YELLOW)
        label = Text("omega squared", font_size=24, color=YELLOW).next_to(box, RIGHT)
        self.play(Create(box), Write(label))
        self.wait(1)
        self.play(FadeOut(box), FadeOut(label))

    @beat("Show the balancing equation", seconds=3, narration="So to balance things out, on the left hand side, the exponential decay part should have an additional omega squared term up top.")
    def balance_eq(self):
        self.left = MathTex("e^{\\omega^2 t}")
        self.left.set_color(BLUE)
        self.left.to_edge(RIGHT, buff=2)
        self.arrow = Arrow(self.d2.get_right(), self.left.get_left())
        self.play(Write(self.left), GrowArrow(self.arrow))

    @beat("Final summary animation", seconds=3, narration="This adjustment ensures that our differential equation remains consistent with the oscillatory behavior.")
    def summary(self):
        self.rect = SurroundingRectangle(VGroup(self.d2, self.left), color=GREEN)
        self.play(Create(self.rect))
        self.play(self.d2.animate.set_color(GREEN), self.left.animate.set_color(GREEN))
        self.wait(1)

    @beat("Clear for final look", seconds=2, narration="And that is how the chain rule forces the omega squared term into the exponent.")
    def end(self):
        self.play(FadeOut(self.eq), FadeOut(self.d1), FadeOut(self.arrow), FadeOut(self.rect))
        self.play(VGroup(self.d2, self.left).animate.move_to(ORIGIN))
