    def show_grid(self):
        self.grid = VGroup(*[
            Square(side_length=0.5, stroke_width=1, fill_opacity=0).move_to(RIGHT * 2 + UP * (i - 2) * 0.5)
            for i in range(self.layer1_size)
        ])
        self.play(ReplacementTransform(self.labels.copy(), self.grid))

    @beat("Color code positive weights", seconds=3, narration="And I'm going to use green pixels to indicate positive weights.")
    def color_positive(self):
        weights = [0.8, -0.5, 0.2, -0.9, 0.4]
        anims = []
        for i, w in enumerate(weights):
            if w > 0:
                self.grid[i].set_fill(GREEN, opacity=w)
                anims.append(FadeIn(self.grid[i]))
        self.play(*anims)

    @beat("Color code negative weights", seconds=3, narration="And red pixels to indicate negative weights, where the brightness of that pixel is some loose depiction of the weight's value.")
