from forge.beats import ForgeScene, beat
import numpy as np

class SphereGeometryAnalysis(ForgeScene, ThreeDScene):
    @beat("Set up the 3D scene with a sphere", seconds=3, narration="Of course, the meat here comes from showing why these two competing effects cancel each other out, and in some ways the details fleshing this out are just as pretty as the zoomed out structure of the full argument.")
    def setup_scene(self):
        self.set_camera_orientation(phi=75 * DEGREES, theta=30 * DEGREES)
        self.axes = ThreeDAxes(x_range=[-3, 3, 1], y_range=[-3, 3, 1], z_range=[-3, 3, 1])
        self.sphere = Sphere(radius=2, fill_opacity=0.3, color=BLUE)
        self.play(Create(self.axes), Create(self.sphere))

    @beat("Cut the sphere in half", seconds=3, narration="So let's dig in. Let me go ahead and cut away half of the sphere so that we can get a better look.")
    def cut_sphere(self):
        # We use a hemisphere by restricting u_range to [0, PI]
        self.half_sphere = Sphere(radius=2, fill_opacity=0.4, color=BLUE, u_range=(0, PI))
        self.play(ReplacementTransform(self.sphere, self.half_sphere))

    @beat("Label the radius r", seconds=3, narration="For any mathematical problem solving, it never hurts to start by giving things names. So let's say that the radius of the sphere is r.")
    def label_radius(self):
        radius_line = Line(ORIGIN, [2, 0, 0], color=YELLOW)
        r_label = MathTex("r", color=YELLOW).next_to(radius_line.get_center(), UP)
        self.play(Create(radius_line), Write(r_label))
        self.radius_group = VGroup(radius_line, r_label)

    @beat("Add a rectangle cross section", seconds=3, narration="And for one specific rectangle...")
    def add_rectangle(self):
        d = 1.2
        h = np.sqrt(2**2 - d**2)
        # Rectangle in the yz-plane at x=d
        self.rect = Polygon(
            [d, -h, -h], [d, h, -h], 
            [d, h, h], [d, -h, h],
            color=RED, fill_opacity=0.6
        )
        self.play(Create(self.rect))

    @beat("Label the distance d", seconds=3, narration="...let's call the distance between that rectangle and the z-axis d.")
