import numpy as np

class SymmetrySymmetry(ForgeScene):
    @beat("Introduce the 2D square rotation symmetry", seconds=3, narration="Recall how in the 2D case, the 180 degree rotation splits the square into two pairs of parallel sides.")
    def rotate_square(self):
        self.square = Square(side_length=2.5, color=BLUE).rotate(PI/4)
        self.side_pairs = VGroup(
            Line(self.square.get_vertices()[0], self.square.get_vertices()[1], color=RED, stroke_width=8),
            Line(self.square.get_vertices()[2], self.square.get_vertices()[3], color=RED, stroke_width=8),
            Line(self.square.get_vertices()[1], self.square.get_vertices()[2], color=YELLOW, stroke_width=8),
            Line(self.square.get_vertices()[3], self.square.get_vertices()[0], color=YELLOW, stroke_width=8)
        )
        self.play(Create(self.square))
        self.play(Create(self.side_pairs))
        self.wait(1)

    @beat("Transition to 3D cube structure", seconds=3, narration="A similar thing happens here.")
    def show_cube(self):
        self.cube = Cube(side_length=2.5, fill_opacity=0.3, stroke_width=2).rotate(PI/6, axis=UP).rotate(PI/6, axis=RIGHT)
        self.play(FadeOut(self.square), FadeOut(self.side_pairs))
        self.play(Create(self.cube))

    @beat("Isolate the top layer", seconds=3, narration="The top square gets split into two separate subsets, each unaffected by a 180 degree rotation.")
    def top_layer(self):
        top_face = Square(side_length=2.5).set_fill(BLUE, 0.5).rotate(PI/6, axis=UP).rotate(PI/6, axis=RIGHT).shift(UP*1.25)
        self.subsets = VGroup(
            Line(top_face.get_vertices()[0], top_face.get_vertices()[2], color=RED, stroke_width=6),
            Line(top_face.get_vertices()[1], top_face.get_vertices()[3], color=RED, stroke_width=6)
        )
        self.play(FadeIn(top_face))
        self.play(Create(self.subsets))

    @beat("Divide remaining layers", seconds=3, narration="And the other layers get similarly divided into pairs.")
    def other_layers(self):
        middle_layers = VGroup(*[
            Square(side_length=2.5).set_fill(GREEN, 0.2).rotate(PI/6, axis=UP).rotate(PI/6, axis=RIGHT).shift(UP * (1.25 - i * 1.25))
            for i in range(1, 3)
        ])
        self.play(FadeIn(middle_layers))

    @beat("Count the degrees of freedom", seconds=3, narration="So overall, this results in six independent choices, suggesting 64 lookalikes.")
    def calculate_lookalikes(self):
        choices = 6
        lookalikes = 2 ** choices
        self.text = Text(f"{choices} independent choices", font_size=36).to_edge(RIGHT)
        self.result = Text(f"Result: 2^{choices} = {lookalikes} lookalikes", font_size=40, color=GOLD).next_to(self.text, DOWN)
        self.play(Write(self.text))
        self.play(Write(self.result))

    @beat("Final summary view", seconds=3, narration="This structure helps us navigate the symmetry group of the object.")
    def finalize(self):
        self.play(self.cube.animate.rotate(PI, axis=UP), run_time=2)
        self.wait(1)
