from manim import *
from forge.beats import ForgeScene, beat
import numpy as np

class SocialDistancingSimulation(ForgeScene):
    # Simulation grid layout
    rows, cols = 10, 10
    grid_size = 4

    def get_pos(self, i, j, offset):
        x = offset[0] + (j - self.cols/2) * (self.grid_size / self.cols)
        y = offset[1] + (i - self.rows/2) * (self.grid_size / self.rows)
        return np.array([x, y, 0])

    @beat("Initialize 4 simulation grids", seconds=3, narration="No isolation is perfect, though, so every now and then even those repulsed by each other will jiggle close enough to get infected.")
    def init_grids(self):
        offsets = [(-3.5, 2), (3.5, 2), (-3.5, -2), (3.5, -2)]
        self.grids = VGroup()
        for off in offsets:
            g = VGroup(*[Dot(self.get_pos(r, c, off), radius=0.05, color=BLUE) 
                         for r in range(self.rows) for c in range(self.cols)])
            self.grids.add(g)
        self.play(FadeIn(self.grids), run_time=2)

    @beat("Highlight rare interactions", seconds=3, narration="The point is that those interactions are much rarer.")
    def highlight_rarity(self):
        # Pick a few random dots to "infect"
        infected = VGroup(self.grids[0][12], self.grids[1][45], self.grids[2][88], self.grids[3][5])
        self.play(infected.animate.set_color(RED), run_time=2)

    @beat("Define the threshold", seconds=3, narration="Let's take a look at four separate runs here. In each one of them, after we hit 50 cases, I'll turn on social distancing.")
    def show_threshold(self):
        count = len(self.grids) * 50 // 100 # Showing the logic of 50%
        label = Text(f"Threshold: 50 cases", font_size=24).to_edge(UP)
        self.play(Write(label))
        self.wait(1)

    @beat("Setup top-left condition", seconds=3, narration="But in the top left, we'll turn it on for everybody.")
    def top_left_all(self):
        box = SurroundingRectangle(self.grids[0], color=YELLOW, buff=0.1)
        text = Text("100% Distancing", font_size=20, color=YELLOW).next_to(box, UP)
        self.play(Create(box), Write(text))

