            x_range=[-3, 3, 0.5], y_range=[-3, 3, 0.5], padding=1
        )
        self.play(Create(stream_lines))
        self.stream_lines = stream_lines

    @beat("Animate the cycle", seconds=4, narration="The two of you will go back and forth between affection and repulsion in an endless cycle.")
