from manim import *
from forge.beats import ForgeScene, beat
import numpy as np

class FourierEpicycles(ForgeScene):
    def get_f_points(self, n=100):
        # Parametric approximation of an 'f' shape
        t = np.linspace(0, 2 * np.pi, n)
        x = 0.5 * np.cos(t) + 0.2 * np.sin(3 * t)
        y = 1.5 * np.sin(t) - 0.5 * np.cos(t)
        return [np.array([x[i], y[i], 0]) for i in range(n)]

    @beat("Initialize the canvas with an f-shape", seconds=3, narration="For finitely many vectors, this tracing usually won't be a perfect replica of the target shape, which in this animation is a lowercase f.")
    def setup_shape(self):
        self.path = VMobject(color=BLUE, stroke_width=4)
        self.points = self.get_f_points()
        self.path.set_points_smoothly(self.points)
        self.label = Text("Target: 'f'", font_size=24).to_edge(UP)
        self.play(Create(self.path), Write(self.label))

    @beat("Show the summation of circles", seconds=4, narration="But the more circles you include, the closer it gets.")
    def show_circles(self):
        self.circles = VGroup()
        curr_pos = ORIGIN
        for i in range(5):
            radius = 1.0 / (i + 1)
            c = Circle(radius=radius, color=WHITE, stroke_opacity=0.3).move_to(curr_pos)
            self.circles.add(c)
            curr_pos += [radius, 0, 0]
        self.play(LaggedStart(*[FadeIn(c) for c in self.circles], lag_ratio=0.2))

    @beat("Display the 100-circle approximation", seconds=4, narration="What you're seeing now uses only 100 circles, and I think you'd agree that the deviations from the real shape are negligible.")
    def show_n_circles(self):
        self.count_text = Text(f"{len(self.points)} circles", font_size=32, color=YELLOW).to_edge(RIGHT)
        self.play(FadeOut(self.circles), Write(self.count_text))
        self.play(Indicate(self.path))

    @beat("Highlight the vector parameters", seconds=4, narration="What's mind-blowing is that just by tweaking the initial size and angle of each vector...")
    def tweak_vectors(self):
        arrow = Arrow(ORIGIN, [1, 0.5, 0], color=RED)
        label = MathTex(r"r_n, \theta_n", font_size=36).next_to(arrow, UP)
        self.play(FadeIn(arrow), Write(label))
        self.play(Rotate(arrow, angle=PI/4, about_point=ORIGIN))

    @beat("Show the transformation to a new curve", seconds=4, narration="...that gives you enough control to approximate any curve you want.")
    def morph_shape(self):
        new_points = [p * 0.8 for p in self.points]
        new_path = VMobject(color=GREEN, stroke_width=4).set_points_smoothly(new_points)
        self.play(ReplacementTransform(self.path, new_path))
        self.play(new_path.animate.shift(LEFT * 2))

    @beat("Final summary", seconds=3, narration="It is a beautiful demonstration of how complex shapes decompose into simple, rotating components.")
    def finish(self):
        self.play(FadeOut(self.count_text), FadeOut(self.label))
        self.wait(2)
