from manim import *
from forge.beats import ForgeScene, beat
import random

class MCMCShuffleExplanation(ForgeScene):
    def setup(self):
        self.grid_size = 5
        self.cells = VGroup(*[
            Square(side_length=1.0, fill_opacity=0.3, stroke_width=2)
            for _ in range(self.grid_size**2)
        ]).arrange_in_grid(self.grid_size, self.grid_size, buff=0.1).shift(LEFT * 2)

        self.state = [0] * (self.grid_size**2)
        for i in range(5):
            self.state[i] = 1

    @beat("Introduce the grid and the initial state", seconds=4, narration="So how are we getting the samples you're seeing on the screen right now? Well, you probably noticed that the simulation is continuously changing over time.")
    def show_grid(self):
        for i, cell in enumerate(self.cells):
            if self.state[i] == 1:
                cell.set_fill(BLUE, opacity=0.8)
        self.play(Create(self.cells), run_time=3)

    @beat("Clarify that we don't jump to a final sample", seconds=3, narration="So we're not just getting a sample from the Boltzmann distribution in one go.")
    def not_one_go(self):
        label = Text("Not a single jump", font_size=36, color=RED).to_edge(RIGHT)
        self.play(Write(label), run_time=2)
        self.play(FadeOut(label))

    @beat("Show small random changes", seconds=4, narration="Instead, we're making a bunch of small, manageable random changes to the picture that eventually lead to a proper sample.")
    def random_changes(self):
        idx = random.randint(0, len(self.cells)-1)
        new_color = BLUE if self.state[idx] == 0 else BLACK
        self.state[idx] = 1 - self.state[idx]
        self.play(self.cells[idx].animate.set_fill(new_color, opacity=0.8 if self.state[idx] else 0.3), run_time=1)

    @beat("Use the card shuffle analogy", seconds=3, narration="You can think of this like shuffling cards.")
    def card_analogy(self):
        cards = VGroup(*[Rectangle(height=1.5, width=1, fill_color=WHITE, fill_opacity=1) for _ in range(4)]).arrange(RIGHT, buff=0.2).shift(RIGHT * 3)
        self.play(FadeIn(cards, shift=UP), run_time=2)

    @beat("Show randomness being added", seconds=3, narration="Each time you shuffle, a little bit of randomness is added,")
    def shuffle_action(self):
        self.play(Rotate(self.cells, angle=0.1), run_time=1)
        self.play(Rotate(self.cells, angle=-0.1), run_time=1)

    @beat("Conclude with the uniform distribution concept", seconds=4, narration="and eventually you get a roughly uniform distribution on the arrangements of cards.")
    def final_state(self):
        dist_label = Text("Uniform Distribution", font_size=30).next_to(self.cells, UP)
        self.play(Write(dist_label), run_time=2)
        self.play(self.cells.animate.set_fill(opacity=0.5), run_time=2)
