from manim import *
from forge.beats import ForgeScene, beat
import numpy as np

class HeatEquationDetour(ForgeScene):
    def get_sine_wave(self, t=0):
        # Heat equation solution: u(x, t) = sin(pi * x) * exp(-pi^2 * t)
        # We model the rod from x=0 to x=1
        x_vals = np.linspace(0, 1, 50)
        y_vals = np.sin(np.pi * x_vals) * np.exp(-(np.pi**2) * t)
        return x_vals, y_vals

    @beat("Introduce the rod and the initial sine wave distribution.", seconds=3, 
          narration="Sadly, nature is not so nice, knocking us off onto an annoying but highly necessary detour. Here's the thing, even if nature were to somehow produce a temperature distribution on this rod, which looks like this perfect sine wave.")
    def init_rod(self):
        self.rod = Line([-3, 0, 0], [3, 0, 0], color=GRAY, stroke_width=20)
        x_vals, y_vals = self.get_sine_wave(t=0)
        self.curve = VMobject(color=YELLOW).set_points_smoothly([
            np.array([-3 + x*6, y*2, 0]) for x, y in zip(x_vals, y_vals)
        ])
        self.play(Create(self.rod), Create(self.curve))

    @beat("Show the exponential decay assumption.", seconds=3,
          narration="the exponential decay is not actually how it would evolve.")
    def show_decay(self):
        decay_label = MathTex(r"u(x,t) = \sin(\pi x)e^{-\pi^2 t}", font_size=36).to_edge(UP)
        self.play(Write(decay_label))
        self.play(self.curve.animate.set_opacity(0.3))

    @beat("Explain the boundary condition.", seconds=3,
          narration="Assuming that no heat flows in or out of the rod, here's what that evolution would actually look like.")
    def boundary_condition(self):
        bc = MathTex(r"\frac{\partial u}{\partial x} = 0 \text{ at } x=0, 1", font_size=36).next_to(self.rod, DOWN)
        self.play(Write(bc))

    @beat("Simulate the actual heat evolution.", seconds=4,
          narration="The points on the left are heated up a little at first, and those on the right are cooled down by their neighbors to the interior.")
    def simulate_evolution(self):
        # Evolution with Neumann boundary conditions leads to flattening
        # We animate the sine wave flattening towards a constant average
        self.curve.set_opacity(1)
        self.play(
            UpdateFromAlphaFunc(self.curve, lambda m, a: m.become(
                VMobject(color=YELLOW).set_points_smoothly([
                    np.array([-3 + x*6, (np.sin(np.pi * x) * np.exp(-10 * a)) * 2, 0]) 
                    for x in np.linspace(0, 1, 50)
                ])
            ), run_time=4, rate_func=linear)
        )

    @beat("Highlight the flattening effect.", seconds=3,
          narration="The temperature eventually equalizes across the entire rod.")
    def conclusion(self):
        final_line = Line([-3, 0, 0], [3, 0, 0], color=YELLOW, stroke_width=6)
        self.play(ReplacementTransform(self.curve, final_line))
        self.wait(1)

    @beat("Final summary of the detour.", seconds=3,
          narration="This shift from simple decay to boundary-constrained equilibrium is the detour nature forces upon us.")
    def summary(self):
        text = Text("Heat Equation Evolution", font_size=30).to_edge(RIGHT)
        self.play(Write(text))
        self.wait(2)
