from manim import *
from forge.beats import ForgeScene, beat

class HonorSystemProtocol(ForgeScene):
    @beat("Show a ledger with multiple transactions between Alice and Bob", seconds=4, narration="That way, if Alice pays Bob $100 multiple times, each one of those lines on the ledger requires a completely new signature.")
    def draw_ledger(self):
        ledger_background = Rectangle(width=6, height=4, color=WHITE, fill_opacity=0.1).shift(LEFT*2)
        self.play(Create(ledger_background), run_time=1.0)

        transactions = [
            "Alice pays Bob $100",
            "Bob pays Alice $50",
            "Alice pays Bob $100",
            "Bob pays Alice $50"
        ]

        self.ledger = VGroup()
        for i, transaction in enumerate(transactions):
            text = Text(transaction, font_size=24).next_to(ledger_background.get_top(), DOWN, buff=0.5 + i*0.5)
            self.ledger.add(text)
            self.play(Write(text), run_time=0.5)

    @beat("Show signatures for each transaction", seconds=3, narration="Alright, great. Digital signatures remove a huge aspect of trust in this initial protocol.")
    def add_signatures(self):
        self.signatures = VGroup()
        for i, transaction in enumerate(self.ledger):
