from manim import *
from forge.beats import ForgeScene, beat
from fractions import Fraction

class BayesFactorComparison(ForgeScene):

    @beat("Introduce standard probability formula", seconds=4, narration="Maybe it looks nicer if we use the words sensitivity and false positive rate, emphasizing the test accuracy.")
    def show_standard_formula(self):
        self.formula = MathTex(
            r"P(D|H) = \frac{P(H|D)P(D)}{P(H|D)P(D) + P(H|\neg D)P(\neg D)}"
        ).scale(0.8).shift(UP * 1)

        self.labels = VGroup(
            Text("Sensitivity: P(H|D)", font_size=24, color=BLUE).next_to(self.formula, DOWN, buff=1).shift(LEFT * 2),
            Text("False Positive Rate: P(H|~D)", font_size=24, color=RED).next_to(self.formula, DOWN, buff=1.8).shift(LEFT * 1.5)
        )
        self.play(Write(self.formula), Write(self.labels), run_time=3)

    @beat("Highlight the intermingling", seconds=3, narration="It helps emphasize which parts come from test accuracy, but in the usual formula, everything is intermingled.")
    def highlight_intermingling(self):
        box = SurroundingRectangle(self.formula, color=YELLOW, buff=0.2)
        self.play(Create(box), run_time=2)
        self.box = box

    @beat("Transition to Odds and Bayes Factor", seconds=4, narration="This emphasizes why I like framing with odds and a Bayes factor; it cleanly factors out the prior.")
    def show_odds_form(self):
        self.odds_formula = MathTex(
            r"\text{Posterior Odds} = \text{Bayes Factor} \times \text{Prior Odds}"
        ).scale(0.9).shift(DOWN * 1)

        self.play(FadeOut(self.formula), FadeOut(self.labels), FadeOut(self.box))
        self.play(Write(self.odds_formula), run_time=3)

    @beat("Deconstruct Bayes Factor", seconds=3, narration="It cleanly factors out the parts that have to do with the prior from the parts that have to do with test accuracy.")
    def show_components(self):
        bf_brace = Brace(self.odds_formula[0][14:26], DOWN)
        bf_text = bf_brace.get_text("Test Accuracy (Bayes Factor)").set_color(GREEN)

        prior_brace = Brace(self.odds_formula[0][27:], DOWN)
        prior_text = prior_brace.get_text("Prior").set_color(ORANGE)

        self.play(Create(bf_brace), Write(bf_text))
        self.play(Create(prior_brace), Write(prior_text))
        self.components = VGroup(bf_brace, bf_text, prior_brace, prior_text)

    @beat("Comparison layout", seconds=3, narration="Over in the usual formula, all of those are very intermingled together, unlike this clean factorization.")
    def compare_side_by_side(self):
        self.play(self.odds_formula.animate.scale(0.6).to_edge(LEFT, buff=1),
                  self.components.animate.scale(0.6).next_to(self.odds_formula, DOWN))

        old_formula = MathTex(r"P(H|D) = \frac{P(D|H)P(H)}{P(D)}").scale(0.7).to_edge(RIGHT, buff=1)
        label = Text("Intermingled formula", font_size=24).next_to(old_formula, UP)
        self.play(Write(old_formula), Write(label))
        self.final_group = VGroup(old_formula, label)

    @beat("Final summary", seconds=3, narration="By separating the prior from the likelihood, we gain a much clearer view of how the test updates our beliefs.")
    def conclusion(self):
        self.play(Indicate(self.odds_formula), Indicate(self.final_group))
        self.wait(1)
