from manim import *
from forge.beats import ForgeScene, beat
import numpy as np

class PhaseTransitionVisualization(ForgeScene):
    def setup(self):
        self.grid_size = 20
        self.spacing = 6.0 / self.grid_size
        self.dots = VGroup()
        for x in range(self.grid_size):
            for y in range(self.grid_size):
                dot = Dot(radius=0.1)
                dot.move_to(np.array([-5 + x * self.spacing, -3 + y * self.spacing, 0]))
                self.dots.add(dot)
        self.add(self.dots)

    @beat("Initialize gas state", seconds=3, narration="But at low temperatures, once we cross a certain threshold, a phase transition begins to happen.")
    def init_gas(self):
        for dot in self.dots:
            dot.set_color(WHITE).set_opacity(0.1)
        self.play(FadeIn(self.dots), run_time=2)

    @beat("Transition to liquid", seconds=4, narration="And the density goes from very low, like a gas, to very high, like a liquid, skipping all the intermediate values.")
    def transition_liquid(self):
        self.play(
            self.dots.animate.set_color(BLUE).set_opacity(0.9),
            run_time=3
        )

    @beat("Show gradual change", seconds=3, narration="Due to the nature of the simulation, the number of molecules on the screen still has to change gradually.")
    def gradual_change(self):
        self.play(
            *[dot.animate.set_opacity(0.5) for dot in self.dots],
            run_time=2
        )

    @beat("Phase separation", seconds=4, narration="But during the phase transition, every region of the picture is either mostly blue or mostly white.")
    def phase_separation(self):
        animations = []
        for dot in self.dots:
            if dot.get_center()[0] < 0:
                animations.append(dot.animate.set_color(BLUE).set_opacity(0.9))
            else:
                animations.append(dot.animate.set_color(WHITE).set_opacity(0.1))
        self.play(*animations, run_time=3)

    @beat("Highlight boundary", seconds=3, narration="And there are no regions with intermediate density where the blue and white regions meet.")
    def boundary(self):
        line = Line(start=[0, -3.5, 0], end=[0, 3.5, 0], color=YELLOW)
        label = Text("Sharp Boundary", font_size=32, color=YELLOW).next_to(line, RIGHT)
        self.play(Create(line), Write(label), run_time=2)

    @beat("Final state", seconds=2, narration="It is a distinct separation of phases.")
    def final_view(self):
        self.play(FadeOut(self.dots), run_time=1.5)
