from manim import *
from forge.beats import ForgeScene, beat

class GroupAxiomIntroduction(ForgeScene):
    @beat("Introduce groups as symmetries", seconds=4, narration="All of this is true of groups as well, which are best understood as abstractions above the idea of symmetry actions.")
    def symmetry_intro(self):
        shape = RegularPolygon(n=3, color=BLUE).scale(1.5)
        self.label = Text("Symmetry Group", font_size=36).to_edge(UP)
        self.play(Create(shape), Write(self.label))
        rotations = VGroup(*[
            Arrow(start=ORIGIN, end=UP*1.2, color=YELLOW).rotate(i * 120 * DEGREES, about_point=ORIGIN)
            for i in range(3)
        ])
        self.play(FadeIn(rotations))
        self.shape = shape
        self.rotations = rotations

    @beat("Emphasize importance of understanding groups", seconds=4, narration="I'm emphasizing this for two reasons. One is that understanding what groups really are gives a better appreciation for the monster, and the other is that many students learning about groups for the first time can find them frustratingly opaque.")
    def motivation(self):
        self.play(FadeOut(self.shape, self.rotations), FadeOut(self.label))
        self.text = Text("Group Theory", font_size=60).move_to(LEFT * 2)
        self.play(Write(self.text))

    @beat("Acknowledge the difficulty of definitions", seconds=3, narration="I know that I did. A typical course starts with this very formal and abstract definition...")
    def frustration(self):
        thought = Text("?", color=RED, font_size=72).next_to(self.text, RIGHT, buff=1)
        self.play(FadeIn(thought, scale=0.5))
        self.wait(1)
        self.play(FadeOut(thought))

    @beat("Define the set G", seconds=3, narration="...which is that a group is a set in a collection of things...")
    def define_set(self):
        self.group_box = SurroundingRectangle(Text("Set G").move_to(RIGHT*2), buff=0.5)
        self.elements = VGroup(*[Dot(RIGHT*2 + np.array([np.cos(i), np.sin(i), 0])*0.5) for i in range(5)])
        self.play(Create(self.group_box), FadeIn(self.elements))

