import numpy as np

class KochDimension(ForgeScene):
    @beat("Introduce the scaling equation", seconds=3, narration="So that means the dimension should be some number D, so that when we raise one third to the power of D, it gives us one fourth.")
    def scaling_equation(self):
        eq = MathTex(r"(1/3)^D = 1/4", font_size=60)
        self.play(Write(eq))
        self.eq = eq

    @beat("Rearrange the equation", seconds=3, narration="Well, that's the same as saying three to the what equals four,")
    def rearrange(self):
        new_eq = MathTex(r"3^D = 4", font_size=60)
        self.play(Transform(self.eq, new_eq))

    @beat("Introduce the logarithm", seconds=3, narration="so you can go and plug into a calculator log base three of four,")
    def log_representation(self):
        log_eq = MathTex(r"D = \log_{3}(4)", font_size=60)
        self.play(Transform(self.eq, log_eq))

    @beat("Calculate the value", seconds=3, narration="and that comes out to be around 1.262.")
    def calculate(self):
        val = np.log(4) / np.log(3)
        result = MathTex(f"D \\approx {val:.3f}", font_size=60, color=YELLOW)
        self.play(Transform(self.eq, result))

    @beat("Visualize the Koch curve segment", seconds=4, narration="So in a sense, the von Koch curve is a 1.262 dimensional shape.")
    def visualize(self):
        # Create a stylized Koch segment
        path = VGroup()
        points = [LEFT*3, LEFT*1 + UP*0.5, ORIGIN, RIGHT*1 + DOWN*0.5, RIGHT*3]
        for i in range(len(points)-1):
            path.add(Line(points[i], points[i+1]))

        path.set_stroke(BLUE, width=4)
        path.shift(DOWN*2)

        self.play(FadeIn(path))
        self.play(self.eq.animate.to_edge(UP))
        self.wait(2)
