from manim import *
from forge.beats import ForgeScene, beat
import numpy as np

class AreaSquishing(ForgeScene):
    def get_graph(self, s=1):
        # f(x) = s * exp(-s * x) for x >= 0
        return FunctionGraph(lambda x: s * np.exp(-s * x), x_range=[0, 6], color=BLUE)

    @beat("Show the unit square and the graph with s=1", seconds=4, narration="And you can interpret that as telling you that the area under this graph is 1, which is kind of fun.")
    def show_unit_square(self):
        self.axes = Axes(x_range=[0, 6, 1], y_range=[0, 2, 1], axis_config={"include_tip": False})
        self.square = Square(side_length=2, fill_opacity=0.2, fill_color=YELLOW).align_to(self.axes.c2p(0, 0), DOWN + LEFT)
        self.graph = self.get_graph(s=1)
        self.area = self.axes.get_area(self.graph, x_range=[0, 6], color=BLUE, opacity=0.3)
        self.play(Create(self.axes), Create(self.square), Create(self.graph), FadeIn(self.area))

    @beat("Highlight the tail area filling the square", seconds=4, narration="I guess that means that all the area under this infinite tail is exactly enough to fill in the rest of this unit square.")
    def highlight_tail(self):
        # The integral of e^-x from 0 to infinity is 1.
        # We show the area filling the remaining part of the 1x1 square.
        self.play(self.area.animate.set_color(YELLOW), run_time=2)
        self.play(Indicate(self.square), run_time=2)

    @beat("Introduce s parameter", seconds=3, narration="And then if we reintroduce that value s and set it equal to something that's not 1...")
    def introduce_s(self):
        self.s_val = ValueTracker(1.0)
        label = MathTex("s = ").to_edge(UP)
        value = DecimalNumber(1.0).next_to(label, RIGHT).add_updater(lambda d: d.set_value(self.s_val.get_value()))
        self.add(label, value)
        self.play(Write(label), Write(value))

    @beat("Squish the graph by increasing s", seconds=4, narration="...the effect is to squish the graph in the horizontal direction.")
    def squish_graph(self):
        new_graph = always_redraw(lambda: self.get_graph(s=self.s_val.get_value()))
        new_area = always_redraw(lambda: self.axes.get_area(new_graph, x_range=[0, 6], color=BLUE, opacity=0.3))
        self.play(
            ReplacementTransform(self.graph, new_graph),
            ReplacementTransform(self.area, new_area),
            self.s_val.animate.set_value(2.0),
            run_time=3
        )

    @beat("Explain the general rule", seconds=4, narration="That's always the effect if you multiply the input of a function by some constant.")
    def explain_rule(self):
        rule = MathTex("f(x) \\to f(s \\cdot x)").to_edge(RIGHT)
        self.play(Write(rule))
        self.play(Indicate(rule))

    @beat("Final look", seconds=3, narration="It's a beautiful geometric intuition for how function arguments transform the domain.")
    def conclude(self):
        self.play(FadeOut(self.square), self.graph.animate.set_stroke(opacity=0.5))
        self.wait(2)
