    @beat("Name the rule", seconds=3, narration="This is something known as Laplace's rule of succession, it dates back to the 18th century.")
    def name_rule(self):
        self.title = Text("Laplace's Rule of Succession", color=BLUE).to_edge(UP)
        year = Text("18th Century", font_size=30).next_to(self.title, DOWN)
        self.play(Write(self.title), FadeIn(year))

    @beat("Show the formula", seconds=3, narration="To understand what assumptions are underlying this, and how changing either those assumptions...")
    def formula(self):
        formula = MathTex(r"P = \frac{s+1}{n+2}").scale(1.5).shift(DOWN * 0.5)
        self.play(
            FadeOut(self.group2), 
            FadeOut(self.group3), 
            FadeOut(self.cross),
            FadeIn(formula)
        )
        self.formula = formula

    @beat("Closing thoughts", seconds=3, narration="...or your underlying goal can change the choice you make, we really do need to go through all the math.")
    def closing(self):
        note = Text("We need to go through the math.", font_size=30).shift(DOWN * 2.5)
        self.play(Write(note))
        self.wait(1)
