from forge.beats import ForgeScene, beat

class EigenvalueDerivation(ForgeScene):

    @beat("As a quick reminder, if the effect of a linear transformation on a given vector is to scale that vector by some constant, we call it an eigenvector of the transformation...", seconds=4, narration="As a quick reminder, if the effect of a linear transformation on a given vector is to scale that vector by some constant, we call it an eigenvector of the transformation...")
    def show_eigenvector_definition(self):
        self.plane = NumberPlane(
            x_range=[-4, 4], y_range=[-3, 3],
            background_line_style={"stroke_opacity": 0.3}
        ).scale(0.6).shift(LEFT * 3.5)

