        self.label_v = MathTex(r"\mathbf{v}", color=YELLOW).next_to(self.vector_v.get_end(), UP)

        # Transformed vector scaled by 2
        self.scaled_v = Vector([4, 2], color=BLUE).shift(LEFT * 3.5)
        self.label_av = MathTex(r"A\mathbf{v} = \lambda\mathbf{v}", color=BLUE).to_edge(UP).shift(LEFT * 2)

        self.play(FadeIn(self.plane), GrowArrow(self.vector_v), Write(self.label_v), run_time=2)
        self.play(Transform(self.vector_v, self.scaled_v), Write(self.label_av), run_time=2)

    @beat("...and we call the relevant scaling factor the corresponding eigenvalue, often denoted with the letter lambda.", seconds=3, narration="...and we call the relevant scaling factor the corresponding eigenvalue, often denoted with the letter lambda.")
    def show_lambda(self):
        self.lambda_text = MathTex(r"\lambda = 2", color=BLUE).next_to(self.label_av, DOWN)
        self.play(Write(self.lambda_text), run_time=2)
        self.wait(1)

    @beat("When you write this as an equation, and you rearrange a little bit...", seconds=3, narration="When you write this as an equation, and you rearrange a little bit...")
    def write_equation(self):
        self.eq1 = MathTex(r"A\mathbf{v} = \lambda \mathbf{v}").to_edge(RIGHT).shift(UP * 1.5)
        self.eq2 = MathTex(r"A\mathbf{v} - \lambda I\mathbf{v} = 0").next_to(self.eq1, DOWN, buff=0.5)

        self.play(Write(self.eq1), run_time=1.5)
        self.play(TransformMatchingTex(self.eq1.copy(), self.eq2), run_time=1.5)

    @beat("...what you see is that if the number lambda is an eigenvalue of a matrix A, then the matrix A minus lambda times the identity...", seconds=4, narration="...what you see is that if the number lambda is an eigenvalue of a matrix A, then the matrix A minus lambda times the identity...")
    def factor_out_vector(self):
        self.eq3 = MathTex(r"(A - \lambda I)\mathbf{v} = 0").next_to(self.eq2, DOWN, buff=0.5)
        self.box = SurroundingRectangle(self.eq3[0][:7], color=YELLOW)

        self.play(TransformMatchingTex(self.eq2.copy(), self.eq3), run_time=2)
        self.play(Create(self.box), run_time=2)

    @beat("...must send some non-zero vector, namely the corresponding eigenvector, to the zero vector...", seconds=4, narration="...must send some non-zero vector, namely the corresponding eigenvector, to the zero vector...")
    def non_zero_nullspace(self):
