        self.play(Write(self.text_non_zero), run_time=2)
        self.wait(2)

    @beat("...which in turn means that the determinant of this modified matrix must be zero.", seconds=4, narration="...which in turn means that the determinant of this modified matrix must be zero.")
    def determinant_zero(self):
