from manim import *
from forge.beats import ForgeScene, beat

class TowerOfHanoiIntro(ForgeScene):
    num_disks = 4

    def get_disk(self, size, spindle_idx, position_in_stack):
        width = 0.5 + size * 0.4
        # Use valid Manim color TEAL_D
        disk = Rectangle(width=width, height=0.3, fill_opacity=1, 
                         color=interpolate_color(BLUE, TEAL_D, size / (self.num_disks - 1)))
        x_pos = (spindle_idx) * 3.5
        y_pos = -2.5 + position_in_stack * 0.35
        return disk.move_to([x_pos, y_pos, 0])

    @beat("Set up the initial Hanoi configuration", seconds=4, narration="So they all start up stacked up from biggest to smallest on one spindle, and the goal is to move the entire tower from one spindle to another.")
    def setup_tower(self):
        self.spindles = VGroup(*[Line(DOWN*1.5, UP*1.5).shift(i*3.5*RIGHT) for i in [-1, 0, 1]])
        self.disks = VGroup(*[self.get_disk(i, -1, self.num_disks - 1 - i) for i in range(self.num_disks)])
        self.play(Create(self.spindles), LaggedStart(*[FadeIn(d) for d in self.disks]))

    @beat("Highlight the rules", seconds=3, narration="The rule is you can only move one disk at a time, and you can't move a bigger disk on top of a smaller disk.")
    def show_rules(self):
        rule_text = Text("1 disk at a time", font_size=30, color=YELLOW).to_edge(UP)
        rule_text2 = Text("No larger on smaller", font_size=30, color=RED).next_to(rule_text, DOWN)
        self.play(Write(rule_text), Write(rule_text2))
        self.wait(2)
        self.play(FadeOut(rule_text), FadeOut(rule_text2))

    @beat("Focus on the top disk", seconds=3, narration="For example, your first move must involve moving disk 0, since any other disk has stuff on top of it.")
    def highlight_top(self):
        self.top_disk = self.disks[-1]
        self.play(Indicate(self.top_disk, color=YELLOW, scale_factor=1.2))

    @beat("Show the blockage", seconds=3, narration="...that needs to get out of the way before it can move.")
    def show_blockage(self):
        arrows = VGroup(*[Arrow(start=self.disks[i].get_top(), end=self.disks[i-1].get_bottom(), 
                                color=RED, buff=0.1) for i in range(self.num_disks - 1, 0, -1)])
        self.play(Create(arrows))
        self.wait(1)
        self.play(FadeOut(arrows))

    @beat("Execute first move", seconds=3, narration="Therefore, the only valid move is to shift the smallest disk to an empty spindle.")
    def first_move(self):
        target_pos = self.spindles[1].get_bottom() + UP * 0.175
        self.play(self.top_disk.animate.move_to(target_pos))

    @beat("Conclusion of intro", seconds=2, narration="This sequence of necessity defines the recursive nature of the puzzle.")
    def conclude(self):
        self.play(FadeOut(self.disks), FadeOut(self.spindles))
