class SphereTetrahedronProbability(ForgeScene, ThreeDScene):
    @beat("Initialize the 3D scene with a sphere", seconds=3, narration="So anyway, here's the question. If you choose four random points on a sphere, and consider the tetrahedron with these points as its vertices, what is the probability that the center of the sphere is inside that tetrahedron?")
    def setup_sphere(self):
        self.set_camera_orientation(phi=75 * DEGREES, theta=-45 * DEGREES)
        self.sphere = Sphere(radius=2, fill_opacity=0.1, color=BLUE)
        self.center = Dot(color=YELLOW)
        self.play(Create(self.sphere), FadeIn(self.center))

    @beat("Place four random points on the sphere", seconds=3, narration="Go ahead, take a moment and kind of digest this question.")
    def add_points(self):
        # Use fixed points to ensure visual consistency while appearing random
        angles = [0.5, 2.1, 3.8, 5.5]
        points = [np.array([2 * np.cos(a), 2 * np.sin(a), (i%2)*1.5 - 0.75]) for i, a in enumerate(angles)]
        self.dots = VGroup(*[Dot(p, color=WHITE) for p in points])
        self.play(LaggedStart(*[FadeIn(p) for p in self.dots], lag_ratio=0.5))

    @beat("Form the tetrahedron from the points", seconds=3, narration="You might start thinking about which of these tetrahedra contain the sphere's center...")
    def draw_tetrahedron(self):
        edges = VGroup()
        pts = [d.get_center() for d in self.dots]
        for i in range(4):
            for j in range(i + 1, 4):
                edges.add(Line(pts[i], pts[j], color=GRAY))
        self.play(Create(edges))

    @beat("Highlight the center", seconds=3, narration="...which ones don't...")
    def highlight_center(self):
        self.play(Indicate(self.center))

    @beat("Show a silhouette/cross-section view", seconds=3, narration="...how you might systematically distinguish the two...")
    def cross_section_view(self):
        self.move_camera(theta=45 * DEGREES, run_time=2)

    @beat("Pose the challenge", seconds=3, narration="...and how do you approach a problem like this?")
    def final_thought(self):
        # 1/2^(4-1) = 1/8
        prob = 1 / 8
        text = Text(f"Probability = 1/8", font_size=36).to_edge(UP)
        self.add_fixed_in_frame_mobjects(text)
        self.play(Write(text))
        self.wait(2)
