import numpy as np

class LogarithmicEscherTransformation(ForgeScene):
    def get_grid(self, color=BLUE):
        return VGroup(*[
            Line(start=[-4, y, 0], end=[4, y, 0], color=color, stroke_opacity=0.3)
            for y in np.linspace(-4, 4, 9)
        ], *[
            Line(start=[x, -4, 0], end=[x, 4, 0], color=color, stroke_opacity=0.3)
            for x in np.linspace(-4, 4, 9)
        ])

    @beat("Initialize the complex plane view", seconds=3, narration="Step two, take a logarithm of this, which in this case gives us a similarly bizarre transformation of the whole scene.")
    def setup_plane(self):
        self.grid = self.get_grid()
        self.plane_label = Text("Complex Plane", font_size=24).to_edge(UP)
        self.play(Create(self.grid), Write(self.plane_label))

    @beat("Apply log transformation", seconds=3, narration="But there is a little difference this time.")
    def log_transform(self):
        def log_func(pos):
            x, y, z = pos
            r = np.sqrt(x**2 + y**2)
            theta = np.arctan2(y, x)
            return np.array([np.log(r + 0.1), theta, 0])

        self.play(self.grid.animate.apply_function(log_func), run_time=2)

    @beat("Highlight zoom factor", seconds=3, narration="Because Escher was working with a much deeper zoom, with a scale factor of 256, the repeating tiles in this new example actually span a wider part of the complex plane.")
