from manim import *
from forge.beats import ForgeScene, beat

class GaussianPrimeImbalance(ForgeScene):
    @beat("Introduce Gaussian primes and their conjugate pairs", seconds=3,
          narration="We're dealing with Gaussian primes, which are complex numbers that look like a plus bi, where a and b are integers.")
    def introduce_gaussian_primes(self):
        primes = [1, 2, 3, 5]
        self.gaussian_primes = VGroup(*[
            MathTex(f"{a}+{b}i", font_size=36).move_to([-3 + i % 2 * 3, 1.5 - i // 2 * 1.5, 0])
            for i, (a, b) in enumerate(zip(primes, primes))
        ])
        self.conjugates = VGroup(*[
            MathTex(f"{a}-{b}i", font_size=36).move_to([-3 + i % 2 * 3, 0.5 - i // 2 * 1.5, 0])
            for i, (a, b) in enumerate(zip(primes, primes))
        ])
        self.play(LaggedStart(*[Write(gp) for gp in self.gaussian_primes], lag_ratio=0.1, run_time=1.5))
        self.play(LaggedStart(*[Write(c) for c in self.conjugates], lag_ratio=0.1, run_time=1.5))

    @beat("Show the problem with the prime number 3", seconds=3,
          narration="But what if you introduce a factor like 3, which doesn't break down as the product of two conjugate Gaussian primes?")
    def show_problem(self):
        self.problem_prime = MathTex("3", font_size=48, color=RED).move_to([0, 0, 0])
        self.play(Write(self.problem_prime), run_time=1.0)

    @beat("Create two columns to represent the system", seconds=2,
          narration="Well that really mucks up the whole system. When you're divvying up the primes between the two columns, there's no way that you can split up this 3.")
    def create_columns(self):
        self.columns = VGroup(
            Rectangle(height=3, width=1, color=BLUE).move_to([-2, 0, 0]),
            Rectangle(height=3, width=1, color=GREEN).move_to([2, 0, 0])
        )
        self.play(Create(self.columns), run_time=1.0)

    @beat("Attempt to balance the columns with the problem prime", seconds=3,
          narration="No matter where you put it, it leaves the columns imbalanced.")
    def attempt_balance(self):
        self.play(
            Transform(self.problem_prime.copy(), self.problem_prime.copy().move_to([-2, 0, 0])),
            Transform(self.problem_prime.copy(), self.problem_prime.copy().move_to([2, 0, 0])),
            run_time=1.5
        )
        self.play(
            FadeOut(self.problem_prime.copy()),
            FadeOut(self.problem_prime.copy()),
            run_time=0.5
        )

    @beat("Show the consequence of the imbalance", seconds=3,
          narration="And what that means is that when you take the product of all of the numbers in each column, you're not going to end up with a conjugate pair.")
    def show_consequence(self):
        products = VGroup(
            MathTex("1+i \\times 2+i", font_size=36, color=BLUE).move_to([-2, -1.5, 0]),
            MathTex("1-i \\times 2-i", font_size=36, color=GREEN).move_to([2, -1.5, 0])
        )
        self.play(Write(products), run_time=1.5)
        self.wait(0.5)
