from manim import *
from forge.beats import ForgeScene, beat

class TilePuzzleAbstraction(ForgeScene):
    @beat("Introduce a single tile and its 4 X constraints", seconds=4, narration="If any tile ever touches fewer than that, it kind of feels like a waste of its potential. So with that in mind, we can abstract away from the grid for a second.")
    def setup_tile(self):
        self.tile = Square(side_length=2, color=BLUE, fill_opacity=0.3)
        self.xs = VGroup(*[
            Tex("X").move_to(self.tile.get_edge_center(d)) 
            for d in [UP, DOWN, LEFT, RIGHT]
        ])
        self.group = VGroup(self.tile, self.xs)
        self.play(Create(self.tile), Write(self.xs), run_time=2.5)
        self.wait(1.5)

    @beat("Show tiles floating freely", seconds=4, narration="And just imagine these tiles freely floating, each one touching 4 X's somewhere around its boundary.")
    def floating_tiles(self):
        self.tiles = VGroup(*[
            VGroup(Square(side_length=1.5, color=BLUE, fill_opacity=0.3),
                   *[Tex("X", font_size=30).move_to(p) for p in [UP*0.75, DOWN*0.75, LEFT*0.75, RIGHT*0.75]])
            for _ in range(3)
        ]).arrange(RIGHT, buff=1.5).shift(UP*0.5)
        self.play(Transform(self.group, self.tiles), run_time=3)

    @beat("Transition to the puzzle concept", seconds=4, narration="The goal will be to somehow fit all of these together kind of like a puzzle.")
    def puzzle_concept(self):
        self.play(self.group.animate.arrange(buff=-0.2).move_to(ORIGIN), run_time=3)

    @beat("Focus on one tile and its right-side X", seconds=4, narration="To understand the constraints here, I want you to focus on just one of them.")
    def focus_tile(self):
        target = self.group[1]
        self.play(
            FadeOut(self.group[0], self.group[2]),
            target.animate.scale(1.5).move_to(LEFT*2),
            run_time=3
        )
        self.right_x = target[4] # The X on the right side
        self.play(Indicate(self.right_x), run_time=1)

    @beat("Add tiles above and below the right X", seconds=4, narration="And imagine fitting two other tiles above and below the X that it has on its right side.")
    def add_neighbors(self):
        n1 = Square(side_length=1.5, color=RED, fill_opacity=0.3).next_to(self.right_x, UP, buff=0.1)
        n2 = Square(side_length=1.5, color=RED, fill_opacity=0.3).next_to(self.right_x, DOWN, buff=0.1)
        self.play(FadeIn(n1), FadeIn(n2), run_time=3)

    @beat("Final arrangement", seconds=4, narration="This creates a chain of constraints that dictates how the entire structure must interlock.")
    def final_view(self):
        brace = Brace(VGroup(self.right_x, VGroup(self.group[1][0], self.group[1][1])), RIGHT)
        label = brace.get_text("Constraint Point")
        self.play(Create(brace), Write(label), run_time=3)
