from manim import *
from forge.beats import ForgeScene, beat
import numpy as np

class PrimeSpiralAnalysis(ForgeScene):
    def get_pos(self, n):
        # Ulam spiral-like mapping: angle increases by fixed amount (golden angle)
        angle = n * 2.39996
        radius = 0.15 * np.sqrt(n)
        return np.array([radius * np.cos(angle), radius * np.sin(angle), 0])

    @beat("Initialize the spiral points", seconds=3, narration="Six more steps, smaller still, and so on, with this angle changing gently enough that it gives the illusion of a single curving line.")
    def draw_spiral(self):
        self.dots = VGroup(*[Dot(point=self.get_pos(i), radius=0.04) for i in range(1, 101)])
        self.play(Create(self.dots, run_time=2.5))

    @beat("Filter for prime numbers", seconds=3, narration="When you limit the view to prime numbers, all but two of these spiral arms will go away.")
    def filter_primes(self):
        primes = [i for i in range(1, 101) if i > 1 and all(i % j != 0 for j in range(2, int(i**0.5) + 1))]
        self.prime_dots = VGroup(*[self.dots[i-1] for i in primes])
        self.play(FadeOut(VGroup(*[d for d in self.dots if d not in self.prime_dots])), 
                  self.prime_dots.animate.set_color(YELLOW), run_time=2)

    @beat("Show multiples of 6", seconds=3, narration="And think about it, a prime number can't be a multiple of 6...")
    def show_six(self):
        multiples = [i for i in range(6, 101, 6)]
        self.six_dots = VGroup(*[Dot(point=self.get_pos(i), color=RED).scale(1.5) for i in multiples])
        self.play(FadeIn(self.six_dots), run_time=2)

    @beat("Show 2 above multiples of 6", seconds=3, narration="...and it also can't be 2 above a multiple of 6 unless it's 2...")
    def show_two_above(self):
        two_above = [i for i in range(8, 101, 6)]
        self.two_dots = VGroup(*[Dot(point=self.get_pos(i), color=BLUE).scale(1.5) for i in two_above if i != 2])
        self.play(FadeIn(self.two_dots), run_time=2)

    @beat("Show 4 above multiples of 6", seconds=3, narration="...or 4 above a multiple of 6, since all of those are even numbers.")
    def show_four_above(self):
        four_above = [i for i in range(10, 101, 6)]
        self.four_dots = VGroup(*[Dot(point=self.get_pos(i), color=GREEN).scale(1.5) for i in four_above])
        self.play(FadeIn(self.four_dots), run_time=2)

    @beat("Conclusion summary", seconds=3, narration="Because these patterns cover all even numbers, primes are restricted to the remaining gaps.")
    def conclude(self):
        label = Text("Primes avoid 6n, 6n+2, 6n+4", font_size=32).to_edge(UP)
        self.play(Write(label), self.prime_dots.animate.set_color(WHITE), run_time=2)
        self.wait(1)
