import numpy as np

class WaveInteraction(ForgeScene):
    @beat("Introduce the sine wave", seconds=3, narration="That tends to be a little bit busier, so usually we just draw the sine wave.")
    def draw_sine_wave(self):
        self.axes = Axes(x_range=[-6, 6], y_range=[-2, 2], axis_config={"include_ticks": False})
        self.wave = self.axes.plot(lambda x: 1.2 * np.sin(2 * x), color=BLUE, stroke_width=6)
        self.label = MathTex(r"E(x, t) = A \sin(kx - \omega t)").to_edge(UP)
        self.play(Create(self.wave), Write(self.label))

    @beat("Transition to material interaction", seconds=3, narration="So thinking back to the question of why interactions with a layer of material would cause a kickback to the phase of the wave, let's start thinking it through.")
    def show_material(self):
        self.glass = Rectangle(width=4, height=8, fill_opacity=0.3, fill_color=GREY, stroke_color=WHITE).shift(RIGHT * 2)
        self.question = Text("Phase Kickback?", font_size=36, color=YELLOW).next_to(self.glass, UP)
        self.play(FadeIn(self.glass), Write(self.question))

    @beat("Light entering the material", seconds=3, narration="When a light beam enters a material, like glass, then it causes all of the charges inside that material...")
    def light_enters(self):
        self.beam = Line(LEFT * 6, RIGHT * 2, color=BLUE, stroke_width=8)
        self.play(Create(self.beam))

    @beat("Add charges inside the material", seconds=3, narration="...you know, electrons or maybe the occasional ion...")
    def draw_charges(self):
        self.charges = VGroup(*[Dot(point=[2 + np.random.uniform(-1.5, 1.5), np.random.uniform(-2, 2), 0]) for _ in range(12)])
        self.play(FadeIn(self.charges))

    @beat("Animate the wiggling charges", seconds=4, narration="...to wiggle up and down in response to that light wave.")
    def wiggle_charges(self):
        self.wiggle = AnimationGroup(*[
            c.animate.shift(UP * 0.3).shift(DOWN * 0.3) for c in self.charges
        ], lag_ratio=0.1)
        self.play(self.wiggle, run_time=3)

    @beat("Final state showing oscillation", seconds=3, narration="The charges oscillate in sync with the driving electric field.")
    def finalize(self):
        # Indicate oscillation with small arrows
        arrows = VGroup(*[DoubleArrow(c.get_center(), c.get_center() + UP * 0.4, buff=0, tip_length=0.1) for c in self.charges])
        self.play(FadeIn(arrows))
        self.play(Indicate(self.wave, color=BLUE), run_time=2)
