from manim import *
from forge.beats import ForgeScene, beat

class GeneratingFunctionTheory(ForgeScene):
    @beat("Introduce the generating function form", seconds=3, narration="So the art of analyzing a generating function here will be to deduce facts about these coefficients without actually expanding the expression.")
    def show_abstract_form(self):
        self.func = MathTex("f(x) = \\sum_{n=0}^{N} c_n x^n", font_size=60)
        self.func.to_edge(LEFT, buff=1)
        self.play(Write(self.func))
        self.wait(1)

    @beat("Highlight the coefficients", seconds=3, narration="So moving forward, I'm just going to write this expansion more abstractly...")
    def highlight_coeffs(self):
        self.c_n = self.func[0][8:10]
        self.box = SurroundingRectangle(self.c_n, color=YELLOW)
        self.play(Create(self.box))
        self.wait(1)

    @beat("Explain the summation range", seconds=3, narration="...just a sum from n equals 0 up to capital N...")
    def explain_sum(self):
        sum_part = self.func[0][2:7]
        self.sum_box = SurroundingRectangle(sum_part, color=BLUE)
        self.play(ReplacementTransform(self.box, self.sum_box))
        self.wait(1)

    @beat("Define the coefficients", seconds=3, narration="...where c sub n tells us the coefficients that we don't know.")
    def define_cn(self):
        self.desc = Text("c_n : The unknown coefficients", font_size=32, color=YELLOW).next_to(self.func, RIGHT, buff=1)
        self.play(FadeIn(self.desc, shift=RIGHT))
        self.play(Indicate(self.c_n))
        self.wait(1)

    @beat("Show the expanded view", seconds=4, narration="Instead of expanding the whole polynomial, we focus on the structure of these values.")
    def show_expansion(self):
        self.expansion = MathTex("f(x) = c_0 + c_1 x + c_2 x^2 + \\dots + c_N x^N", font_size=48)
        self.expansion.next_to(self.func, DOWN, buff=1.5)
        self.play(FadeIn(self.expansion, shift=UP))
        self.wait(2)

    @beat("Final conclusion on analysis", seconds=3, narration="Our goal is to extract properties of c_n directly from the functional form f(x).")
    def conclusion(self):
        arrow = Arrow(start=self.func.get_right(), end=self.expansion.get_top(), color=RED)
        label = Text("Analyze directly", font_size=24, color=RED).next_to(arrow, RIGHT)
        self.play(Create(arrow), Write(label))
        self.play(FadeOut(self.sum_box))
        self.wait(1)
