from manim import *
from forge.beats import ForgeScene, beat
from fractions import Fraction

class JewelFairDivision(ForgeScene):
    # Jewel counts: 4 sapphires, 5 emeralds, 2 diamonds, 3 rubies
    # Total = 14 jewels
    jewels = ["Sapphire"] * 4 + ["Emerald"] * 5 + ["Diamond"] * 2 + ["Ruby"] * 3

    def get_jewel_color(self, type):
        colors = {"Sapphire": BLUE, "Emerald": GREEN, "Diamond": WHITE, "Ruby": RED}
        return colors[type]

    @beat("Introduce the arrangement of jewels", seconds=3, narration="For example, for the arrangement I'm showing here, I just did it with 4 cuts.")
    def show_line(self):
        self.row = VGroup(*[Circle(radius=0.25, fill_opacity=0.8, fill_color=self.get_jewel_color(j)) 
                           for j in self.jewels]).arrange(RIGHT, buff=0.1).shift(LEFT*1.5)
        self.cuts = VGroup(*[DashedLine(start=UP*0.5, end=DOWN*0.5).move_to(self.row[i].get_right()+UP*0.1) 
                            for i in [2, 5, 8, 11]])
        self.play(Create(self.row), Create(self.cuts), run_time=2.5)

    @beat("Split the strands", seconds=3, narration="If I give the top 3 strands to you, and these bottom 2 strands to your co-conspirator...")
    def split_strands(self):
        self.top = VGroup(*self.row[:7]).copy().shift(UP*1.5)
        self.bottom = VGroup(*self.row[7:]).copy().shift(DOWN*1.5)
        self.play(FadeOut(self.row), FadeIn(self.top), FadeIn(self.bottom), run_time=2.5)

    @beat("Show the counts", seconds=4, narration="...each of you ends up with 4 sapphires, 5 emeralds, 2 diamonds, and 3 rubies.")
    def show_inventory(self):
        counts = {"Sapphire": 4, "Emerald": 5, "Diamond": 2, "Ruby": 3}
        labels = VGroup()
        for i, (name, count) in enumerate(counts.items()):
            label = Text(f"{count} {name}", color=self.get_jewel_color(name), font_size=24)
            labels.add(label)
        labels.arrange(DOWN, aligned_edge=LEFT).next_to(ORIGIN, RIGHT, buff=2)
        self.play(Write(labels), run_time=3)
        self.labels = labels

    @beat("State the theorem", seconds=3, narration="The claim, the thing I want to prove in this video, is that if there are N different jewel types...")
    def state_theorem(self):
        n_types = len(set(self.jewels))
        text = Text(f"N = {n_types} jewel types", font_size=36).to_edge(UP)
        self.play(FadeOut(self.top, self.bottom, self.labels), Write(text), run_time=2)
        self.n_text = text

    @beat("Explain the N cut bound", seconds=3, narration="...it's always possible to do this fair division with only N cuts, or fewer.")
    def show_bound(self):
        n_types = len(set(self.jewels))
        bound = Text(f"Requires ≤ {n_types} cuts", color=YELLOW, font_size=40).next_to(self.n_text, DOWN, buff=1)
        rect = SurroundingRectangle(bound, color=YELLOW)
        self.play(Write(bound), Create(rect), run_time=2.5)

    @beat("Final summary", seconds=2, narration="This is the core of the fair division theorem.")
    def conclude(self):
        self.play(Indicate(self.n_text), Indicate(self.n_text), run_time=2)
