from manim import *
from forge.beats import ForgeScene, beat
from fractions import Fraction

class DiscreteLaplacianVisualization(ForgeScene):
    def setup(self):
        self.t_values = [2.0, 2.0, 2.0]
        self.points = VGroup(*[Dot(point=RIGHT * i * 2, radius=0.15) for i in range(-1, 2)])
        self.labels = VGroup(*[DecimalNumber(v, num_decimal_places=1).next_to(p, UP) 
                               for v, p in zip(self.t_values, self.points)])

    @beat("Introduce the three points T1, T2, and T3", seconds=3, narration="It's the same value on the right hand side, but we're adding a new perspective to how to think about it.")
    def init_graph(self):
        line = Line(self.points[0].get_center(), self.points[2].get_center(), stroke_width=2)
        self.play(Create(line), FadeIn(self.points), Write(self.labels))

    @beat("Label the differences between adjacent points", seconds=4, narration="Instead of comparing the average of the neighbors to T2, we're thinking about the difference of the differences.")
    def show_deltas(self):
        d1 = Tex(r"$\Delta_1 = T_2 - T_1$", color=BLUE).to_edge(UP, buff=1)
        d2 = Tex(r"$\Delta_2 = T_3 - T_2$", color=GREEN).next_to(d1, DOWN)
        self.play(Write(d1), Write(d2))

    @beat("Highlight the equilibrium state", seconds=4, narration="Here, take a moment to gut check that this makes sense. If those two differences are the same, then the average of T1 and T3 is the same as T2, so T2 will not tend to change.")
    def equilibrium(self):
        brace = Brace(self.points, DOWN)
        text = Tex(r"$\Delta_2 - \Delta_1 = 0 \implies \frac{T_1 + T_3}{2} = T_2$").next_to(brace, DOWN)
        self.play(Create(brace), Write(text))

    @beat("Animate T2 increasing due to positive curvature", seconds=4, narration="If delta T2 is bigger than delta T1, meaning the difference of the differences is positive, notice how the average of T1 and T3 is bigger than T2, so T2 tends to increase.")
    def increase_t2(self):
        new_val = 3.0
        new_label = DecimalNumber(new_val, num_decimal_places=1).next_to(self.points[1], UP)
        arrow = Arrow(self.points[1].get_center(), self.points[1].get_center() + UP * 1.5, color=YELLOW)

        self.play(
            FadeOut(self.labels[1]),
            FadeIn(new_label),
            self.points[1].animate.shift(UP * 1.5),
            GrowArrow(arrow)
        )
        self.labels[1] = new_label

    @beat("Summarize the visual intuition", seconds=3, narration="This curvature, the second derivative, acts as a force pushing T2 towards the average of its neighbors.")
    def summary(self):
        rect = SurroundingRectangle(self.points, color=YELLOW)
        self.play(Create(rect))
        self.wait(1)

    @beat("Final cleanup", seconds=2, narration="It is a beautiful way to visualize discrete heat diffusion.")
    def cleanup(self):
        self.play(FadeOut(self.points), FadeOut(self.labels), FadeOut(self.labels))
