from manim import *
from forge.beats import ForgeScene, beat

class NewtonsFractalZoom(ForgeScene):

    @beat(
        "Show a coarse grid of points representing initial guesses.",
        seconds=4,
        narration="Now as I've done it here, this isn't quite enough resolution to get the full story..."
    )
    def show_coarse_grid(self):
        self.dots = VGroup(*[
            Dot(point=[x, y, 0], radius=0.08, color=BLUE_C)
            for x in np.linspace(-3, 3, 7)
            for y in np.linspace(-2, 2, 5)
        ])
        self.play(FadeIn(self.dots, lag_ratio=0.02), run_time=3.5)

    @beat(
        "Show a much finer grid of initial guesses to increase resolution.",
        seconds=4,
        narration="...so let me show you what it would look like if we started with an even finer grid of initial guesses..."
    )
    def show_finer_grid(self):
        dense_dots = VGroup(*[
            Dot(point=[x, y, 0], radius=0.03, color=BLUE_D)
            for x in np.linspace(-4, 4, 35)
            for y in np.linspace(-2.5, 2.5, 25)
        ])
        self.play(Transform(self.dots, dense_dots), run_time=3.5)

    @beat(
        "Simulate applying Newton's method by shifting points toward root destinations.",
        seconds=4,
        narration="...and played the same game, applying Newton's method a whole bunch of times..."
    )
    def apply_newton_iterations(self):
        # Move dots slightly to simulate marching towards roots
        animations = []
        for dot in self.dots:
            pos = dot.get_center()
            # simple mock gravitational pull towards three mock roots at (-2,0), (2,0), (0,2)
            dx, dy, _ = pos
            if dx < 0:
                target = np.array([-2.0, 0.0, 0.0])
            elif dy > 1.0:
                target = np.array([0.0, 2.0, 0.0])
            else:
                target = np.array([2.0, 0.0, 0.0])
            new_pos = pos * 0.2 + target * 0.8
            animations.append(dot.animate.move_to(new_pos))

        self.play(AnimationGroup(*animations, lag_ratio=0.01), run_time=3.5)

    @beat(
        "Color each dot based on which root it lands on.",
        seconds=4,
        narration="...letting each root march forward, coloring each dot based on what root it lands on..."
    )
    def color_by_root(self):
        color_anims = []
        for dot in self.dots:
            x, y, _ = dot.get_center()
            if x < -0.5:
                c = RED_C
            elif y > 0.5:
                c = GREEN_C
            else:
                c = YELLOW_C
            color_anims.append(dot.animate.set_color(c))
        self.play(AnimationGroup(*color_anims, lag_ratio=0.005), run_time=3.5)

    @beat(
        "Roll back the clock to see the original starting positions with their assigned colors.",
        seconds=4,
        narration="...then rolling back the clock to see where it originally came from."
    )
    def rollback_clock(self):
        # Reset dots back to their original grid positions while keeping their new root colors
        animations = []
        i = 0
        for x in np.linspace(-4, 4, 35):
            for y in np.linspace(-2.5, 2.5, 25):
                dot = self.dots[i]
                animations.append(dot.animate.move_to([x, y, 0]))
                i += 1
        self.play(AnimationGroup(*animations, lag_ratio=0.005), run_time=3.5)

    @beat(
        "Zoom in or emphasize that even this resolution reveals intricate boundaries.",
        seconds=3,
        narration="But even this isn't really a high enough resolution to appreciate the pattern."
    )
    def final_emphasis(self):
        self.play(self.dots.animate.scale(1.2), run_time=2.5)
