from manim import *
from forge.beats import ForgeScene, beat
from fractions import Fraction

class HandshakeProblem(ForgeScene):
    n = 6
    people = VGroup()
    lines = VGroup()

    @beat("Initialize the group of people", seconds=3, narration="Imagine we have a group of people at a party. Let's start with six people arranged in a circle.")
    def setup_people(self):
        self.people = VGroup(*[Dot(radius=0.2, color=BLUE).move_to(
            2.5 * np.array([np.cos(t), np.sin(t), 0])
        ) for t in np.linspace(0, 2*PI, self.n, endpoint=False)])
        self.play(FadeIn(self.people, scale=0.5, lag_ratio=0.2))

    @beat("Highlight one person", seconds=3, narration="If we want to count how many handshakes occur, let's pick one person and see who they shake hands with.")
    def highlight_one(self):
        self.target = self.people[0]
        self.play(self.target.animate.set_color(YELLOW), run_time=1)
        self.wait(1)

    @beat("Draw handshakes for the first person", seconds=4, narration="This person shakes hands with everyone else in the group. Since there are six people total, that makes five handshakes.")
    def draw_first_set(self):
        self.lines = VGroup(*[Line(self.target.get_center(), p.get_center(), color=WHITE, stroke_opacity=0.5) 
                              for p in self.people[1:]])
        self.play(Create(self.lines), run_time=2)
        self.count_label = MathTex(r"5").to_edge(RIGHT)
        self.play(Write(self.count_label))

    @beat("Move to the next person", seconds=4, narration="Now, move to the next person. They have already shaken hands with the first, so we only count the remaining four new handshakes.")
    def draw_second_set(self):
        p2 = self.people[1]
        new_lines = VGroup(*[Line(p2.get_center(), p.get_center(), color=WHITE, stroke_opacity=0.5) 
                             for p in self.people[2:]])
        self.play(p2.animate.set_color(YELLOW), Create(new_lines))
        self.lines.add(*new_lines)
        self.count_label.become(MathTex(f"5 + 4").to_edge(RIGHT))
        self.play(Transform(self.count_label, MathTex(f"9").to_edge(RIGHT)))

    @beat("Show the pattern", seconds=4, narration="As we continue, each new person has fewer people left to shake hands with: three, then two, then one.")
    def show_pattern(self):
        # Remaining: 3, 2, 1
        self.count_label.become(MathTex(f"5 + 4 + 3 + 2 + 1").to_edge(RIGHT))
        self.play(Write(self.count_label))

    @beat("Sum the series", seconds=3, narration="Summing these up, five plus four plus three plus two plus one gives us fifteen unique handshakes.")
    def sum_series(self):
        total = sum(range(self.n))
        self.result = MathTex(f"Total = {total}").to_edge(RIGHT).shift(DOWN)
        self.play(ReplacementTransform(self.count_label.copy(), self.result))

    @beat("Introduce the formula", seconds=4, narration="There's a faster way to think about this. With six people, each person shakes five hands, but that counts every handshake twice.")
    def formula_logic(self):
        self.formula = MathTex(r"\frac{n(n-1)}{2}").scale(1.5).to_edge(LEFT)
        self.play(Write(self.formula))

    @beat("Plug in the numbers", seconds=4, narration="Plugging in our number, six times five divided by two confirms our result of fifteen.")
    def compute_formula(self):
        calc = MathTex(r"\frac{6 \times 5}{2} = 15").next_to(self.formula, DOWN)
        self.play(Write(calc))

    @beat("Final conclusion", seconds=3, narration="This handshake problem is a classic way to understand how to count pairs in any group.")
    def finish(self):
        self.play(FadeOut(self.lines), self.people.animate.set_color(BLUE))
        self.wait(2)
