        self.left_particles = self.get_particles(20, BLUE, [-4.5, -1.5, -2, 2])
        self.right_particles = self.get_particles(5, RED, [1.5, 4.5, -2, 2])
        self.play(Create(self.system), FadeIn(self.left_particles), FadeIn(self.right_particles))

