from manim import *
from forge.beats import ForgeScene, beat

class BipartiteMatchingExplanation(ForgeScene):
    left_nodes_data = [("A1", 1.5), ("A2", 0.5), ("A3", -0.5), ("A4", -1.5)]
    right_nodes_data = [("B1", 1.5), ("B2", 0.5), ("B3", -0.5), ("B4", -1.5)]

