        ("A1", "B1"), ("A1", "B2"),
        ("A2", "B2"), ("A2", "B3"),
        ("A3", "B2"), ("A3", "B4"),
        ("A4", "B3")
    ]

    @beat("Introduce the two disjoint sets of a bipartite graph", seconds=4, narration="A bipartite graph has its vertices divided into two separate groups, where edges only connect nodes from opposite sides.")
    def show_bipartite_sets(self):
        self.left_dots = VGroup(*[
            Dot(point=[-2.5, y, 0], color=BLUE, radius=0.15)
            for _, y in self.left_nodes_data
        ])
        self.right_dots = VGroup(*[
            Dot(point=[2.5, y, 0], color=GREEN, radius=0.15)
            for _, y in self.right_nodes_data
        ])

        left_labels = VGroup(*[
            Text(name, font_size=24, color=BLUE).next_to(dot, LEFT, buff=0.2)
            for (name, _), dot in zip(self.left_nodes_data, self.left_dots)
        ])
        right_labels = VGroup(*[
            Text(name, font_size=24, color=GREEN).next_to(dot, RIGHT, buff=0.2)
            for (name, _), dot in zip(self.right_nodes_data, self.right_dots)
        ])

        left_box = SurroundingRectangle(VGroup(self.left_dots, left_labels), color=BLUE, buff=0.4, stroke_width=2)
        right_box = SurroundingRectangle(VGroup(self.right_dots, right_labels), color=GREEN, buff=0.4, stroke_width=2)

        left_title = Text("Set A", font_size=28, color=BLUE).next_to(left_box, UP)
        right_title = Text("Set B", font_size=28, color=GREEN).next_to(right_box, UP)

        self.play(
            FadeIn(left_box), FadeIn(left_title),
            FadeIn(right_box), FadeIn(right_title),
            LaggedStart(*[FadeIn(d, scale=0.5) for d in self.left_dots], lag_ratio=0.1),
            LaggedStart(*[FadeIn(d, scale=0.5) for d in self.right_dots], lag_ratio=0.1),
            LaggedStart(*[Write(l) for l in left_labels], lag_ratio=0.1),
            LaggedStart(*[Write(l) for l in right_labels], lag_ratio=0.1),
            run_time=3.0
        )
        self.wait(1.0)

    @beat("Draw all possible edges between the two sets", seconds=4, narration="Here are all the possible connections or potential pairings between the items in Set A and Set B.")
    def show_all_edges(self):
        left_dict = {name: dot.get_center() for (name, _), dot in zip(self.left_nodes_data, self.left_dots)}
        right_dict = {name: dot.get_center() for (name, _), dot in zip(self.right_nodes_data, self.right_dots)}

        self.all_edges = VGroup(*[
            Line(left_dict[u], right_dict[v], stroke_width=2, stroke_opacity=0.4, color=WHITE)
            for u, v in self.edges_data
        ])

        self.play(
            LaggedStart(*[Create(e) for e in self.all_edges], lag_ratio=0.08),
            run_time=3.0
        )
        self.wait(1.0)

    @beat("Define a matching as a set of edges with no shared endpoints", seconds=4, narration="A matching is a subset of these edges where no two edges share a vertex, meaning each node is used at most once.")
    def explain_matching_definition(self):
        definition_text = Text("Matching: No shared endpoints", font_size=24, color=YELLOW).to_edge(UP)

        self.play(
            FadeOut(self.all_edges),
            Write(definition_text),
            run_time=1.5
        )
        self.def_text = definition_text
        self.wait(2.5)

    @beat("Highlight a valid matching on the graph", seconds=4, narration="For example, if we pair A1 with B1, A2 with B2, and A3 with B4, we form a valid matching of size three.")
    def show_valid_matching(self):
        left_dict = {name: dot.get_center() for (name, _), dot in zip(self.left_nodes_data, self.left_dots)}
        right_dict = {name: dot.get_center() for (name, _), dot in zip(self.right_nodes_data, self.right_dots)}

        matching_pairs = [("A1", "B1"), ("A2", "B2"), ("A3", "B4")]

        self.matching_lines = VGroup(*[
            Line(left_dict[u], right_dict[v], stroke_width=5, color=YELLOW)
            for u, v in matching_pairs
        ])

        matching_count = len(matching_pairs)
        count_label = Text(f"Size: {matching_count}", font_size=28, color=YELLOW).next_to(self.def_text, DOWN, buff=0.2)

        self.play(
            LaggedStart(*[Create(line) for line in self.matching_lines], lag_ratio=0.15),
            Write(count_label),
            run_time=3.0
        )
        self.count_label = count_label
        self.wait(1.0)

    @beat("Achieve the maximum possible matching", seconds=4, narration="We can adjust our choices to find the maximum matching, pairing up all four elements from Set A to Set B completely.")
    def show_maximum_matching(self):
        left_dict = {name: dot.get_center() for (name, _), dot in zip(self.left_nodes_data, self.left_dots)}
        right_dict = {name: dot.get_center() for (name, _), dot in zip(self.right_nodes_data, self.right_dots)}

        max_pairs = [("A1", "B2"), ("A2", "B3"), ("A3", "B4"), ("A4", "B1")]

        new_matching_lines = VGroup(*[
            Line(left_dict[u], right_dict[v], stroke_width=5, color=GREEN_C)
            for u, v in max_pairs
        ])

        max_count = len(max_pairs)
        max_label = Text(f"Maximum Matching Size: {max_count}", font_size=28, color=GREEN_C).next_to(self.def_text, DOWN, buff=0.2)

        self.play(
            Transform(self.matching_lines, new_matching_lines),
            Transform(self.count_label, max_label),
            run_time=2.0
        )
        self.wait(2.0)
