        self.calc_box = MathTex(r"\frac{\partial L}{\partial w} = \frac{\partial L}{\partial a} \cdot \frac{\partial a}{\partial z} \cdot \frac{\partial z}{\partial w}", font_size=36).next_to(self.arrow, RIGHT)

