from manim import *
from forge.beats import ForgeScene, beat
import numpy as np

class FundamentalTheoremOfAlgebra(ForgeScene):
    def get_poly_path(self, n, radius=2.5, resolution=200):
        t = np.linspace(0, 2 * PI, resolution)
        # P(z) = z^n + lower_order_terms
        # For large radius, z^n dominates
        z = radius * np.exp(1j * t)
        w = z**n
        return VMobject().set_points_smoothly([
            np.array([w.real[i], w.imag[i], 0]) / (radius**n) * 2.0 
            for i in range(resolution)
        ])

    @beat("Introduce polynomial behavior", seconds=4, narration="So with the polynomial, for large enough inputs, every term other than the leading term becomes insignificant in comparison.")
    def show_dominance(self):
        self.plane = ComplexPlane(x_range=[-4, 4], y_range=[-3, 3], axis_config={"include_tip": False})
        self.n = 3
        self.label = MathTex(f"P(z) \\approx z^{{{self.n}}}").to_edge(UP)
        self.play(Create(self.plane), Write(self.label))

    @beat("Draw a large loop", seconds=4, narration="So any complex polynomial whose leading term is x to the n has a winding number of n around a large enough loop.")
    def draw_loop(self):
        self.circle = Circle(radius=2, color=BLUE)
        self.dot = Dot(self.circle.get_start())
        self.play(Create(self.circle), FadeIn(self.dot))
        self.play(MoveAlongPath(self.dot, self.circle), run_time=2)

    @beat("Map the loop", seconds=4, narration="As we trace this loop in the input plane, the output traces a path that winds around the origin.")
    def map_loop(self):
        self.image = self.get_poly_path(self.n)
        self.image.set_color(YELLOW)
        self.play(Create(self.image))

    @beat("Visualize the winding", seconds=4, narration="Because the leading term is z to the n, the output curve wraps around the origin exactly n times.")
    def show_winding(self):
        count_text = Text(f"Winding Number = {self.n}", font_size=36, color=YELLOW).to_edge(RIGHT)
        self.play(Write(count_text))
        self.wait(2)

    @beat("Shrink the loop", seconds=4, narration="In that way, our winding number technology actually guarantees that every complex polynomial has a zero.")
    def shrink_loop(self):
        small_circle = Circle(radius=0.2, color=RED)
        small_image = self.get_poly_path(self.n, radius=0.2)
        small_image.set_color(RED)
        self.play(Transform(self.circle, small_circle), Transform(self.image, small_image))
        self.zero_dot = Dot(color=RED).scale(1.5)
        self.play(FadeIn(self.zero_dot))

    @beat("Conclusion", seconds=3, narration="If the winding number must change as we shrink the loop to a point, it must pass through the origin, revealing a root.")
    def conclusion(self):
        conclusion_text = Text("Root exists!", color=RED).next_to(self.zero_dot, UP)
        self.play(Write(conclusion_text), Indicate(self.zero_dot))
