        self.wave2 = self.axes.plot(lambda x: np.sin(2*x), color=GREEN)

        self.play(Create(self.wave1), Create(self.wave2))

    @beat("Multiply the waves together", seconds=3, narration="When we multiply these two functions together")
    def multiply_waves(self):
