        integral2 = sum(np.sin(2*x) for x in np.linspace(-3, 3, 1000)) * (6/1000)
        integral_labels = VGroup(
            MathTex(r"\int_{-3}^{3} \sin(x) \, dx", "=", str(round(integral1, 2)), font_size=24),
