class GridLimitParadox(ForgeScene):
    def get_grid_val(self, row, col):
        return 7 if col == row else 1

    @beat("Initialize the infinite grid visual", seconds=3, narration="So we've got a grid here where every row has a single 7 and then a whole bunch of ones.")
    def show_grid(self):
        self.grid = VGroup()
        for r in range(5):
            row = VGroup()
            for c in range(5):
                val = self.get_grid_val(r, c)
                sq = Square(side_length=0.7, fill_opacity=0.3, fill_color=BLUE if val == 1 else RED)
                txt = MathTex(str(val), font_size=30).move_to(sq.get_center())
                row.add(VGroup(sq, txt))
            row.arrange(RIGHT, buff=0.1)
            self.grid.add(row)
        self.grid.arrange(DOWN, buff=0.1).shift(LEFT * 2)
        self.play(Create(self.grid), run_time=2)

    @beat("Highlight row products", seconds=3, narration="So if you were to take the infinite product of each row, you just get 7 for each one of them.")
    def row_products(self):
        self.row_labels = VGroup()
        for i, row in enumerate(self.grid):
            prod = 1
            for j in range(5):
                prod *= self.get_grid_val(i, j)
            label = MathTex(r"= " + str(prod), font_size=30).next_to(row, RIGHT)
            self.row_labels.add(label)
        self.play(LaggedStart(*[Write(l) for l in self.row_labels], lag_ratio=0.2), run_time=2)

    @beat("Show limit of products", seconds=3, narration="So since every one of these products is 7, the limit of the products is also 7.")
    def limit_of_products(self):
        self.limit_res = MathTex(r"\lim_{n \to \infty} (\text{Row}_n) = 7", font_size=36).to_edge(RIGHT).shift(UP * 1.5)
        self.play(Write(self.limit_res), run_time=2)

    @beat("Highlight columns", seconds=3, narration="But look at what happens if you take the limits first.")
    def highlight_columns(self):
        self.col_rects = VGroup()
        for j in range(5):
            col = VGroup(*[self.grid[i][j] for i in range(5)])
