from manim import *
from forge.beats import ForgeScene, beat
from forge.primitives.grid import Board, Cell

class ContactTracingExplainer(ForgeScene):
    board = Board(6, 6)

    def xy(self, cell):
        x = -4.5 + (cell.col - 2.5) * 0.9
        y = (cell.row - 2.5) * 0.9
        return np.array([x, y, 0.0])

    @beat("Setup the population grid representing people", seconds=3, narration="Not infected yet, infected and contagious but with no symptoms...")
    def setup_population(self):
        self.squares = VGroup(*[
            Square(side_length=0.8, stroke_width=1, stroke_color=GRAY, fill_opacity=1,
                   fill_color=BLUE_E).move_to(self.xy(c))
            for c in self.board.cells()])

        title = Text("Population", font_size=24, color=WHITE).to_corner(UP + RIGHT)
        self.play(
            LaggedStart(*[FadeIn(s, scale=0.5) for s in self.squares], lag_ratio=0.01, run_time=2.0),
            FadeIn(title, shift=LEFT),
            run_time=2.5
        )

    @beat("Show asymptomatic spreader", seconds=3, narration="...and infected, contagious and showing symptoms.")
    def show_asymptomatic(self):
        self.spreader_cell = Cell(2, 2)
        idx = 0
        for i, c in enumerate(self.board.cells()):
            if c.row == self.spreader_cell.row and c.col == self.spreader_cell.col:
                idx = i
                break

        self.spreader_square = self.squares[idx]
        new_sq = Square(side_length=0.8, stroke_width=2, stroke_color=YELLOW, fill_opacity=1,
                        fill_color=YELLOW_D).move_to(self.xy(self.spreader_cell))

        label = Text("Asymptomatic\n& Contagious", font_size=20, color=YELLOW).to_corner(UP + RIGHT).shift(DOWN * 0.8)

        self.play(
            Transform(self.spreader_square, new_sq),
            FadeIn(label, shift=LEFT),
            run_time=2.0
        )

    @beat("Show spread to neighbors", seconds=3, narration="The problem is that the virus still spreads because of all the contacts...")
    def show_spread(self):
        # Manually determine von Neumann or Moore neighborhood using valid board cells
        neighbors = []
        for c in self.board.cells():
            if abs(c.row - self.spreader_cell.row) <= 1 and abs(c.col - self.spreader_cell.col) <= 1:
                if not (c.row == self.spreader_cell.row and c.col == self.spreader_cell.col):
                    neighbors.append(c)

        self.neighbor_squares = VGroup()

        anims = []
        for n in neighbors:
            idx = 0
            for i, c in enumerate(self.board.cells()):
                if c.row == n.row and c.col == n.col:
                    idx = i
                    break
            sq = self.squares[idx]
            new_sq = Square(side_length=0.8, stroke_width=1, stroke_color=RED, fill_opacity=1,
                            fill_color=RED_D).move_to(self.xy(n))
            self.neighbor_squares.add(new_sq)
            anims.append(Transform(sq, new_sq))

        label = Text(f"{len(neighbors)} new infections", font_size=20, color=RED).to_corner(UP + RIGHT).shift(DOWN * 1.6)

        self.play(
            *anims,
            FadeIn(label, shift=LEFT),
            run_time=2.5
        )
        self.stored_neighbors = neighbors

    @beat("Show symptoms appearing", seconds=3, narration="If you have widespread testing, you can get people to self-isolate as soon as they show symptoms.")
    def show_symptoms(self):
        symptomatic_sq = Square(side_length=0.8, stroke_width=2, stroke_color=PURPLE, fill_opacity=1,
                                fill_color=PURPLE_D).move_to(self.xy(self.spreader_cell))

        label = Text("Shows Symptoms\n& Isolates", font_size=20, color=PURPLE).to_corner(UP + RIGHT).shift(DOWN * 2.4)

        self.play(
            Transform(self.spreader_square, symptomatic_sq),
            FadeIn(label, shift=LEFT),
