import numpy as np

class PlateauShrinking(ForgeScene):
    def get_plateau(self, width):
        return Line(start=LEFT * (width / 2), end=RIGHT * (width / 2), color=BLUE, stroke_width=8)

    @beat("The plateau gets smaller by that 1 over 7.", seconds=3, narration="The plateau gets smaller by that 1 over 7.")
    def step_one(self):
        self.plateau = self.get_plateau(4)
        self.label = MathTex(r"w = 1").next_to(self.plateau, UP)
        self.play(Create(self.plateau), Write(self.label))

        new_width = 4 * (1 - 1/7)
        new_plateau = self.get_plateau(new_width)
        self.play(Transform(self.plateau, new_plateau), 
                  Transform(self.label, MathTex(r"w = 6/7").next_to(new_plateau, UP)))

    @beat("Doing one more iteration with 1 over 9, the plateau gets smaller by that amount.", seconds=3, narration="Doing one more iteration with 1 over 9, the plateau gets smaller by that amount.")
    def step_two(self):
        current_w = 4 * (1 - 1/7)
        new_width = current_w * (1 - 1/9)
        new_plateau = self.get_plateau(new_width)
        self.play(Transform(self.plateau, new_plateau),
                  Transform(self.label, MathTex(r"w = 16/3 \cdot \dots").next_to(new_plateau, UP)))

    @beat("And as we keep going the plateau gets thinner and thinner.", seconds=3, narration="And as we keep going the plateau gets thinner and thinner.")
    def shrink_further(self):
        final_plateau = self.get_plateau(0.5)
        self.play(self.plateau.animate.set_width(0.5),
                  self.label.animate.next_to(final_plateau, UP).become(MathTex(r"w \to 0").next_to(final_plateau, UP)))

    @beat("And also notice how just outside of the plateau the function is really really close to 1", seconds=3, narration="And also notice how just outside of the plateau the function is really really close to 1 because it's always been the result of an average.")
    def visualize_neighbors(self):
        self.bg_line = Line(LEFT*4, RIGHT*4, color=GRAY, stroke_width=4).shift(DOWN*2)
        self.left_neighbor = Line(LEFT*4, self.plateau.get_left(), color=YELLOW, stroke_width=6).shift(DOWN*2)
        self.right_neighbor = Line(self.plateau.get_right(), RIGHT*4, color=YELLOW, stroke_width=6).shift(DOWN*2)
        self.play(Create(self.bg_line), Create(self.left_neighbor), Create(self.right_neighbor))

    @beat("The point at which all of this breaks is once we get to the iteration where we're sliding a window with width 1 15th", seconds=4, narration="The point at which all of this breaks is once we get to the iteration where we're sliding a window with width 1 15th across the whole thing.")
    def window_sliding(self):
        self.window = Rectangle(width=1/15 * 4, height=1, color=RED).shift(LEFT*2 + DOWN*2)
        self.window_label = MathTex(r"w = 1/15", color=RED).next_to(self.window, UP)
        self.play(Create(self.window), Write(self.window_label))
        self.play(self.window.animate.shift(RIGHT*4), run_time=2, rate_func=linear)

    @beat("Final summary of the process.", seconds=3, narration="This iterative averaging eventually collapses the structure entirely.")
    def conclusion(self):
        self.play(FadeOut(self.plateau), FadeOut(self.bg_line), FadeOut(self.left_neighbor), 
                  FadeOut(self.right_neighbor), FadeOut(self.window), FadeOut(self.window_label), FadeOut(self.label))
        final_text = Text("Convergence to 1", font_size=48).center()
        self.play(Write(final_text))
