from manim import *
from forge.beats import ForgeScene, beat
import math

class DirichletPrimes(ForgeScene):
    def get_primes(self, n):
        primes = []
        for i in range(2, n + 1):
            if all(i % j != 0 for j in range(2, int(math.sqrt(i)) + 1)):
                primes.append(i)
        return primes

    @beat("Introduce the set of primes up to x", seconds=3, narration="It's essentially what we just saw for 10, but more general. Again, you look at all the primes up to some bound x.")
    def show_primes(self):
        self.primes = self.get_primes(50)
        self.prime_group = VGroup(*[Text(str(p), font_size=24) for p in self.primes])
        self.prime_group.arrange_in_grid(5, 5, buff=0.4).shift(LEFT * 2.5)
        self.play(Write(self.prime_group), run_time=2)

    @beat("Define n and r notation", seconds=3, narration="But instead of asking for what proportion of them have a residue of, say, 1 mod 10, you ask what proportion have a residue of r mod n.")
    def show_residue(self):
        self.n_val = 12
        self.r_val = 5
        self.label = MathTex(r"p \equiv r \pmod{n}", font_size=48).to_edge(RIGHT, buff=1)
        self.params = MathTex(f"n={self.n_val}, r={self.r_val}", font_size=36).next_to(self.label, DOWN)
        self.play(Write(self.label), Write(self.params))

    @beat("Highlight co-primed condition", seconds=3, narration="Where n is any number, and r is anything that's co-primed to n.")
    def show_coprime(self):
        gcd = math.gcd(self.r_val, self.n_val)
        self.gcd_text = Text(f"gcd({self.r_val}, {self.n_val}) = {gcd}", font_size=32, color=YELLOW).next_to(self.params, DOWN)
        self.play(Write(self.gcd_text))

    @beat("Explain the condition", seconds=3, narration="Remember, that means it doesn't share any factors with n bigger than 1.")
    def explain_coprime(self):
        factors_n = [i for i in range(1, self.n_val + 1) if self.n_val % i == 0]
        factors_r = [i for i in range(1, self.r_val + 1) if self.r_val % i == 0]
        fact_text = Text(f"Factors: {factors_n} vs {factors_r}", font_size=24).next_to(self.gcd_text, DOWN)
        self.play(FadeIn(fact_text))
        self.wait(1)

    @beat("Filter primes by congruence", seconds=3, narration="We are looking for primes p where p mod n equals r.")
    def filter_primes(self):
        targets = VGroup()
        for p_mob in self.prime_group:
            p = int(p_mob.text)
            if p % self.n_val == self.r_val:
                p_mob.set_color(RED)
                targets.add(p_mob)
        self.play(Indicate(targets), run_time=2)

    @beat("Conclusion summary", seconds=3, narration="This is the core of Dirichlet's theorem on arithmetic progressions.")
    def summary(self):
        count = sum(1 for p in self.primes if p % self.n_val == self.r_val)
        final_text = Text(f"Count: {count}", font_size=36).move_to(self.label.get_center() + DOWN * 3)
        self.play(Write(final_text))
