from manim import *
from forge.beats import ForgeScene, beat
from fractions import Fraction

class PrimeResidueSpiral(ForgeScene):
    def get_pos(self, n, modulus=44):
        # Archimedean spiral mapping for number n
        angle = n * 0.3
        radius = 0.15 * np.sqrt(n)
        return radius * np.array([np.cos(angle), np.sin(angle), 0])

    @beat("Introduce the spiral of integers modulo 44", seconds=4, narration="Maybe now you can tell me what happens when we limit our view to prime numbers.")
    def setup_spiral(self):
        self.dots = VGroup()
        for i in range(1, 101):
            color = BLUE if i > 1 else GRAY
            dot = Dot(self.get_pos(i), color=color, radius=0.06)
            self.dots.add(dot)
        self.play(Create(self.dots, run_time=3))

    @beat("Highlight multiples of 44 and even residues", seconds=4, narration="Primes cannot be a multiple of 44, so that arm won't be visible. Nor can a prime be 2 above a multiple of 44, or 4 above, and so on, since all those residue classes have nothing but even numbers.")
    def hide_evens(self):
        to_hide = VGroup()
        for i in range(1, 101):
            if i % 2 == 0:
                to_hide.add(self.dots[i-1])
        self.play(FadeOut(to_hide, scale=0.5), run_time=3)

    @beat("Explain multiples of 11 exclusion", seconds=4, narration="Likewise, any multiples of 11 can't be prime, except for 11 itself, so the spiral of numbers 11 above a multiple of 44 won't be visible.")
    def hide_eleven_arm(self):
        to_hide = VGroup()
        for i in range(1, 101):
            if i % 11 == 0 and i != 11:
                to_hide.add(self.dots[i-1])
        self.play(FadeOut(to_hide, scale=0.5), run_time=3)

    @beat("Hide the 33 residue class", seconds=4, narration="And neither will the spiral of numbers 33 above a multiple of 44.")
    def hide_thirty_three_arm(self):
        to_hide = VGroup()
        for i in range(1, 101):
            if i % 44 == 33:
                to_hide.add(self.dots[i-1])
        self.play(FadeOut(to_hide, scale=0.5), run_time=3)

    @beat("Identify the remaining dots as potential primes", seconds=4, narration="What remains are the residues coprime to 44, the only places where primes can possibly reside in this projection.")
    def show_remaining(self):
        remaining = VGroup(*[d for d in self.dots if d.fill_opacity > 0])
        self.play(Indicate(remaining, color=YELLOW), run_time=3)

    @beat("Summary label", seconds=3, narration="By filtering the spiral, we isolate the arithmetic structure of prime distributions.")
    def conclusion(self):
        label = Text("Residues coprime to 44", font_size=36).to_edge(RIGHT)
        self.play(Write(label), run_time=2)
        self.wait(1)
