from manim import *
from forge.beats import ForgeScene, beat
import numpy as np

class FunctionContinuity(ForgeScene):
    def setup(self):
        self.input_plane = NumberPlane(
            x_range=[-2, 2, 1], y_range=[-2, 2, 1], 
            x_length=4, y_length=4
        ).shift(LEFT * 3)

        self.output_plane = NumberPlane(
            x_range=[-2, 2, 1], y_range=[-2, 2, 1], 
            x_length=4, y_length=4
        ).shift(RIGHT * 3)

        self.input_dot = Dot(color=BLUE).move_to(self.input_plane.c2p(0.5, 0.5))
        self.output_dot = Dot(color=YELLOW).move_to(self.output_plane.c2p(0, 0.5))

    @beat("Introduce side-by-side input and output spaces", seconds=4, narration="One is to just look at both the input space and the output space side by side.")
    def show_spaces(self):
        self.play(Create(self.input_plane), Create(self.output_plane))
        self.play(FadeIn(self.input_dot), FadeIn(self.output_dot))

    @beat("Show mapping relationship", seconds=4, narration="Each point in the input space moves to a particular point in the output space.")
    def show_mapping(self):
        arrow = Arrow(
            start=self.input_dot.get_center(), 
            end=self.output_dot.get_center(), 
            color=WHITE, buff=0.2
        )
        self.play(GrowArrow(arrow))
        self.wait(2)
        self.play(FadeOut(arrow))

    @beat("Animate input movement", seconds=4, narration="and I can show how moving around that input point corresponds to certain movements in the output space.")
    def animate_movement(self):
        path = Circle(radius=0.3, color=BLUE).move_to(self.input_plane.c2p(0.5, 0.5))
        self.play(Create(path))

        # Mapping f(z) = z^2: u = x^2 - y^2, v = 2xy
        def update_output(m):
            coords = self.input_plane.p2c(self.input_dot.get_center())
            x, y = coords[0], coords[1]
            u, v = x**2 - y**2, 2*x*y
            m.move_to(self.output_plane.c2p(u, v))

        self.output_dot.add_updater(update_output)
        self.play(MoveAlongPath(self.input_dot, path), run_time=3, rate_func=linear)
        self.input_dot.clear_updaters()
        self.output_dot.clear_updaters()
        self.play(FadeOut(path))

    @beat("Define continuous function", seconds=4, narration="All of the functions we consider will be continuous,")
    def define_continuity(self):
        text = Text("Continuous", font_size=36, color=GREEN).to_edge(UP)
        self.play(Write(text))

    @beat("Visualize small changes", seconds=4, narration="in the sense that small little changes to the input only correspond to small little changes in the output,")
    def visualize_small_changes(self):
        circle = Circle(radius=0.1, color=WHITE).move_to(self.input_dot)
