    def decompose_complex(self):
        self.play(self.white_wave.animate.set_stroke(opacity=0.3))
        self.components = VGroup(*[
            self.axes.plot(lambda x, freq=f: 0.4 * np.sin(freq * x), color=c)
            for f, c in zip([2, 5, 8], [RED, GREEN, BLUE])
        ]).arrange(DOWN, buff=0.2).next_to(self.axes, RIGHT, buff=1)
        self.play(LaggedStart(*[Create(c) for c in self.components], lag_ratio=0.5))

    @beat("Explain the rainbow components", seconds=3, narration="And you typically think about it as a combination of many different pure sine waves, each one corresponding to one of the colors in the rainbow.")
    def show_rainbow(self):
        colors = [RED, ORANGE, YELLOW, GREEN, BLUE, PURPLE]
        rainbow = VGroup(*[Line(UP*0.5, DOWN*0.5, color=c) for c in colors]).arrange(RIGHT, buff=0.1)
