        self.play(FadeIn(rainbow))
        self.rainbow = rainbow

    @beat("Transition to schematic representation", seconds=3, narration="For this animation I will schematically represent the wiggling direction for each pure frequency, just with a line.")
    def schematic_intro(self):
        self.play(FadeOut(self.white_wave, self.components, self.axes))
        self.lines = VGroup(*[
            Line(ORIGIN, UP * 1.5, color=c, stroke_width=6)
            for c in [RED, GREEN, BLUE]
        ]).arrange(RIGHT, buff=1.5)
        self.play(self.rainbow.animate.next_to(self.lines, UP, buff=1))
        self.play(Create(self.lines))

