        self.play(FadeOut(self.square), FadeOut(self.side_pairs))
        self.play(Create(self.cube))

    @beat("Isolate the top layer", seconds=3, narration="The top square gets split into two separate subsets, each unaffected by a 180 degree rotation.")
    def top_layer(self):
        top_face = Square(side_length=2.5).set_fill(BLUE, 0.5).rotate(PI/6, axis=UP).rotate(PI/6, axis=RIGHT).shift(UP*1.25)
        self.subsets = VGroup(
