from manim import *
from forge.beats import ForgeScene, beat
from fractions import Fraction

class HammingCodeRefresher(ForgeScene):
    def get_bit_group(self, n, status="data"):
        bits = VGroup()
        for i in range(n):
            color = BLUE if status == "data" else RED
            sq = Square(side_length=0.6, fill_opacity=0.5, fill_color=color)
            val = Text(str(i % 2), font_size=24).move_to(sq.get_center())
            bits.add(VGroup(sq, val))
        return bits.arrange(RIGHT, buff=0.1)

    @beat("Introduce the Hamming block structure", seconds=4, narration="We were talking about Hamming codes, a way to create a block of data where most of the bits carry a meaningful message, while a few others act as a kind of redundancy.")
    def show_block(self):
        self.data_bits = self.get_bit_group(4, "data").shift(UP * 1)
        self.red_bits = self.get_bit_group(3, "redundancy").next_to(self.data_bits, DOWN, buff=0.5)

        label_data = Text("Message Bits", font_size=24).next_to(self.data_bits, LEFT)
        label_red = Text("Redundancy", font_size=24).next_to(self.red_bits, LEFT)

        self.play(Create(self.data_bits), Create(self.red_bits), Write(label_data), Write(label_red))

    @beat("Simulate a bit flip", seconds=3, narration="If any bit gets flipped, either a message bit or a redundancy bit, anything in this block...")
    def bit_flip(self):
        target = self.data_bits[2]
        self.play(target.animate.set_color(YELLOW), run_time=1)
        self.play(target.animate.shift(UP * 0.5), run_time=1)

    @beat("The receiver's detection", seconds=3, narration="...a receiver is going to be able to identify that there was an error, and how to fix it.")
    def detection(self):
        arrow = Arrow(start=UP*0.5, end=DOWN*0.5, color=YELLOW).next_to(self.data_bits[2], UP)
        text = Text("Error Detected!", font_size=30, color=YELLOW).next_to(arrow, UP)
        self.play(GrowArrow(arrow), Write(text))

    @beat("Visualizing parity checks", seconds=4, narration="The basic idea presented there was how to use multiple parity checks...")
    def parity_checks(self):
        self.checks = VGroup(*[Circle(radius=0.3, color=GREEN).move_to(self.data_bits[i]) for i in range(0, 4, 2)])
        self.play(FadeIn(self.checks))

    @beat("The binary search mechanism", seconds=3, narration="...to binary search your way down to the error.")
    def binary_search(self):
        path = VGroup(
            Line(self.checks[0].get_center(), self.data_bits[2].get_center(), color=WHITE),
            Line(self.checks[1].get_center(), self.data_bits[2].get_center(), color=WHITE)
        )
        self.play(Create(path))

    @beat("Conclusion summary", seconds=3, narration="This structure ensures that redundancy is not just overhead, but a diagnostic tool.")
    def summary(self):
        summary_text = Text("Redundancy = Diagnostic Ability", font_size=36, color=BLUE)
        self.play(FadeOut(self.data_bits, self.red_bits, self.checks), Write(summary_text))
