        return np.array([self.radius * np.cos(angle), self.radius * np.sin(angle), 0])

    @beat("Set up the lighthouses on a circle", seconds=3, narration="If you remove one of those lighthouses and put the observer in its place.")
    def setup_lighthouses(self):
        self.points = [self.get_coords(i) for i in range(self.n)]
        self.dots = VGroup(*[Dot(p, color=BLUE) for p in self.points])
        self.circle = Circle(radius=self.radius, color=GRAY, stroke_opacity=0.5)
        self.observer = Dot(self.points[0], color=YELLOW, radius=0.15)

        self.play(Create(self.circle), FadeIn(self.dots[1:]), FadeIn(self.observer), run_time=2)

    @beat("Draw distance lines to the observer", seconds=4, narration="This distance product from all the remaining lighthouses...")
    def draw_distances(self):
        self.lines = VGroup(*[
            Line(self.observer.get_center(), self.dots[i].get_center(), color=YELLOW_D, stroke_width=2)
            for i in range(1, self.n)
        ])
        self.labels = VGroup(*[
            MathTex(f"d_{i}", font_size=24).move_to(line.get_center() + UP * 0.2)
            for i, line in enumerate(self.lines, 1)
        ])
        self.play(Create(self.lines), Write(self.labels), run_time=3)

    @beat("Show the product formula", seconds=3, narration="...equals the number of lighthouses you started with.")
