        self.play(Write(self.reaction), run_time=2)

    @beat("Final cleanup", seconds=2, narration="It's a beautiful geometric property.")
    def cleanup(self):
        self.play(FadeOut(self.lines), FadeOut(self.labels), FadeOut(self.reaction), run_time=1.5)
