class CubeVertices(ForgeScene, ThreeDScene):
    @beat("Initialize 3D camera", seconds=2, narration="To start off, it helps to put some numbers to the way they were thinking about a cube.")
    def setup_scene(self):
        self.set_camera_orientation(phi=75 * DEGREES, theta=-45 * DEGREES)
        self.axes = ThreeDAxes(x_range=[0, 1.5], y_range=[0, 1.5], z_range=[0, 1.5], axis_config={"include_tip": True})
        self.play(Create(self.axes))

    @beat("Place the origin vertex", seconds=3, narration="One natural choice is to put it in 3D space such that one vertex sits at the origin, coordinates 0, 0, 0.")
    def mark_origin(self):
        origin_dot = Dot3D(point=self.axes.c2p(0, 0, 0), color=YELLOW)
        label = MathTex("(0,0,0)").next_to(origin_dot, DOWN)
        self.play(FadeIn(origin_dot), Write(label))
        self.origin_dot = origin_dot
        self.label = label

    @beat("Generate all vertices", seconds=4, narration="And then all of the other vertices are kind of every combination of 0s and 1s that you can come up with.")
    def generate_vertices(self):
        self.points = list(itertools.product([0, 1], repeat=3))
        self.dots = VGroup(*[Dot3D(point=self.axes.c2p(x, y, z), color=BLUE) for x, y, z in self.points])
        self.play(LaggedStart(*[FadeIn(d) for d in self.dots], lag_ratio=0.1))

    @beat("Draw the edges", seconds=3, narration="Connecting these points reveals the structure of a unit cube.")
    def draw_edges(self):
        edges = VGroup()
        for p1 in self.points:
            for p2 in self.points:
                dist = sum((a - b) ** 2 for a, b in zip(p1, p2))
                if dist == 1:
                    edges.add(Line(self.axes.c2p(*p1), self.axes.c2p(*p2), color=WHITE, stroke_width=2))
        self.play(Create(edges))
        self.edges = edges

    @beat("Label the cube", seconds=3, narration="Each vertex is uniquely defined by its coordinates in three-dimensional space.")
    def label_vertices(self):
        labels = VGroup()
        for p in self.points:
            text = MathTex(str(p), font_size=24).next_to(self.axes.c2p(*p), UP + RIGHT, buff=0.1)
            labels.add(text)
        self.play(Write(labels), run_time=2)

    @beat("Final rotation", seconds=3, narration="This setup gives us a perfect foundation to explore the properties of this 3D shape.")
    def rotate_view(self):
        self.begin_ambient_camera_rotation(rate=0.5)
        self.wait(3)
        self.stop_ambient_camera_rotation()
