        self.play(Create(self.axes), Create(self.circle), FadeIn(self.dot), Write(self.label))

    @beat("Rotate the board to show invariance", seconds=3, narration="So on a dartboard with everybody aiming for the bullseye, this would mean that you could rotate the board and it would make no difference for the distribution.")
    def rotate_board(self):
        rotation_group = VGroup(self.dot, self.label)
        self.play(Rotate(rotation_group, angle=PI/2, about_point=self.axes.c2p(0, 0)), run_time=2)

    @beat("Define the radius r", seconds=3, narration="Mathematically, this means that the function describing your probability distribution, which I'll call f2 since it takes in two inputs x and y...")
    def define_f2(self):
        self.f2_text = MathTex("f_2(x, y)", font_size=48).to_edge(RIGHT).shift(UP*1)
        self.line = Line(start=self.axes.c2p(0, 0), end=self.axes.c2p(1, 0.5), color=RED)
        self.r_label = MathTex("r = \\sqrt{x^2 + y^2}", font_size=36, color=RED).next_to(self.line, DOWN)
        self.play(Write(self.f2_text), Create(self.line), Write(self.r_label))

    @beat("Transition to radial function", seconds=3, narration="...well it can be expressed as some single variable function of the radius r.")
    def transition_to_r(self):
        self.f_r_text = MathTex("g(r)", font_size=48, color=YELLOW).next_to(self.f2_text, DOWN)
        self.equals = MathTex("=", font_size=48).next_to(self.f2_text, DOWN).shift(LEFT*1)
        self.play(ReplacementTransform(self.f2_text.copy(), self.equals), Write(self.f_r_text))

    @beat("Highlight the radial dependency", seconds=3, narration="Since the density depends only on the distance from the center, the output remains identical for any point on the same circle.")
    def highlight_circle(self):
        new_dots = VGroup(*[Dot(point=self.axes.c2p(2*np.cos(theta), 2*np.sin(theta)), color=YELLOW) 
                           for theta in [np.pi/4, 3*np.pi/4, 5*np.pi/4, 7*np.pi/4]])
        self.play(FadeIn(new_dots))
        self.play(Indicate(self.f_r_text))

    @beat("Final summary", seconds=3, narration="This radial symmetry simplifies our calculations by reducing two dimensions down to one.")
    def summary(self):
        rect = SurroundingRectangle(VGroup(self.f_r_text, self.r_label), color=WHITE)
        self.play(Create(rect))
        self.wait(2)
