from manim import *
from forge.beats import ForgeScene, beat
import numpy as np

class WindingFrequencyMachine(ForgeScene):
    def get_winding(self, freq, t_max=10):
        # f(t) = cos(2*pi*2*t) + cos(2*pi*3*t)
        # Winding: exp(i * 2 * pi * winding_freq * t) * f(t)
        t = np.linspace(0, t_max, 500)
        signal = np.cos(2 * np.pi * 2 * t) + np.cos(2 * np.pi * 3 * t)
        winding = signal * np.exp(1j * 2 * np.pi * freq * t)
        return VGroup(*[Dot(point=np.array([w.real / 4, w.imag / 4, 0]), radius=0.02) for w in winding])

    @beat("Introduce the signal", seconds=3, narration="Like I said earlier, what you get is no longer a nice pure cosine wave, it's something a little more complicated.")
    def show_signal(self):
        axes = Axes(x_range=[0, 4, 1], y_range=[-2, 2, 1], axis_config={"include_tip": False}).scale(0.8).to_edge(LEFT)
        func = axes.plot(lambda t: np.cos(2 * np.pi * 2 * t) + np.cos(2 * np.pi * 3 * t), x_range=[0, 4])
        self.play(Create(axes), Create(func), run_time=2)
        self.signal = func
        self.axes = axes

    @beat("Winding the signal", seconds=3, narration="But imagine throwing this into our winding frequency machine. It is certainly the case that as you wrap this thing around it looks a lot more complicated.")
    def wrap_chaos(self):
        self.winding = self.get_winding(1.0).shift(RIGHT * 3)
        self.play(FadeOut(self.signal), FadeOut(self.axes), FadeIn(self.winding), run_time=2)

    @beat("Align at 2Hz", seconds=3, narration="You have this chaos and chaos and chaos and chaos, and then whoop, things seem to line up really nicely at 2 cycles per second.")
    def align_two(self):
        new_winding = self.get_winding(2.0).shift(RIGHT * 3)
        self.play(Transform(self.winding, new_winding), run_time=2)
        self.play(Indicate(self.winding, color=YELLOW), run_time=1)

    @beat("Return to chaos", seconds=3, narration="Then as you continue on it's more chaos and more chaos and more chaos and chaos and chaos and chaos,")
    def return_chaos(self):
        new_winding = self.get_winding(2.5).shift(RIGHT * 3)
        self.play(Transform(self.winding, new_winding), run_time=2)

    @beat("Align at 3Hz", seconds=3, narration="whoop, things nicely align again at 3 cycles per second.")
    def align_three(self):
        new_winding = self.get_winding(3.0).shift(RIGHT * 3)
        self.play(Transform(self.winding, new_winding), run_time=2)
        self.play(Indicate(self.winding, color=YELLOW), run_time=1)

    @beat("Final stability", seconds=2, narration="The center of mass shifts only when the winding frequency matches the signal frequency.")
    def finalize(self):
        center = Dot(point=RIGHT * 3, color=RED)
        self.play(FadeIn(center), run_time=1)
        self.wait(1)
