from manim import *
from forge.beats import ForgeScene, beat
import numpy as np

class MovingAverageIllustration(ForgeScene):
    @beat("Introduce the top graph and the window.", seconds=3, narration="The product on the bottom looks just like a copy of the top graph, but limited to a certain window.")
    def setup_graphs(self):
        # Use x_length and y_length instead of x_width and y_height
        axes_top = Axes(x_range=[-4, 4, 2], y_range=[0, 1.2, 1], x_length=6, y_length=2).shift(UP * 2)
        top_graph = axes_top.plot(lambda x: np.exp(-x**2), color=BLUE)
        top_box = Rectangle(width=1.5, height=2.5, color=YELLOW).move_to(axes_top.c2p(-2, 0.5))

        self.axes_top = axes_top
        self.top_graph = top_graph
        self.top_box = top_box

        group = VGroup(axes_top, top_graph, top_box)
        self.play(Create(group), run_time=2)

    @beat("Slide the window along the graph.", seconds=4, narration="Again, as I slide this around left and right and the area gets bigger and smaller, the result maxes out in the middle, but tapers out to either side, except this time it does so more smoothly.")
    def slide_window(self):
        self.play(self.top_box.animate.shift(RIGHT * 4), run_time=3, rate_func=linear)

    @beat("Show the integral result.", seconds=3, narration="It's kind of like we're taking a moving average of that top left graph.")
    def show_result(self):
        axes_bottom = Axes(x_range=[-4, 4, 2], y_range=[0, 1.2, 1], x_length=6, y_length=2).shift(DOWN * 1.5)
        res_graph = axes_bottom.plot(lambda x: 0.8 * np.exp(-x**2 / 1.5), color=RED)
        res_label = MathTex(r"\text{Moving Average}", font_size=30).next_to(axes_bottom, RIGHT)

        self.axes_bottom = axes_bottom
        self.res_graph = res_graph

        group = VGroup(axes_bottom, res_graph, res_label)
        self.play(Create(group), run_time=2)

    @beat("Highlight the connection.", seconds=3, narration="Actually, it's more than just kind of, this literally is a moving average of the top left graph.")
    def highlight_connection(self):
        rect = SurroundingRectangle(self.res_graph, color=WHITE)
        self.play(Create(rect), run_time=2)

    @beat("Overlay the graphs.", seconds=3, narration="When we view them together, the smoothing effect of the convolution becomes clear.")
    def overlay(self):
        self.play(
            FadeOut(self.top_box),
            self.res_graph.animate.set_color(GREEN),
            self.top_graph.animate.set_stroke(opacity=0.3),
            run_time=2
        )

    @beat("Final look at the smoothed curve.", seconds=2, narration="This is the nature of a moving average.")
    def conclusion(self):
        self.play(Indicate(self.res_graph), run_time=2)
